window.BANQUE_INFINI = {"module":"annee-1/theorique/semestre-2/eaif-2","titre":"EAIF II","sources":[{"t":"Exercices — Force","q":"qcm/qcm-exercices-force.html","f":"fiches/exercices-force.html"},{"t":"Exercices — Introduction","q":"qcm/qcm-exercices-intro.html","f":"fiches/exercices-intro.html"},{"t":"Exercices — Mobilité","q":"qcm/qcm-exercices-mobilite.html","f":"fiches/exercices-mobilite.html"},{"t":"Exercices — Pliométrie","q":"qcm/qcm-exercices-pliometrie.html","f":"fiches/exercices-pliometrie.html"},{"t":"Exercices — RSM","q":"qcm/qcm-exercices-rsm.html","f":"fiches/exercices-rsm.html"},{"t":"Exercices — Souplesse","q":"qcm/qcm-exercices-souplesse.html","f":"fiches/exercices-souplesse.html"},{"t":"Goniométrie Cours 1 — Concepts","q":"qcm/qcm-goniometrie-cours-1.html","f":"fiches/goniometrie-cours-1.html"},{"t":"Goniométrie Cours 2 — Procédures","q":"qcm/qcm-goniometrie-cours-2.html","f":"fiches/goniometrie-cours-2.html"},{"t":"Immobilisation Sélective","q":"qcm/qcm-immobilisation.html","f":"fiches/immobilisation-selective.html"},{"t":"Mob. Accessoire Cours 1","q":"qcm/qcm-mob-cours-1.html","f":"fiches/mob-cours-1.html"},{"t":"Mob. Accessoire Cours 2 — Maitland","q":"qcm/qcm-mob-cours-2.html","f":"fiches/mob-cours-2.html"},{"t":"Mob. Accessoire Cours 3 — Colonne vertébrale","q":"qcm/qcm-mob-cours-3.html","f":"fiches/mob-cours-3.html"},{"t":"Mob. Accessoire Cours 4 — Posture","q":"qcm/qcm-mob-cours-4.html","f":"fiches/mob-cours-4.html"},{"t":"Test musculaire","q":"qcm/qcm-testing.html","f":"fiches/testing.html"}],"questions":[{"q":"Combien de principes fondamentaux régissent l'entraînement musculaire ?","o":["2","3","4","6"],"r":2,"e":"4 principes : surcharge, spécificité, maintien/réversibilité, action retardée.","s":0},{"q":"Le principe de SURCHARGE stipule :","o":["Toujours utiliser sa charge maximale, dès la première séance","Une exigence progressive, au-delà de l'habituel","Toujours réduire la charge, à chaque séance","Aucun principe établi, au hasard"],"r":1,"e":"Surcharge progressive : ↑ exigence pour ↑ adaptation. Pour gagner en force, le muscle doit être surchargé.","s":0},{"q":"Le principe de SPÉCIFICITÉ :","o":["Tous les muscles s'entraînent identiquement","Seuls les systèmes sollicités s'adaptent","Chaque exercice a un seul effet","Pas de spécificité"],"r":1,"e":"Spécificité : adaptation des systèmes sollicités selon les besoins.","s":0},{"q":"Le principe de MAINTIEN / RÉVERSIBILITÉ :","o":["Les gains sont définitifs, une fois acquis","Sans exercice, le muscle revient à son état initial","Aucune perte n'est possible, même après un arrêt","La détérioration est toujours inévitable"],"r":1,"e":"Réversibilité : pertes en cas d'arrêt.","s":0},{"q":"Le principe d'ACTION RETARDÉE :","o":["Des résultats immédiats, dès la séance","Des résultats différés, par surcompensation","Une absence d'effet, quel que soit le programme suivi","Des effets aléatoires, imprévisibles"],"r":1,"e":"Surcompensation = adaptation différée.","s":0},{"q":"Les fibres de TYPE I sont :","o":["Rapides, glycolytiques et fatigables","Lentes, oxydatives et peu fatigables","Mixtes, entre lentes et rapides, selon l'entraînement","Inactives au repos, sans tonus"],"r":1,"e":"Type I = lentes, posturales, oxydatives, peu fatigables.","s":0},{"q":"Les fibres de TYPE IIb sont :","o":["Lentes, oxydatives et résistantes à la fatigue","Très rapides, glycolytiques et très fatigables","Aérobies, riches en mitochondries","Toniques et posturales, au repos"],"r":1,"e":"Type IIb = rapides explosives, anaérobies, fatigables. Elles utilisent aussi l'ATP-CP.","s":0},{"q":"Les fibres de TYPE IIa sont :","o":["Lentes et purement oxydatives","Intermédiaires, rapides et modérément fatigables","Identiques aux IIb, très fatigables","Aérobies pures, comme les fibres de type I des muscles posturaux"],"r":1,"e":"Type IIa = intermédiaires. Elles sont à la fois glycolytiques et oxydatives.","s":0},{"q":"Les mitochondries sont nombreuses dans :","o":["Les seules fibres de type IIb, glycolytiques","Les fibres de type I et IIa, oxydatives","Aucune fibre musculaire","Toutes les fibres, de façon égale"],"r":1,"e":"Type I et IIa = beaucoup de mitochondries (métabolisme oxydatif).","s":0},{"q":"La myoglobine est élevée dans :","o":["IIb","I et IIa","Aucune fibre","Indépendant du type"],"r":1,"e":"Myoglobine élevée dans les fibres oxydatives (I et IIa).","s":0},{"q":"Le système ATP-CP fournit l'énergie pour :","o":["Des efforts de 1 à 2 heures, comme le marathon ou le vélo","Des efforts de moins de 30 secondes, comme le sprint","Des efforts de 30 minutes","Aucun usage pratique, à l'effort"],"r":1,"e":"ATP-CP : 1/2 sec ATP, 2-10 sec CP. < 30 sec d'effort intense.","s":0},{"q":"La voie glycolytique (anaérobie lactique) couvre :","o":["Moins de 5 secondes, comme un saut ou un lancer bref","Jusqu'à 60 secondes, puis 1 à 3 minutes par le foie","Plus de 30 minutes, à faible intensité","Aucun type d'effort, au repos"],"r":1,"e":"Glycolyse : 30 sec - 3 min selon le glycogène. Le glycogène musculaire, puis hépatique, l'alimente.","s":0},{"q":"La voie aérobie (oxydative) est :","o":["Très limitée en capacité, de 10 s","Illimitée, avec les glucides puis les lipides","Inactive à l'effort, utilisée seulement pendant le sommeil","Uniquement anaérobie, sans oxygène"],"r":1,"e":"Aérobie : illimitée en capacité, mais puissance faible.","s":0},{"q":"Facteur limitant de la voie glycolytique :","o":["Le manque d'oxygène dans les mitochondries","L'acidose, qui inhibe la glycolyse","Le manque d'ATP disponible","Le manque de glucose, seul"],"r":1,"e":"Métabolites acides → acidose → inhibition. Elle est due aux ions H⁺ et à l'acide lactique.","s":0},{"q":"Un sprint 100 m utilise :","o":["L'ATP-PC, principalement","La glycolyse, secondairement","La voie aérobie, principalement","Les lipides, secondairement"],"r":[0,1],"e":"Effort < 30 sec : ATP-PC, glycolytique en complément.","s":0},{"q":"Un marathon utilise principalement :","o":["L'ATP-PC, en continu, au long cours","La glycolyse anaérobie, avec production de lactate","L'aérobie, avec les glucides puis les lipides","L'anaérobie alactique, rapide"],"r":2,"e":"> 3 min = oxydative.","s":0},{"q":"Un sprint 400 m (30-90 sec) utilise principalement :","o":["ATP-PC","Glycolytique","Aérobie","Lipides"],"r":1,"e":"30-90 sec = glycolytique.","s":0},{"q":"Un faible taux d'innervation (peu de fibres / motoneurone) caractérise :","o":["Le quadriceps et le biceps","Le larynx, le globe oculaire et les doigts","Tous les muscles du corps","Aucun muscle, ce ratio étant toujours élevé chez l'homme"],"r":1,"e":"Faible ratio = précision motrice (mouvements fins). Ce sont des muscles de mouvements précis.","s":0},{"q":"Un grand nombre de fibres / motoneurone caractérise :","o":["Les mouvements précis, comme ceux de l'œil","Les gros muscles, comme le quadriceps","Les muscles des doigts","Le globe oculaire et le larynx"],"r":1,"e":"Grand ratio = mouvements grossiers, force. Ils assurent des mouvements grossiers.","s":0},{"q":"Co-contraction agoniste/antagoniste :","o":["Des mouvements rapides et balistiques","Des mouvements lents, avec une stabilité accrue","Une absence d'activation, au repos","Une inversion de l'activation, comme dans un lancer rapide"],"r":1,"e":"Co-contraction = stabilité, mouvements lents.","s":0},{"q":"Innervation réciproque :","o":["Une co-contraction, pour stabiliser","Une inversion de l'activation, pour les gestes rapides","Aucune activation, le geste étant passif et entièrement réflexe","Une activation aléatoire des deux muscles"],"r":1,"e":"Réciproque = inversion → rapidité (sport, balistique). Elle concerne agoniste et antagoniste, dans les gestes balistiques.","s":0},{"q":"Contraction CONCENTRIQUE :","o":["Un maintien de la longueur","Un raccourcissement du muscle","Un allongement du muscle, sous une tension croissante","Aucun changement de tension"],"r":1,"e":"Concentrique = raccourcissement.","s":0},{"q":"Contraction EXCENTRIQUE :","o":["Un raccourcissement du muscle","Un allongement du muscle, sous tension","Un maintien de la longueur, avec une tension constante","Un repos complet du muscle"],"r":1,"e":"Excentrique = allongement sous tension.","s":0},{"q":"Contraction ISOMÉTRIQUE :","o":["Un raccourcissement du muscle","Un allongement du muscle, sous charge","Un maintien de la longueur, avec tension","Aucune force produite"],"r":2,"e":"Isométrique = statique, pas de mouvement visible.","s":0},{"q":"Quel type de contraction ↑ la force avec la vitesse ?","o":["Concentrique","Excentrique","Isométrique","Aucune"],"r":1,"e":"Excentrique : ↑ force avec ↑ vitesse (concentrique ↓ force avec ↑ vitesse).","s":0},{"q":"L'isométrique ne doit pas dépasser :","o":["3 min","10 minutes","30 min","1 h"],"r":1,"e":"Isométrie : ≤ 10 min/séance, jamais en apnée.","s":0},{"q":"L'isocinétique est :","o":["Une contraction statique, fixe","Un travail à vitesse constante","Un effort anaérobie pur","Un travail sans matériel"],"r":1,"e":"Isocinétique : vitesse constante, résistance variable proportionnelle. La résistance y est variable.","s":0},{"q":"Avantage majeur de l'isocinétique :","o":["Un coût très faible, à l'achat","Une résistance adaptée, donc une force maximale à tout angle","L'absence de matériel, pour un travail à domicile, sans appareil","Un caractère toujours fonctionnel"],"r":1,"e":"Isocinétique : force max à chaque degré de l'amplitude. La résistance est proportionnelle à la force.","s":0},{"q":"L'isométrique a comme inconvénient majeur :","o":["Aucun inconvénient notable","Un travail cardiaque accru et un gain limité à l'angle","Une douleur constante, quelle que soit l'intensité du travail","Un gain immédiat trop important"],"r":1,"e":"Isométrie : limites cardiovasculaires (apnée) et gain limité à l'angle travaillé. L'apnée provoque un effet Valsalva.","s":0},{"q":"Force ANALYTIQUE :","o":["Un groupe musculaire isolé, comme l'extension du genou","Un modèle de mouvement complet","Une absence de mesure, au hasard","La force utile au quotidien, dans les gestes de la vie courante"],"r":0,"e":"Analytique = muscle/groupe isolé.","s":0},{"q":"Le principe de surcharge suppose une exigence :","o":["Constante","Progressive","Décroissante","Maximale d'emblée"],"r":1,"e":"Pour augmenter force et résistance, le muscle doit être surchargé, mais de façon graduée.","s":0},{"q":"Les fibres de type IIa se caractérisent par une capillarisation :","o":["Faible","Élevée","Nulle","Variable selon l'âge"],"r":1,"e":"Elles partagent avec les fibres I une capillarisation et un taux de mitochondries élevés, mais s'en distinguent par une contraction rapide.","s":0},{"q":"L'excitabilité des fibres de type I est décrite comme :","o":["Tonique","Phasique","Intermédiaire","Absente"],"r":0,"e":"Les fibres IIb sont phasiques et les IIa intermédiaires.","s":0},{"q":"La myoglobine des fibres de type IIa est :","o":["Faible","Modérément élevée","Nulle","Identique à celle des IIb"],"r":1,"e":"Elle est élevée dans les fibres I et faible dans les fibres IIb.","s":0},{"q":"La voie anaérobie alactique fournit de l'énergie pendant :","o":["Une demi-seconde pour l'ATP et 2 à 10 s pour la CP","Jusqu'à 60 secondes, avec le glycogène et l'ATP","De 1 à 3 minutes, avec le foie","Plus de 3 minutes, avec l'oxygène"],"r":0,"e":"Sa puissance est très élevée mais sa capacité très limitée. La CP est la créatine-phosphate.","s":0},{"q":"La voie aérobie se caractérise par :","o":["Une capacité illimitée et une puissance faible","Une capacité limitée et une puissance élevée","Une capacité et une puissance très élevées","Une durée inférieure à 30 secondes"],"r":0,"e":"La voie anaérobie alactique a au contraire une puissance très élevée pour une capacité très limitée.","s":0},{"q":"Une activité de 90 à 180 secondes, comme une course de 800 mètres ou la boxe, mobilise :","o":["L'ATP-PC seul, sur un effort bref","Les voies glycolytique et oxydative","La voie oxydative seule, de longue durée","La voie alactique, comme pour un saut ou un départ de sprint"],"r":1,"e":"Au-delà de 3 minutes, la voie oxydative domine ; en deçà de 30 secondes, l'ATP-PC.","s":0},{"q":"Une activité de 30 à 90 secondes, comme un sprint de 400 mètres ou la natation, mobilise principalement :","o":["Le système ATP-PC","Le système glycolytique","Le système oxydatif","Aucun des trois"],"r":1,"e":"Le glycogène hépatique y est sollicité de 1 à 3 minutes, la voie couvrant jusqu'à 60 secondes.","s":0},{"q":"La co-contraction agoniste/antagoniste correspond à :","o":["Des mouvements lents, avec une stabilité accrue","Des mouvements rapides et balistiques","Une inversion de l'activation, comme lors d'un lancer de balle","Une contraction isolée de l'agoniste"],"r":0,"e":"L'innervation réciproque, par inversion de l'activation, sous-tend au contraire les mouvements rapides et balistiques. La stabilité est articulaire.","s":0},{"q":"La force analytique se travaille :","o":["Sur un groupe musculaire isolé, comme l'extension du genou","Sur un modèle de mouvement, comme le contrôle de l'épaule","En chaîne fermée uniquement, avec un appui au sol et des charges","Avec un partenaire, en duo, face à face"],"r":0,"e":"La force fonctionnelle s'organise, elle, autour d'un modèle de mouvement.","s":0},{"q":"La contraction excentrique se caractérise, par rapport à la concentrique, par :","o":["Un gain de force à court terme et une acquisition précoce","Un gain de force à long terme et une acquisition plus tardive","Une moindre exigence de coordination","Une diminution de force avec la vitesse"],"r":1,"e":"Elle exige aussi davantage de coordination et voit sa force augmenter avec la vitesse.","s":0},{"q":"La contraction concentrique se caractérise par :","o":["Une hausse de la force avec la vitesse du geste","Une baisse de la force quand la vitesse augmente","Une longueur constante du muscle","Une vitesse imposée par une machine"],"r":1,"e":"Elle apporte un gain de force à court terme, s'acquiert plus tôt et exige moins de coordination.","s":0},{"q":"La contraction isométrique se caractérise sur le plan tissulaire par :","o":["Une modification de la taille des fibres","Une tension modifiée, sans changement de taille des fibres","Un allongement des fibres, sous tension","Un raccourcissement des fibres, avec une hypertrophie immédiate"],"r":1,"e":"Elle est courante dans les muscles posturaux et stabilisateurs.","s":0},{"q":"Parmi les avantages de la contraction isométrique, le cours cite :","o":["Un matériel minimal et un gain de force rapide","Un gain sur toute l'amplitude","Une grande variété d'exercices","Une absence totale d'effet sur le cœur et la pression artérielle"],"r":0,"e":"Ses inconvénients sont l'augmentation du travail cardiaque par l'apnée, la monotonie et un gain limité à l'amplitude travaillée. Elle se pratique n'importe où.","s":0},{"q":"La durée totale de travail isométrique dans une séance ne doit pas dépasser :","o":["5 minutes","10 minutes","20 minutes","30 minutes"],"r":1,"e":"L'apnée y est par ailleurs proscrite, et un étirement avec relaxation est recommandé à la fin.","s":0},{"q":"La contraction isocinétique se définit par :","o":["Une charge constante, de 10 kg","Une vitesse constante, par exemple 60°/s","Une absence de mouvement, en statique","Une résistance constante, quelle que soit la force produite"],"r":1,"e":"Elle peut être concentrique ou excentrique, la résistance étant proportionnelle à la force du patient. La résistance y est variable.","s":0},{"q":"L'avantage majeur de l'isocinétique est :","o":["Une résistance qui s'adapte à la force à chaque instant","Un coût réduit, pour le cabinet","Une praticabilité partout, même au domicile du patient","L'absence de matériel, à la maison"],"r":0,"e":"C'est ce qui permet de solliciter le muscle au maximum de ses possibilités sur toute l'amplitude.","s":0},{"q":"Le principe d'action retardée signifie que :","o":["Les résultats apparaissent en différé, par surcompensation","L'effort doit être différé de quelques jours, après la blessure","Le muscle se contracte avec retard","La récupération est immédiate"],"r":0,"e":"C'est ce qui justifie la planification des cycles d'entraînement et des périodes de récupération.","s":0},{"q":"Le principe de spécificité énonce que :","o":["Seuls les systèmes sollicités s'adaptent","Tous les systèmes s'adaptent simultanément","L'adaptation est générale","La surcharge suffit"],"r":0,"e":"L'entraînement doit donc respecter les besoins propres du muscle visé.","s":0},{"q":"Le principe de maintien ou réversibilité énonce que :","o":["Les gains sont définitifs","Sans exercice, le muscle revient à son état initial","La force se maintient six mois","Seule la masse se perd, la force restant intacte des années"],"r":1,"e":"C'est l'argument central de la poursuite d'un entretien après la phase de gain.","s":0},{"q":"Selon l'ACSM, l'exercice est :","o":["Toute activité physique spontanée, même non planifiée","Une activité planifiée, structurée, répétitive et voulue","Un sport de loisir, pratiqué en club","Un travail manuel, répété"],"r":1,"e":"Définition ACSM : planifié + structuré + répétitif + intentionnel. C'est une sous-catégorie de l'activité physique.","s":1},{"q":"Composantes liées à la santé visées par l'exercice :","o":["Force (puissance/endurance)","Souplesse","Capacité aérobie","Composition corporelle","Couleur de peau"],"r":[0,1,2,3],"e":"4 composantes santé : force, souplesse, aérobie, composition.","s":1},{"q":"Aptitudes améliorées par l'exercice :","o":["Agilité","Coordination","Équilibre","Temps de réaction","Vitesse","Mémorisation"],"r":[0,1,2,3,4],"e":"5 aptitudes : agilité, coordination, équilibre, temps de réaction, vitesse.","s":1},{"q":"Combien de piliers comporte l'exercice thérapeutique ?","o":["3","4","5","7"],"r":2,"e":"5 piliers : Mobilité, Souplesse, Force, Pliométrie, RSM.","s":1},{"q":"Le 1er pilier de l'exercice thérapeutique est :","o":["Force","Souplesse","Mobilité","Pliométrie"],"r":2,"e":"Ordre : Mobilité → Souplesse → Force → Pliométrie → RSM.","s":1},{"q":"Le 5e pilier est :","o":["La force musculaire, analytique","La reprogrammation sensorimotrice","L'endurance aérobie, générale","L'endurance musculaire, locale"],"r":1,"e":"RSM = pilier 5, le plus avancé. On la note aussi RSM ou TSM.","s":1},{"q":"L'exercice se distingue de l'activité physique générale par :","o":["L'intensité, toujours plus élevée","Son caractère planifié, structuré et intentionnel","La durée, toujours plus longue","La compétition, avec un classement et un adversaire à battre"],"r":1,"e":"Activité physique = tout mouvement. Exercice = sous-catégorie organisée.","s":1},{"q":"La force comprend :","o":["La vitesse, à elle seule","La puissance et l'endurance","La souplesse des muscles","La coordination motrice"],"r":1,"e":"Force = capacité de tension ; comprend puissance + endurance.","s":1},{"q":"L'agilité fait partie des :","o":["Composantes de la santé","Aptitudes motrices","Voies énergétiques","Tissus contractiles"],"r":1,"e":"Agilité = aptitude motrice (pas une composante santé).","s":1},{"q":"L'objectif global de l'exercice thérapeutique est :","o":["La performance sportive, uniquement, en club","Maintenir ou améliorer la santé et les capacités","La compétition, en club ou en équipe","L'esthétique corporelle, avant tout"],"r":1,"e":"Exercice thérapeutique = visée santé/fonction. Les capacités sont fonctionnelles.","s":1},{"q":"La mobilité est centrée sur :","o":["L'amplitude articulaire, physiologique","La force musculaire, maximale","La résistance cardio-respiratoire, à l'effort prolongé","La coordination fine, des doigts"],"r":0,"e":"Mobilité = ROM, physiologie articulaire.","s":1},{"q":"La souplesse cible :","o":["L'os, sa densité minérale","La fibre musculaire, sa longueur","Le liquide synovial, sa viscosité","Le cartilage, son épaisseur"],"r":1,"e":"Souplesse = effet direct sur la fibre musculaire. Elle agit aussi sur son alignement.","s":1},{"q":"La pliométrie utilise :","o":["Un étirement lent, maintenu trente secondes","Un pré-étirement rapide, puis une détente","Un mouvement isométrique, statique","Aucun étirement préalable"],"r":1,"e":"Pliométrie : SSC (Stretch-Shortening Cycle). C'est le cycle allongement-raccourcissement.","s":1},{"q":"La RSM vise :","o":["La force maximale, en charge","La qualité du mouvement, par le contrôle moteur","Le volume musculaire, par l'hypertrophie des fibres rapides","L'esthétique du geste sportif"],"r":1,"e":"RSM = reprogrammation sensorimotrice, contrôle qualité. La proprioception en fait partie.","s":1},{"q":"Pour la population générale, la répartition glucides est :","o":["20%","50%","80%","100%"],"r":1,"e":"Pop générale : glucides 50%, lipides 30%, protéines 15%.","s":1},{"q":"Pour le sportif, la répartition glucides est :","o":["20 à 30 % des apports","40 % des apports","60 à 70 % des apports","90 % des apports"],"r":2,"e":"Sportif : glucides 60-70%, protéines 12%. Ils reconstituent le glycogène musculaire.","s":1},{"q":"Recommandations nutritionnelles générales :","o":["Privilégier les glucides complexes","Préférer les lipides insaturés","Consommer des fibres pour le transit","Modérer le sel","Boire de l'alcool en quantité","Bien s'hydrater"],"r":[0,1,2,3,5],"e":"Alcool = calories vides + diurétique → déshydratation.","s":1},{"q":"Avant une épreuve, privilégier des aliments :","o":["Lourds et copieux","Faciles à digérer","Très épicés","Riches en lipides"],"r":1,"e":"Aliments faciles à digérer pour ne pas surcharger.","s":1},{"q":"Ordre de digestion (le plus rapide en premier) :","o":["Lipides → protéines → glucides complexes → sucres","Glucides complexes → protéines → lipides","Sucres → glucides complexes → protéines → lipides","Protéines → sucres → lipides → glucides complexes"],"r":2,"e":"Sucres simples → glucides complexes → protéines → lipides.","s":1},{"q":"Préhydratation 10-15 min avant l'effort :","o":["100 mL","300 mL","600-800 mL","2 L"],"r":2,"e":"Préhydratation 600-800 mL (adultes).","s":1},{"q":"Pendant l'effort, hydratation :","o":["Aucune, pour éviter les crampes","De petites quantités toutes les 10 à 15 minutes","2 litres d'un coup, juste avant de commencer","Une boisson alcoolisée, en récompense"],"r":1,"e":"Petites quantités fractionnées toutes les 10-15 min.","s":1},{"q":"La réhydratation post-effort est :","o":["Inutile après l'effort, chez l'adulte","Un aspect essentiel de la récupération","Réservée aux sportifs d'élite","Toujours faite par perfusion, à l'hôpital, sous surveillance"],"r":1,"e":"Récupération = réhydratation essentielle.","s":1},{"q":"Rôles de l'eau dans l'exercice :","o":["Le refroidissement du corps","Le transport des nutriments","Le maintien du volume sanguin","La production directe d'ATP","La réserve de calories"],"r":[0,1,2],"e":"L'eau ne produit pas d'ATP directement et ne stocke pas de calories.","s":1},{"q":"L'alcool agit comme :","o":["Un hydratant, utile à l'effort","Un diurétique, qui favorise la déshydratation","Un anti-inflammatoire, après l'effort","Un anabolisant, qui augmente la masse musculaire et la force"],"r":1,"e":"Alcool = diurétique → ↑ pertes hydriques.","s":1},{"q":"Apports en lipides recommandés (pop. générale) :","o":["5 % des apports, surtout saturés","30 % des apports, surtout insaturés","60 % des apports, surtout saturés","Aucun apport, pour limiter le cholestérol"],"r":1,"e":"Lipides ~30%, max 10% saturés. Les saturés sont limités à 10 %.","s":1},{"q":"Protéines chez le sportif :","o":["1%","12%","30%","50%"],"r":1,"e":"Sportif : protéines 12%. Attention au fer et au calcium.","s":1},{"q":"Si problème d'HTA, l'apport en sel doit être :","o":["Libre","Augmenté","Modéré","Doublé"],"r":2,"e":"Sel : modération (encore plus si HTA).","s":1},{"q":"Les fibres alimentaires sont essentielles pour :","o":["L'énergie","Le transit intestinal","La force musculaire","La concentration"],"r":1,"e":"Fibres = transit intestinal.","s":1},{"q":"L'exercice thérapeutique doit-il être planifié ?","o":["Non, l'improvisation étant meilleure","Oui, selon la définition de l'ACSM","Seulement pour les sportifs, selon l'OMS","Uniquement en cas de douleur"],"r":1,"e":"Toujours planifié et structuré. Elle le veut planifié, structuré, répétitif et intentionnel.","s":1},{"q":"Lequel n'est PAS un pilier ?","o":["Mobilité","Souplesse","Aérobie","Force","Pliométrie","RSM"],"r":2,"e":"L'aérobie est une voie énergétique, pas un pilier. Les 5 piliers : mobilité, souplesse, force, pliométrie, RSM.","s":1},{"q":"La définition ACSM de l'exercice le décrit comme une sous-catégorie d'activité physique qui est :","o":["Planifiée, structurée, répétitive et intentionnelle","Spontanée et quotidienne, sans but","Professionnelle, liée au travail","Exclusivement aérobie, comme la course à pied et la natation"],"r":0,"e":"C'est cette intentionnalité planifiée qui le distingue de l'activité physique générale.","s":1},{"q":"La capacité aérobie fait partie, selon l'ACSM :","o":["Des aptitudes","Des composantes liées à la santé","Des cinq piliers","Des qualités psychomotrices"],"r":1,"e":"Force, souplesse, capacité aérobie et composition corporelle sont les composantes liées à la santé ; agilité, coordination, équilibre, temps de réaction et vitesse sont les aptitudes.","s":1},{"q":"La composition corporelle est classée par l'ACSM parmi :","o":["Les aptitudes","Les composantes liées à la santé","Les piliers de l'exercice thérapeutique","Les facteurs de souplesse"],"r":1,"e":"Elle y figure aux côtés de la force, de la souplesse et de la capacité aérobie.","s":1},{"q":"Le temps de réaction est classé parmi :","o":["Les composantes liées à la santé","Les aptitudes motrices","Les piliers de l'exercice thérapeutique","Les mécanismes énergétiques"],"r":1,"e":"Agilité, coordination, équilibre, temps de réaction et vitesse constituent les aptitudes.","s":1},{"q":"La force, dans les composantes liées à la santé, recouvre :","o":["La puissance et l'endurance","La seule force maximale","La vitesse","La coordination"],"r":0,"e":"Elle constitue l'un des cinq piliers de l'exercice thérapeutique et l'une des composantes liées à la santé.","s":1},{"q":"Le pilier « mobilité » vise :","o":["À maintenir ou améliorer l'amplitude des articulations","À allonger les fibres musculaires, par étirement","À augmenter la puissance","À reprogrammer le contrôle moteur"],"r":0,"e":"La souplesse, elle, agit directement sur la fibre musculaire. Son effet porte directement sur la physiologie articulaire.","s":1},{"q":"Le pilier « souplesse » agit directement sur :","o":["La physiologie articulaire","La fibre musculaire","Le système nerveux central","La composition corporelle"],"r":1,"e":"Elle vise l'amplitude articulaire par l'allongement de la fibre, ainsi que l'amélioration de la production motrice et la relaxation.","s":1},{"q":"Le pilier « pliométrie » repose sur :","o":["Un pré-étirement, avant la contraction rapide","Un maintien postural prolongé","Une mobilisation passive","Un étirement statique, maintenu plus de trente secondes"],"r":0,"e":"Ses mouvements sont rapides et puissants, pour un coût métabolique réduit. Il active le cycle allongement-raccourcissement.","s":1},{"q":"Le pilier « reprogrammation sensorimotrice » vise :","o":["La quantité de force produite","La qualité du mouvement et le contrôle moteur","L'amplitude articulaire, passive","La composition corporelle et la masse grasse, à long terme"],"r":1,"e":"C'est le cinquième pilier, développé par Vladimir Janda sous le nom d'entraînement sensorimoteur. Son effet est direct sur la physiologie neuromusculaire.","s":1},{"q":"L'ordre des cinq piliers tel que le cours les énonce est :","o":["Mobilité, souplesse, force, pliométrie, RSM","Force, mobilité, souplesse, RSM, pliométrie","Souplesse, force, mobilité, pliométrie, RSM","Pliométrie, force, mobilité, souplesse, RSM"],"r":0,"e":"Cette progression va du plus articulaire au plus neuromusculaire. La RSM est la reprogrammation sensorimotrice.","s":1},{"q":"L'acronyme FITT-VP, utilisé pour la prescription d'exercice, commence par :","o":["Force, intensité, temps, type","Fréquence, intensité, temps, type","Fonction, intensité, tolérance, technique","Fréquence, itération, temps, tâche"],"r":1,"e":"Les lettres V et P y ajoutent le volume et la progression.","s":1},{"q":"La pliométrie ne doit être introduite que si la zone concernée est :","o":["Encore œdématiée, pour drainer l'œdème par le mouvement","Sans œdème ni douleur, avec des capacités normales","Immobilisée, en attelle","Douloureuse mais mobile"],"r":1,"e":"Elle se situe en phase finale de récupération, après les autres piliers. L'amplitude, la force et la souplesse doivent être normales.","s":1},{"q":"L'agilité et la coordination se distinguent des composantes liées à la santé parce qu'elles relèvent :","o":["De la performance, donc des aptitudes","De la composition corporelle, mesurée par impédance","Du système cardiovasculaire","De l'amplitude articulaire"],"r":0,"e":"Cette distinction structure toute la définition ACSM de l'exercice.","s":1},{"q":"Le caractère « structuré » de l'exercice, selon l'ACSM, signifie qu'il :","o":["Suit des paramètres définis, et non le hasard","Se pratique en salle, avec un coach, à heure fixe","Fait intervenir du matériel spécifique, en salle","Est encadré par un professionnel de santé, toujours"],"r":0,"e":"Planification, structure, répétition et intentionnalité forment les quatre attributs de la définition.","s":1},{"q":"Le caractère « répétitif » de l'exercice implique :","o":["Une exécution unique, bien faite","Une répétition nécessaire à l'adaptation","Une monotonie imposée au patient","Un travail exclusivement analytique, muscle par muscle"],"r":1,"e":"Sans répétition, aucune adaptation durable des systèmes sollicités n'est possible. L'adaptation recherchée en dépend.","s":1},{"q":"L'objectif global de l'exercice, dans la définition ACSM, est :","o":["L'amélioration ou le maintien de la santé et des aptitudes","La seule performance sportive, en compétition, à haut niveau","La seule perte de poids, à long terme","La seule prévention des chutes"],"r":0,"e":"L'exercice thérapeutique en constitue l'application clinique, organisée en cinq piliers. Il s'agit des composantes liées à la santé.","s":1},{"q":"La mobilité, parmi les cinq piliers, se travaille selon le cours par :","o":["La thérapie manuelle en passif et l'exercice en actif","Les seuls étirements, en fin de séance","La seule pliométrie, en sauts","Le seul travail en charge, avec des haltères et des machines"],"r":0,"e":"La mobilité passive comprend elle-même les composantes accessoire et physiologique.","s":1},{"q":"L'équilibre, cité parmi les aptitudes, résulte de l'intégration :","o":["Des systèmes vestibulaire, visuel et proprioceptif","Du seul système vestibulaire, dans l'oreille interne","De la seule vision, binoculaire","De la seule force musculaire"],"r":0,"e":"C'est cette intégration que la reprogrammation sensorimotrice cherche à restaurer.","s":1},{"q":"La vitesse figure, dans la classification ACSM :","o":["Parmi les composantes liées à la santé","Parmi les aptitudes","Parmi les piliers","Parmi les voies énergétiques"],"r":1,"e":"Elle y côtoie l'agilité, la coordination, l'équilibre et le temps de réaction.","s":1},{"q":"L'exercice thérapeutique se distingue de l'exercice en général par :","o":["Son organisation en cinq piliers, à visée de rééducation","Son intensité plus élevée, proche du maximum théorique","Sa durée plus longue, d'au moins une heure","L'absence de planification, à la demande"],"r":0,"e":"Mobilité, souplesse, force, pliométrie et reprogrammation sensorimotrice en constituent le cadre.","s":1},{"q":"Les exercices de mobilité visent à :","o":["Augmenter la force musculaire, en charge progressive","Maintenir ou améliorer l'amplitude articulaire","Diminuer la masse osseuse","Augmenter la consommation maximale d'oxygène"],"r":1,"e":"Mobilité : effet direct sur l'amplitude et la physiologie articulaire. Ils ont un effet direct sur la physiologie articulaire.","s":2},{"q":"L'immobilisation peut être bénéfique pour :","o":["Le repos initial, pour la cicatrisation","Rien, l'immobilisation étant toujours néfaste, à tout moment","Le renforcement du muscle","Le gain de mobilité articulaire"],"r":0,"e":"Repos = bénéfique pour la cicatrisation initiale.","s":2},{"q":"Effets systémiques nuisibles de l'immobilisation :","o":["Musculo-squelettique","Cardiovasculaire","Respiratoire","Tégumentaire","Endocrinien"],"r":[0,1,2,3],"e":"4 grands systèmes affectés : MSK, CV, respi, tégumentaire.","s":2},{"q":"Effets MSK de l'immobilisation :","o":["↓ masse osseuse (ostéopénie)","Atrophie musculaire","↓ ROM","↑ masse graisseuse","↑ masse osseuse"],"r":[0,1,2,3],"e":"Tous sauf ↑ masse osseuse (qui diminue).","s":2},{"q":"Effets cardiovasculaires de l'immobilisation :","o":["↓ volume sanguin","↓ débit cardiaque","↑ retour veineux","Hypotension orthostatique","Thromboses veineuses profondes"],"r":[0,1,3,4],"e":"Retour veineux diminué, pas augmenté.","s":2},{"q":"Effets respiratoires de l'immobilisation :","o":["Des pneumonies","Une embolie pulmonaire","Un asthme bronchique","Une bronchite chronique"],"r":[0,1],"e":"Pneumonies et EP fréquentes. Asthme et BPCO sont chroniques préexistantes.","s":2},{"q":"L'effet local nuisible de l'immobilisation est :","o":["Un renforcement musculaire, par le repos","Une altération de la capsule, des ligaments et des tendons","Une hausse de l'amplitude, par relâchement capsulaire et tendineux","Aucun effet local, à court terme"],"r":1,"e":"Local : capsule, ligaments, tendons s'altèrent (rétraction).","s":2},{"q":"Le tégumentaire peut être affecté par :","o":["Augmentation de la peau","Escarres","Cicatrisation accrue","Aucun problème"],"r":1,"e":"Immobilisation → escarres.","s":2},{"q":"Avantages de la mobilité :","o":["Indépendance et fonctionnalité","↑ et maintien de l'amplitude","Stimule la circulation/retour veineux","Charge nécessaire à l'os (prévention ostéoporose)","Prévient les escarres","Augmentation de la raideur capsulaire"],"r":[0,1,2,3,4],"e":"5 avantages majeurs. La raideur capsulaire résulte de l'immobilisation ; la mobilité la combat.","s":2},{"q":"Idées clés pour la mobilité active :","o":["Mouvement libre","Qualité du mouvement (schéma)","Amplitude","Force maximale","Répétition"],"r":[0,1,2,4],"e":"La force max n'est pas un objectif de la mobilité.","s":2},{"q":"En thérapie manuelle, la mobilité est :","o":["Active, faite par le patient","Passive, accessoire et physiologique","Volontaire, contre une résistance","Réflexe, par étirement"],"r":1,"e":"Thérapie manuelle = mobilité passive.","s":2},{"q":"En exercice, la mobilité est :","o":["Passive, faite par l'évaluateur","Active, faite par le patient","Réflexe, déclenchée par un étirement brusque du muscle","Imposée par une machine"],"r":1,"e":"Exercice = mobilité active.","s":2},{"q":"L'ostéoporose se prévient par :","o":["L'immobilisation stricte, au lit","Une charge mécanique sur l'os","Le repos au lit, prolongé","L'alcool, à dose modérée, qui renforcerait la trame osseuse"],"r":1,"e":"L'os a besoin de charges pour maintenir sa densité (loi de Wolff).","s":2},{"q":"L'hypotension orthostatique survient :","o":["Au repos, allongé sur le dos","Au passage debout, après un alitement prolongé","En position assise, au bureau","En décubitus, la nuit, après un repas copieux et un bain chaud"],"r":1,"e":"Alitement → ↓ volume sanguin → hypotension orthostatique au levée.","s":2},{"q":"Les thromboses veineuses profondes (TVP) sont favorisées par :","o":["Le mouvement régulier","La stase veineuse de l'immobilisation","L'exercice physique intense, surtout en altitude","Une bonne hydratation"],"r":1,"e":"Stase veineuse = facteur principal de TVP (triade de Virchow). C'est un élément de la triade de Virchow.","s":2},{"q":"L'embolie pulmonaire est :","o":["Une infection du poumon","Une complication de la TVP, et une urgence vitale","Une allergie respiratoire, aux pollens, sans gravité","Une rétention urinaire, en HBP"],"r":1,"e":"EP : migration d'un thrombus de la TVP vers les artères pulmonaires.","s":2},{"q":"L'amplitude se perd à quelle vitesse en immobilisation ?","o":["Très lentement, sur des années","Rapidement, par atrophie et raccourcissement","Jamais, l'articulation gardant son amplitude malgré le repos","De façon variable selon l'humeur"],"r":1,"e":"Pertes rapides : muscle (5% force/jour) + raccourcissement capsulo-ligamentaire. La force musculaire baisse d'environ 5 % par jour.","s":2},{"q":"Pour prévenir les escarres lors d'immobilisation :","o":["Maintenir la même position, sans bouger, au lit","Redistribuer les pressions, en changeant de position","Aucune mesure particulière","Une compression continue, sur les talons"],"r":1,"e":"Redistribuer pressions par mobilité et changements de position.","s":2},{"q":"La mobilité active est :","o":["Réalisée par l'évaluateur","Réalisée volontairement par le patient","Réalisée sous anesthésie","Réalisée sans contrôle moteur, par réflexe médullaire"],"r":1,"e":"Active = par le patient lui-même.","s":2},{"q":"La mobilité passive est :","o":["Réalisée par le patient lui-même","Réalisée par l'évaluateur, segment proximal stabilisé","Une absence de mobilité, segment fixé par une orthèse rigide","Un mouvement réflexe, médullaire"],"r":1,"e":"Passive = réalisée par l'évaluateur sans participation active.","s":2},{"q":"Un mouvement analytique cible :","o":["Plusieurs articulations en même temps","Une articulation/segment précis","Tout le corps","Aucune cible"],"r":1,"e":"Analytique = ciblé, articulation/segment isolé.","s":2},{"q":"Un mouvement fonctionnel intègre :","o":["Une seule articulation, isolée du reste du membre et du tronc","Plusieurs articulations, dans une tâche cohérente","Aucune articulation, en statique","Du repos, entre les séries"],"r":1,"e":"Fonctionnel = tâche globale, multi-articulaire (ex : se lever). Se lever d'une chaise en est un exemple.","s":2},{"q":"L'atrophie musculaire en alitement :","o":["Touche seulement le muscle strié cardiaque","Touche d'abord les muscles posturaux","N'a aucun effet musculaire","Augmente la force, par le repos"],"r":1,"e":"Atrophie touche surtout les fibres lentes posturales d'abord. Ce sont des fibres de type I, puis tous les muscles.","s":2},{"q":"Quels facteurs limitent la perte de ROM en immobilisation ?","o":["Une restriction stricte du mouvement","Une mobilisation précoce et régulière","Une pression articulaire élevée","Une compression durable"],"r":1,"e":"Mobilisation précoce préserve l'amplitude.","s":2},{"q":"L'augmentation de la masse graisseuse en immobilisation est due à :","o":["Un renforcement musculaire","Une dépense qui baisse sans baisse des apports","L'alimentation seule, quelle que soit l'activité","Une activité physique intense"],"r":1,"e":"↓ DE sans ↓ alimentation → bilan calorique positif → ↑ graisse. Le bilan calorique devient positif.","s":2},{"q":"L'objectif principal de la mobilité chez la personne alitée :","o":["La performance sportive, en club","Le maintien de l'indépendance et de la fonction","L'esthétique corporelle, avant tout","La réduction du temps de sommeil, pour accélérer la récupération"],"r":1,"e":"Indépendance et fonctionnalité = priorité.","s":2},{"q":"Le mouvement libre désigne :","o":["Un mouvement contre résistance","Un mouvement sans résistance externe ni contrainte","Un mouvement passif, imposé","Une absence de mouvement, en contraction isométrique maintenue"],"r":1,"e":"Libre = sans résistance externe.","s":2},{"q":"Indications principales de la mobilité :","o":["Post-immobilisation","Maladies chroniques","Personnes âgées","Sportif sain","Pré-opératoire"],"r":[0,1,2,4],"e":"Le sportif sain en bonne santé pratique mais c'est moins un objectif de soin.","s":2},{"q":"La mobilité contre-indications :","o":["Aucune contre-indication, jamais","Les fractures non consolidées et les hémorragies actives","Toutes les pathologies, sans exception, même les plus bénignes","Une douleur légère, passagère"],"r":1,"e":"CI : fractures non consolidées, hémorragies, lésions instables. Les lésions instables en font aussi partie.","s":2},{"q":"L'objectif premier de la mobilité après une chirurgie est :","o":["Un renforcement maximal, d'emblée","Restaurer l'amplitude et éviter les adhérences","La reprise de la compétition, dès la sortie de l'hôpital","L'esthétique de la cicatrice"],"r":1,"e":"Post-chirurgie : récupérer ROM, prévenir adhérences.","s":2},{"q":"La mobilité se définit dans le cours comme un ensemble d'exercices visant à :","o":["Maintenir ou améliorer l'amplitude articulaire","Allonger les fibres musculaires, par étirement prolongé","Augmenter la puissance, en charge","Restaurer le contrôle moteur"],"r":0,"e":"C'est ce qui la distingue de la souplesse, dont l'effet porte directement sur la fibre musculaire. Ses effets sont directs sur la physiologie articulaire.","s":2},{"q":"Parmi les effets musculo-squelettiques nuisibles de l'immobilisation, le cours cite :","o":["Une perte osseuse, une atrophie et une perte d'amplitude","Une hypertrophie musculaire, due au repos prolongé","Une augmentation de la densité osseuse, au repos","Une augmentation de l'amplitude"],"r":0,"e":"La diminution de masse osseuse conduit à l'ostéopénie puis à l'ostéoporose. La masse graisseuse augmente aussi.","s":2},{"q":"Parmi les effets cardiovasculaires de l'immobilisation figurent :","o":["Une baisse du volume sanguin et du débit cardiaque","Une hausse du débit cardiaque","Une hypertension artérielle","Une bradycardie isolée, sans autre changement cardiovasculaire"],"r":0,"e":"S'y ajoutent l'hypotension orthostatique et les thromboses veineuses profondes. Le volume systolique et le retour veineux diminuent aussi.","s":2},{"q":"Les complications respiratoires de l'immobilisation citées sont :","o":["Les pneumonies et l'embolie pulmonaire","L'asthme et la bronchite chronique obstructive","La bronchite chronique","L'apnée du sommeil, obstructive"],"r":0,"e":"L'atteinte tégumentaire se manifeste, elle, par les escarres.","s":2},{"q":"Les effets locaux nuisibles de l'immobilisation concernent :","o":["Les tissus, comme la capsule, les ligaments et les tendons","Le système cardiovasculaire, en entier","Le système respiratoire, au lit","La peau uniquement, par les escarres sur les zones d'appui osseux"],"r":0,"e":"Les effets systémiques touchent, eux, les appareils musculo-squelettique, cardiovasculaire, respiratoire et tégumentaire.","s":2},{"q":"L'immobilisation présente un effet bénéfique dans le cas :","o":["Du repos après une blessure, pour la cicatrisation","De la prévention de l'ostéoporose","De l'entretien musculaire, chez le sujet âgé et alité","De la circulation veineuse, au lit"],"r":0,"e":"C'est son seul bénéfice cité, à mettre en balance avec l'ensemble de ses effets nuisibles.","s":2},{"q":"Parmi les avantages de la mobilité, le cours cite le fait :","o":["De redistribuer la pression et de prévenir les escarres","D'augmenter la masse musculaire","D'améliorer la capacité aérobie et la consommation d'oxygène","De réduire la douleur nociceptive"],"r":0,"e":"S'y ajoutent l'indépendance fonctionnelle, l'entretien de l'amplitude, la stimulation circulatoire et la charge nécessaire à l'os. La pression porte sur les surfaces d'appui.","s":2},{"q":"La mobilité apporte à l'os :","o":["La charge nécessaire à la prévention de l'ostéoporose","Un repos protecteur, contre l'usure articulaire","Une décharge, pour limiter les microfractures","Une immobilisation relative, en position de repos"],"r":0,"e":"L'immobilisation entraîne au contraire une diminution de la masse osseuse.","s":2},{"q":"Parmi les idées clés de la mobilité active figure :","o":["La qualité du mouvement, c'est-à-dire son schéma","La résistance maximale, à chaque essai","La vitesse maximale, quelle que soit la qualité du geste","L'apnée, pour stabiliser"],"r":0,"e":"S'y ajoutent le mouvement libre, l'amplitude, le caractère analytique et fonctionnel, général et spécifique, et la répétition.","s":2},{"q":"La mobilité active se travaille selon un mouvement :","o":["Analytique et fonctionnel, général et spécifique","Exclusivement analytique, segment par segment, isolé","Exclusivement fonctionnel, dans la tâche","Exclusivement passif, par le thérapeute"],"r":0,"e":"Cette double lecture permet de relier le travail segmentaire à la tâche.","s":2},{"q":"En thérapie manuelle, la mobilité passive comprend :","o":["Les composantes accessoire et physiologique","La seule composante physiologique","La seule composante accessoire, par glissement des surfaces","Le renforcement contre résistance"],"r":0,"e":"L'exercice relève, lui, de la mobilité active.","s":2},{"q":"L'hypotension orthostatique après immobilisation prolongée relève :","o":["Des effets musculo-squelettiques","Des effets cardiovasculaires","Des effets respiratoires","Des effets tégumentaires"],"r":1,"e":"Elle accompagne la diminution du volume sanguin, du volume systolique et du retour veineux.","s":2},{"q":"Les escarres relèvent des effets :","o":["Musculo-squelettiques","Cardiovasculaires","Respiratoires","Tégumentaires"],"r":3,"e":"La mobilité les prévient en redistribuant la pression sur les surfaces d'appui.","s":2},{"q":"L'augmentation de la masse graisseuse en immobilisation figure parmi les effets :","o":["Musculo-squelettiques","Cardiovasculaires","Tégumentaires","Locaux"],"r":0,"e":"Elle y accompagne la diminution de la masse maigre et de la force.","s":2},{"q":"La mobilité stimule notamment :","o":["La circulation et le retour veineux","La sécrétion hormonale","La digestion et le transit, chez la personne alitée","La thermorégulation, par la sueur"],"r":0,"e":"C'est l'un des arguments de la mobilisation précoce chez le patient alité.","s":2},{"q":"Les thromboses veineuses profondes sont classées par le cours parmi les effets :","o":["Musculo-squelettiques","Cardiovasculaires","Respiratoires","Locaux"],"r":1,"e":"L'embolie pulmonaire, qui peut en résulter, est classée parmi les effets respiratoires.","s":2},{"q":"La mobilité contribue à l'indépendance du patient parce qu'elle :","o":["Maintient la fonctionnalité","Augmente la force maximale","Améliore la capacité aérobie","Réduit la douleur"],"r":0,"e":"Indépendance et fonctionnalité figurent en tête des avantages cités.","s":2},{"q":"Le mouvement libre, parmi les idées clés de la mobilité active, s'oppose :","o":["Au mouvement assisté ou contraint","Au mouvement analytique, segment par segment","Au mouvement fonctionnel","À la répétition des gestes"],"r":0,"e":"Il figure avec la qualité du mouvement, l'amplitude, le caractère analytique/fonctionnel et la répétition.","s":2},{"q":"L'atrophie musculaire liée à l'immobilisation se traduit par :","o":["Une baisse de la force et de la masse maigre","Une hausse de la force, au repos","Une hausse de la masse maigre","Une hypertrophie compensatrice, par les fibres restantes"],"r":0,"e":"Elle s'accompagne d'une augmentation de la masse graisseuse.","s":2},{"q":"La perte d'amplitude articulaire en immobilisation est classée parmi les effets :","o":["Systémiques musculo-squelettiques","Cardiovasculaires","Locaux tissulaires uniquement","Tégumentaires"],"r":0,"e":"Les effets locaux tissulaires concernent, eux, la capsule, les ligaments et les tendons.","s":2},{"q":"La pliométrie correspond à :","o":["Un étirement lent et prolongé, au sol","Des mouvements rapides et puissants, après un pré-étirement","Un renforcement isométrique, statique","Une absence d'étirement, avec des contractions lentes et maximales"],"r":1,"e":"Pliométrie = pré-étirement + contraction explosive.","s":3},{"q":"Le cycle activé par la pliométrie est :","o":["Le cycle de Krebs, dans les mitochondries","Le cycle allongement-raccourcissement","Le cycle cardiaque, systole et diastole","Le cycle veineux, par la pompe"],"r":1,"e":"SSC = Stretch-Shortening Cycle. C'est le SSC, ou stretch-shortening cycle.","s":3},{"q":"Caractéristiques de la pliométrie :","o":["↑ puissance et vitesse en intervalles courts","Coût métabolique réduit","Phase finale de récupération","Toujours en début de rééducation","Méthode aérobie pure"],"r":[0,1,2],"e":"Phase finale de récupération + ↑ puissance/vitesse en courts intervalles.","s":3},{"q":"Prérequis avant pliométrie :","o":["Exempt d'œdème","Exempt de douleur","ROM normale","Force et souplesse normales","Avoir 50 ans","Pas de prérequis"],"r":[0,1,2,3],"e":"4 prérequis : pas d'œdème, pas de douleur, ROM normale, force et souplesse normales.","s":3},{"q":"Modèle MÉCANIQUE de la pliométrie :","o":["Une énergie électrique, produite par le nerf moteur","Une énergie élastique stockée par un étirement rapide","Une énergie chimique pure, issue de l'ATP","Aucun stockage d'énergie, en continu"],"r":1,"e":"Modèle mécanique = composante élastique des tendons. Elle est stockée dans le complexe muscle-tendon et libérée à la contraction.","s":3},{"q":"Modèle NEUROPHYSIOLOGIQUE de la pliométrie :","o":["Une inhibition réflexe de l'agoniste, par le Golgi","Une stimulation du fuseau, d'où une contraction réflexe","Une activation de l'organe de Golgi","Une inhibition réciproque pure"],"r":1,"e":"Fuseau réagit à l'étirement → réflexe myotatique → contraction agoniste. L'activité de l'agoniste augmente.","s":3},{"q":"La pliométrie est utilisée pour :","o":["Récupération initiale post-traumatique","↑ puissance et explosivité","Étirement passif","Aucun objectif"],"r":1,"e":"↑ puissance, explosivité, performance sportive.","s":3},{"q":"Exemple typique d'exercice pliométrique :","o":["Un squat lent, avec une barre lourdement chargée","Le drop jump, le box jump et les bondissements","Un étirement maintenu, au sol","Une marche lente, sur tapis"],"r":1,"e":"Drop jump, box jump, bondissements = pliométrie classique.","s":3},{"q":"Si la phase de couplage (étirement → contraction) est trop longue :","o":["L'effet est maximal, par sommation","L'énergie élastique se perd en chaleur","Il n'y a aucun effet","L'effet s'inverse, en relâchement"],"r":1,"e":"Phase de couplage très brève (ms) sinon énergie dissipée. L'effet est donc diminué.","s":3},{"q":"Le fuseau musculaire est sensible à :","o":["La température du muscle, à l'effort","L'étirement, en vitesse et en amplitude","La pression sanguine locale","La lumière et la chaleur"],"r":1,"e":"Fuseau = récepteur d'étirement (vitesse + amplitude).","s":3},{"q":"Le réflexe myotatique est :","o":["Une contraction réflexe en réponse à un étirement","Une relaxation réflexe du muscle","Un tremblement musculaire","Un mouvement volontaire, déclenché après un étirement lent"],"r":0,"e":"Réflexe myotatique = contraction réflexe protectrice à l'étirement.","s":3},{"q":"La pliométrie nécessite une base de :","o":["Endurance pure","Force et souplesse","Aucune base","Seulement de l'agilité"],"r":1,"e":"Pliométrie en fin de récupération : nécessite force et souplesse comme base.","s":3},{"q":"La pliométrie est CONTRE-INDIQUÉE en :","o":["Phase de récupération avancée, avant la reprise","Phase aiguë, avec œdème et douleur","Performance sportive, en saison","Préparation physique générale"],"r":1,"e":"CI en phase aiguë : risque de récidive lésionnelle.","s":3},{"q":"Pourquoi le coût métabolique de la pliométrie est-il réduit ?","o":["L'effort est très faible, au repos","L'énergie élastique stockée est réutilisée","Il n'y a aucun travail réel","Elle est purement anaérobie, sans recours à l'oxygène"],"r":1,"e":"Réutilisation énergie élastique = économie métabolique.","s":3},{"q":"Pour un sport de saut, la pliométrie :","o":["Inutile","Très utile pour ↑ détente","Toujours nocive","Pour faibles uniquement"],"r":1,"e":"Pliométrie idéale pour sports de saut.","s":3},{"q":"Pliométrie verticale typique :","o":["La marche, sur le plat","Le squat jump et le box jump","La course lente, sur une longue distance","L'étirement, au sol"],"r":1,"e":"Squat/box jump = pliométrie verticale.","s":3},{"q":"Pliométrie horizontale typique :","o":["L'étirement, au sol, en fin de séance","Les bondissements et les foulées bondissantes","Le squat, avec une barre, en descente lente et contrôlée","Le pliage debout, buste en avant"],"r":1,"e":"Bondissements = pliométrie horizontale.","s":3},{"q":"L'efficacité de la pliométrie dépend de :","o":["Un couplage court entre allongement et raccourcissement","La lenteur du pré-étirement, maintenu longtemps","Le volume de travail, très élevé à chaque séance","Aucun facteur particulier, l'effet étant constant"],"r":0,"e":"Couplage court (< 250 ms idéalement) = efficacité optimale. Il doit durer moins de 250 ms idéalement.","s":3},{"q":"L'organe tendineux de Golgi (OTG) :","o":["Il active la contraction du muscle, en réflexe","Il détecte la tension et inhibe la contraction","Il stocke l'énergie élastique","Il n'a aucun rôle connu"],"r":1,"e":"OTG = sécurité : inhibe la contraction si tension excessive. C'est un rôle de protection.","s":3},{"q":"Type de fibres principalement sollicitées en pliométrie :","o":["Les fibres de type 1, lentes et oxydatives","Les fibres rapides, de type 2","Aucune fibre en particulier","Toutes les fibres, également"],"r":1,"e":"Type II rapides (IIa et IIb) pour explosivité. Ce sont les fibres IIa et IIb.","s":3},{"q":"En physiothérapie de rééducation post-blessure, la pliométrie intervient :","o":["Dès la phase aiguë, en douceur","En phase finale, avant le retour au sport","Jamais, en rééducation de l'adulte","Avant tout autre exercice, en première séance d'échauffement"],"r":1,"e":"Pliométrie = retour à la fonction sportive, phase tardive.","s":3},{"q":"Risque principal d'une pliométrie mal dosée :","o":["Aucun risque particulier, même mal dosée","La récidive lésionnelle et les tendinopathies","Une hypertension artérielle, à l'effort","Des vertiges, en position debout"],"r":1,"e":"Surcharge → lésion musculo-tendineuse (Achille, rotulien).","s":3},{"q":"La progression en pliométrie suit :","o":["Un ordre aléatoire, selon l'envie du jour","Du bilatéral à l'unilatéral, et du faible à l'intense","L'ordre inverse, de l'unilatéral intense au bilatéral","Aucune logique, d'une séance à l'autre"],"r":1,"e":"Progression rigoureuse : du bilatéral peu intense vers unilatéral intense. La hauteur augmente aussi progressivement.","s":3},{"q":"Bénéfice neuromusculaire principal :","o":["Une baisse de la force maximale","Un recrutement accru des unités motrices rapides","Aucun bénéfice mesurable, à long terme","Une baisse de l'explosivité, par fatigue nerveuse chronique"],"r":1,"e":"↑ recrutement UM rapides → explosivité.","s":3},{"q":"Différence pliométrie vs musculation classique :","o":["Aucune différence, en pratique","La pliométrie utilise le pré-étirement rapide","Elles sont identiques, en tout point","L'inverse, la musculation utilisant le pré-étirement rapide"],"r":1,"e":"Pliométrie = SSC ; musculation = surcharge progressive. C'est le SSC, alors que la musculation repose sur une surcharge lente.","s":3},{"q":"Le temps de couplage idéal en pliométrie :","o":["1 sec","< 250 ms","5 sec","30 sec"],"r":1,"e":"< 250 ms = SSC court, efficace.","s":3},{"q":"En pliométrie, la phase excentrique :","o":["Elle est inutile, et donc supprimée","Un étirement rapide qui stocke l'énergie","Une absence d'étirement, la contraction étant immédiate","Une phase concentrique, explosive"],"r":1,"e":"Phase excentrique = étirement rapide → stockage.","s":3},{"q":"En pliométrie, la phase concentrique :","o":["Aucun mouvement, la position étant maintenue","Une contraction explosive, avec l'énergie stockée","Un allongement du muscle, sous tension croissante","Le repos, entre deux sauts successifs"],"r":1,"e":"Phase concentrique = explosion utilisant l'énergie stockée.","s":3},{"q":"La pliométrie améliore aussi :","o":["Rien d'autre que la force","La coordination et le recrutement neuromusculaire","L'endurance cardio-respiratoire, de façon nette","La souplesse passive, au repos"],"r":1,"e":"Bénéfices neuromusculaires multiples. La coordination est intermusculaire.","s":3},{"q":"L'intégration de la pliométrie dans un programme :","o":["Quotidienne et intensive, sans aucun jour de repos","Modérée, progressive et espacée, pour récupérer","Aucune intégration, en rééducation","Aléatoire, selon la forme"],"r":1,"e":"Volumes contrôlés, récupération entre séances (impact articulaire).","s":3},{"q":"La pliométrie se définit comme un ensemble d'exercices :","o":["Lents et contrôlés, sans élan","Rapides et puissants, avec un pré-étirement du muscle","Isométriques, sans mouvement","Passifs, réalisés par le thérapeute sur un patient relâché"],"r":1,"e":"Ce pré-étirement active le cycle d'allongement/raccourcissement.","s":3},{"q":"La pliométrie augmente puissance et vitesse :","o":["Sur des intervalles courts","Sur des efforts prolongés","Sans limite de durée","Uniquement en endurance"],"r":0,"e":"Son coût métabolique est par ailleurs réduit, ce qui la distingue d'un travail en résistance classique.","s":3},{"q":"La pliométrie se situe dans la progression thérapeutique :","o":["En phase initiale, dès J1","En phase finale de récupération","Avant le travail de mobilité","Pendant l'immobilisation, sous attelle ou plâtre"],"r":1,"e":"Elle suppose une zone exempte d'œdème et de douleur, avec amplitude, force et souplesse normales.","s":3},{"q":"Parmi les prérequis à la pliométrie, le cours exige :","o":["Une zone exempte d'œdème et de douleur","Une force supérieure à la normale","Une amplitude supérieure à la normale","Un œdème résiduel toléré"],"r":0,"e":"S'y ajoutent une amplitude, une force et une souplesse normales.","s":3},{"q":"Dans le modèle mécanique de la pliométrie, l'énergie élastique est augmentée par :","o":["Un étirement lent et maintenu","Un étirement rapide du muscle et du tendon","Une contraction isométrique","Un raccourcissement préalable, suivi d'une longue pause"],"r":1,"e":"Si cet étirement est suivi d'une contraction, l'énergie stockée est libérée et augmente la production totale de force.","s":3},{"q":"Dans le modèle neurophysiologique, l'étirement rapide stimule :","o":["L'organe tendineux de Golgi","Le fuseau musculaire","Les mécanorécepteurs cutanés","Le système vestibulaire"],"r":1,"e":"Il en résulte une action réflexe du muscle, une augmentation de l'activité de l'agoniste et donc de la force produite.","s":3},{"q":"Le cycle activé par le pré-étirement porte le nom de :","o":["Cycle d'allongement/raccourcissement","Cycle de Krebs","Cycle réflexe myotatique inverse","Cycle de co-contraction"],"r":0,"e":"Il est expliqué par deux modèles complémentaires : mécanique et neurophysiologique.","s":3},{"q":"Le coût métabolique réduit de la pliométrie s'explique par :","o":["La restitution d'une énergie élastique déjà stockée","Une intensité faible, proche du repos","Des séries longues, à faible charge","L'absence de contraction, le geste étant passif"],"r":0,"e":"C'est l'un des trois arguments du cours, avec l'augmentation de puissance et de vitesse sur intervalles courts.","s":3},{"q":"L'énergie élastique stockée lors de la phase d'étirement :","o":["Est libérée si une contraction suit","Est dissipée dans tous les cas","Ne peut pas être restituée","Provient du métabolisme aérobie"],"r":0,"e":"C'est le cœur du modèle mécanique de la pliométrie.","s":3},{"q":"L'action réflexe décrite dans le modèle neurophysiologique augmente :","o":["L'activité du muscle agoniste","L'activité de l'antagoniste","L'inhibition de l'agoniste","La relaxation"],"r":0,"e":"Le fuseau musculaire, stimulé par l'étirement rapide, en est le point de départ.","s":3},{"q":"La pliométrie sollicite avant tout la qualité :","o":["D'endurance aérobie","De puissance","De souplesse","De mobilité articulaire"],"r":1,"e":"Elle augmente puissance et vitesse sur des intervalles courts.","s":3},{"q":"Le pré-étirement, dans la pliométrie, doit être :","o":["Lent et progressif","Rapide","Maintenu longuement","Passif"],"r":1,"e":"C'est la rapidité de l'étirement qui augmente l'énergie élastique et stimule le fuseau musculaire.","s":3},{"q":"La pliométrie s'inscrit, parmi les cinq piliers de l'exercice thérapeutique :","o":["En quatrième position, après la force","En première position","Avant la mobilité, d'emblée","À la place de la RSM, au dernier rang"],"r":0,"e":"L'ordre est mobilité, souplesse, force, pliométrie, reprogrammation sensorimotrice.","s":3},{"q":"Les deux modèles explicatifs de la pliométrie sont :","o":["Le modèle mécanique et le modèle neurophysiologique","Le modèle métabolique et le modèle cardiovasculaire","Le modèle statique et le modèle dynamique","Le modèle local et le modèle global"],"r":0,"e":"Le premier repose sur l'énergie élastique, le second sur le fuseau musculaire et l'action réflexe.","s":3},{"q":"La normalité de la souplesse est exigée avant la pliométrie parce que :","o":["Le pré-étirement rapide sollicite le muscle en allongement","Elle diminue la force du muscle","Elle augmente le coût métabolique","Elle ralentit le mouvement et allonge la phase de couplage"],"r":0,"e":"Amplitude, force et souplesse normales et absence d'œdème et de douleur constituent les prérequis cités.","s":3},{"q":"La production totale de force en pliométrie résulte :","o":["De la contraction volontaire, à elle seule","De la contraction, de l'énergie élastique et du réflexe","Du seul réflexe myotatique","De la seule énergie élastique, restituée par les tendons"],"r":1,"e":"Les deux modèles s'additionnent, l'un mécanique et l'autre neurophysiologique.","s":3},{"q":"La pliométrie agit sur les composants :","o":["Musculo-tendineux","Osseux","Capsulaires","Cutanés"],"r":0,"e":"C'est l'élasticité de ces composants qui stocke l'énergie lors de l'étirement rapide.","s":3},{"q":"Le caractère « puissant » des mouvements pliométriques signifie qu'ils associent :","o":["Force et vitesse","Force et endurance","Amplitude et lenteur","Résistance et isométrie"],"r":0,"e":"La puissance est précisément le produit de la force par la vitesse.","s":3},{"q":"L'exigence d'une amplitude normale avant la pliométrie tient au fait que :","o":["Le geste rapide utilise toute l'amplitude disponible","L'amplitude n'a aucune importance","La pliométrie augmente l'amplitude","L'amplitude est travaillée en même temps, au cours des sauts"],"r":0,"e":"Une amplitude limitée exposerait à une contrainte en fin de course lors d'un mouvement rapide.","s":3},{"q":"Le fuseau musculaire, dans le modèle neurophysiologique, est sensible :","o":["À la tension tendineuse","À l'étirement rapide","À la température","À la compression articulaire"],"r":1,"e":"Sa stimulation déclenche l'action réflexe qui augmente la force produite.","s":3},{"q":"La RSM vise principalement :","o":["La force maximale, en charge","La qualité du mouvement et le contrôle moteur","La consommation d'oxygène, à l'effort maximal","La masse musculaire, en volume"],"r":1,"e":"RSM = effet direct sur la physiologie neuromusculaire et le contrôle moteur.","s":4},{"q":"Les propriocepteurs incluent :","o":["Les mécanorécepteurs articulaires","Les récepteurs musculaires","Les récepteurs cutanés","Les cônes et les bâtonnets","Les glandes endocrines"],"r":[0,1,2],"e":"Propriocepteurs : articulaires + musculaires + cutanés. La capsule, les ligaments, le fuseau et le motoneurone gamma en font partie.","s":4},{"q":"Rôle des propriocepteurs :","o":["Réguler la tension artérielle","Indiquer la position des segments dans l'espace","Assurer une sécrétion hormonale","Aucun rôle, en dehors de la douleur et de la température"],"r":1,"e":"Fondamentaux pour le contrôle moteur. Ils renseignent aussi dans le temps.","s":4},{"q":"Le cycle vicieux de l'instabilité commence par :","o":["Une maladie cardiaque, puis une fatigue à l'effort","Un dysfonctionnement musculo-squelettique","Un stress mental, chronique","Une hypoglycémie, à jeun"],"r":1,"e":"Dysfonction MSK → ↓ proprio → perte d'activation/stabilisation → schéma moteur altéré. La proprioception baisse ensuite.","s":4},{"q":"Stabilité STRUCTURELLE (passive) :","o":["Le système sensorimoteur, réflexe et rapide","La capsule, les ligaments et la congruence","Le cerveau, par la planification","Le cœur, par la perfusion"],"r":1,"e":"Passive = anatomie passive (capsule, ligaments, surfaces).","s":4},{"q":"Stabilité FONCTIONNELLE (active) :","o":["L'anatomie seule, capsule, ligaments et surfaces","Le système sensorimoteur et les muscles","Aucune structure, en pratique","La posture uniquement, au repos et debout"],"r":1,"e":"Active = dynamique, dépend des muscles et du SN. L'activation est neuromusculaire, par des mécanismes locaux et globaux.","s":4},{"q":"Stabilisation LOCALE :","o":["Un mécanisme réflexe","Un circuit entre mécanorécepteurs et muscles","La vitesse de contraction, plus que la force","Une stabilisation par les chaînes globales","Des schémas de co-contraction"],"r":[0,1,2,4],"e":"Locale : réflexe, vitesse > force, co-contraction. Globale = quadrants.","s":4},{"q":"Stabilisation GLOBALE :","o":["Un réflexe articulaire isolé, local et rapide","Des chaînes, scapulo-thoracique et lombo-pelvienne","Aucune chaîne musculaire, seulement des ligaments","Une stabilisation par le cœur"],"r":1,"e":"Globale = stabilisation proximale par chaînes. Ce sont les quadrants supérieur et inférieur.","s":4},{"q":"Le quadrant supérieur correspond à :","o":["Lombo-pelvien","Scapulo-thoracique","Cervico-céphalique","Plantaire"],"r":1,"e":"Quadrant supérieur = stabilité scapulo-thoracique.","s":4},{"q":"Le quadrant inférieur correspond à :","o":["Scapulo-thoracique","Lombo-pelvien","Cervical","Pied uniquement"],"r":1,"e":"Quadrant inférieur = stabilité lombo-pelvienne.","s":4},{"q":"Les 3 systèmes intégrés pour l'équilibre :","o":["Vestibulaire","Visuel","Proprioceptif","Cardiaque","Digestif"],"r":[0,1,2],"e":"3 piliers de l'équilibre : vestibulaire + visuel + proprioceptif.","s":4},{"q":"Réactions d'équilibre automatiques :","o":["TT (tibio-tarsienne)","Hanche","Pas","Suspension","Genou"],"r":[0,1,2,3],"e":"4 réactions : TT, hanche, pas, suspension.","s":4},{"q":"Le TSM (entraînement sensorimoteur) a été développé par :","o":["George Maitland, en Australie","Vladimir Janda, en Tchéquie","Carl Kaltenborn, en Norvège","Robert Lovett, aux États-Unis"],"r":1,"e":"Janda = TSM, philosophie équilibre > force. Il a vécu de 1928 à 2002.","s":4},{"q":"Selon Janda, dans les activités fonctionnelles :","o":["La force prime sur tout le reste, toujours","L'équilibre et la stabilisation réflexe priment sur la force","L'aérobie prime sur la force et l'équilibre","La souplesse seule prime, quelle que soit l'activité fonctionnelle"],"r":1,"e":"Janda : équilibre/stabilisation réflexe > force pure pour le quotidien.","s":4},{"q":"Avantages du TSM :","o":["Une hausse de l'activité EMG","Une hausse de l'équilibre postural","Une hausse de la proprioception","Une baisse des chutes et des récidives","Une prévention des blessures sportives","Une hausse de la VO2 maximale"],"r":[0,1,2,3,4],"e":"Pas d'effet direct sur la VO2max.","s":4},{"q":"3 points clés du TSM :","o":["La posture neutre des pieds, des lombaires et du cou","La respiration diaphragmatique","Le contrôle du centre de gravité","L'apnée volontaire, pendant l'effort","La force maximale, en charge"],"r":[0,1,2],"e":"3 piliers : posture + respiration + contrôle CG.","s":4},{"q":"Le TSM commence à quel niveau ?","o":["Avec partenaire","Fonctionnel","Statique","Dynamique"],"r":2,"e":"Progression : Statique → Dynamique → Fonctionnel → Avec partenaire.","s":4},{"q":"Niveau STATIQUE :","o":["Des mouvements des membres, sur un sol stable et dur","L'équilibre sur surfaces instables, yeux fermés","Des mouvements fonctionnels, comme le squat","Des activités en binôme, avec un ballon"],"r":1,"e":"Statique : maintien sur surfaces instables progressives. Il comprend aussi des transferts de poids.","s":4},{"q":"Niveau DYNAMIQUE :","o":["Un maintien statique de l'équilibre, yeux fermés","Des mouvements des membres, en gardant l'équilibre","Un travail sans aucun matériel","Des activités exclusivement assises"],"r":1,"e":"Dynamique : ajout de mouvements + matériel d'instabilité. Bandes, ballons et poids légers y sont utilisés.","s":4},{"q":"Niveau FONCTIONNEL :","o":["Un travail statique pur, debout","Des gestes fonctionnels, comme la fente, sur surface instable","Un travail sans aucune charge","Un niveau inutile, à supprimer de la progression du programme"],"r":1,"e":"Fonctionnel : tâches motrices complexes. Le squat et le step en sont d'autres exemples.","s":4},{"q":"Matériel typique du TSM :","o":["Surfaces en mousse","Planches d'équilibre","BOSU","Trampoline","Tapis de course","Haltères lourds"],"r":[0,1,2,3],"e":"4 matériels d'instabilité progressive. Pas tapis de course ni haltères lourds.","s":4},{"q":"Surfaces en mousse — code couleur de difficulté :","o":["Rouge, puis bleue, puis jaune","Verte, puis bleue, puis noire","Un ordre aléatoire, selon la marque","Aucun code, seule l'épaisseur indiquant la difficulté"],"r":1,"e":"Verte (plus dure) → bleue → noire (plus instable). La difficulté est croissante.","s":4},{"q":"L'instabilité progressive est obtenue par :","o":["La base de soutien réduite et le centre de gravité déplacé","L'augmentation progressive des charges, en kilogrammes","L'ajout d'haltères uniquement, sur un sol stable","L'absence de variation, d'une séance à l'autre"],"r":0,"e":"Progression : ↓ BS, déplacement CG, instabilité augmentée.","s":4},{"q":"Mécanismes locaux de stabilisation :","o":["Stabilisation articulaire réflexe","Circuit mécanorécepteurs → muscles péri-articulaires","Schémas de co-contraction","Stabilisation lombo-pelvienne globale","Réaction du quadrant supérieur"],"r":[0,1,2],"e":"Locaux : réflexes péri-articulaires. Globaux = chaînes.","s":4},{"q":"Le motoneurone gamma intervient dans :","o":["Le contrôle du rythme cardiaque","La sensibilité du fuseau musculaire à l'étirement","La sécrétion d'adrénaline","La vision, par le réglage du cristallin et de la pupille"],"r":1,"e":"Gamma = sensibilité du fuseau musculaire.","s":4},{"q":"Une dysfonction MSK altère la proprioception parce que :","o":["Aucun lien n'existe entre les deux","Elle modifie les afférences des mécanorécepteurs","Elle active uniquement la vision","Elle n'a aucun rapport avec le système nerveux"],"r":1,"e":"Lésion articulaire → ↓ informations proprioceptives → schémas moteurs altérés.","s":4},{"q":"Le TSM avec partenaire est :","o":["Le niveau initial du programme","Le niveau avancé, en binôme ou en groupe","Un niveau inutile, à éviter en rééducation fonctionnelle","Un niveau réservé aux enfants"],"r":1,"e":"Avec partenaire = niveau final, activités complexes en binôme. Il se pratique sur surfaces instables.","s":4},{"q":"Le TSM aide à :","o":["Augmenter la force pure, à l'EMG","Améliorer l'activité EMG et la réaction","Réduire la digestion, après les repas","Baisser la tension artérielle, au repos"],"r":1,"e":"Bénéfices neuromusculaires (EMG, activation, vitesse). Les schémas d'activation s'améliorent aussi.","s":4},{"q":"Pour la prévention des récidives, le TSM est :","o":["Inutile, faute de preuve scientifique solide et récente","Très efficace, contre les chutes et les récidives","Dangereux, à l'âge adulte","Sans aucune preuve, ni pour ni contre"],"r":1,"e":"Études soutiennent l'efficacité du TSM pour la prévention.","s":4},{"q":"Sur surface instable, la posture neutre des pieds, lombaires et cervicales est :","o":["Optionnelle, selon le confort","Essentielle, comme premier point clé","Inutile, sur surface instable","À éviter, car elle fige le mouvement et limite la réaction"],"r":1,"e":"Posture neutre = base de stabilité réflexe. C'est le premier point clé de Janda.","s":4},{"q":"La reprogrammation sensorimotrice vise à maintenir ou améliorer :","o":["La qualité du mouvement et le contrôle moteur","L'amplitude articulaire, passive","La longueur des fibres musculaires, par des étirements longs","La puissance musculaire, explosive"],"r":0,"e":"C'est le cinquième pilier de l'exercice thérapeutique. Elle agit directement sur la physiologie neuromusculaire.","s":4},{"q":"Les mécanorécepteurs articulaires siègent :","o":["Dans la capsule et les ligaments","Dans le tendon, uniquement","Dans le muscle, uniquement","Dans la peau, uniquement, sous l'épiderme"],"r":0,"e":"Les récepteurs musculaires, avec le motoneurone gamma, et les récepteurs cutanés complètent le système proprioceptif.","s":4},{"q":"Le rôle des propriocepteurs est d'indiquer :","o":["La position des segments dans l'espace et le temps","La force développée par le muscle, en newtons","La température de la peau, au contact","La douleur, par les nocicepteurs"],"r":0,"e":"Ils sont fondamentaux pour le contrôle et la qualité du mouvement.","s":4},{"q":"Le cycle vicieux de l'instabilité débute par :","o":["Un dysfonctionnement musculo-squelettique","Un programme moteur altéré","Un modèle de mouvement anormal","Une perte d'activation musculaire, autour de l'articulation"],"r":0,"e":"Il entraîne une baisse de proprioception, puis une perte d'activation, un programme moteur altéré et un mouvement anormal — qui relance le cycle.","s":4},{"q":"La stabilité structurelle, dite passive, repose sur :","o":["La capsule, les ligaments et la congruence articulaire","Le système sensorimoteur, réflexe, et l'activation des muscles","L'activation neuromusculaire","Les chaînes musculaires, globales"],"r":0,"e":"La stabilité fonctionnelle, active, repose au contraire sur le système sensorimoteur et l'activation neuromusculaire.","s":4},{"q":"La stabilisation articulaire réflexe, mécanisme local, repose sur :","o":["Un circuit entre récepteurs articulaires et muscles","Les chaînes neuromusculaires proximales, globales","Le système vestibulaire, dans l'oreille","La force maximale, développée par le muscle"],"r":0,"e":"Elle se réalise par des schémas de co-contraction.","s":4},{"q":"Dans la stabilisation réflexe locale, ce qui compte le plus est :","o":["La force du muscle elle-même","La réaction réflexe et la vitesse de contraction","L'amplitude disponible, sur toute la course articulaire","L'endurance du muscle, au long cours"],"r":1,"e":"C'est l'un des arguments centraux de Janda : l'équilibre et la stabilisation réflexe priment sur la force dans les activités fonctionnelles.","s":4},{"q":"La stabilisation globale du quadrant supérieur correspond à :","o":["La stabilité scapulo-thoracique","La stabilité lombo-pelvienne","La stabilité de la cheville","La stabilité cervicale"],"r":0,"e":"Le quadrant inférieur correspond, lui, à la stabilité lombo-pelvienne.","s":4},{"q":"Les réactions d'équilibre automatiques citées par le cours sont :","o":["Tibio-tarsienne, hanche, pas et suspension","Cheville et hanche uniquement","Pas et protection","Vestibulaire, visuelle et proprioceptive"],"r":0,"e":"L'équilibre lui-même résulte de l'intégration des systèmes vestibulaire, visuel et proprioceptif.","s":4},{"q":"Vladimir Janda a vécu de :","o":["1928 à 2002","1900 à 1975","1940 à 2010","1950 à 2015"],"r":0,"e":"Il a défendu l'idée que l'équilibre et la stabilisation réflexe importent davantage que la force dans les activités fonctionnelles.","s":4},{"q":"Parmi les avantages de l'entraînement sensorimoteur, le cours cite :","o":["Une hausse de l'activité mesurée en EMG","Une hausse de la masse musculaire, à l'IRM","Une hausse de l'amplitude passive, mesurée au goniomètre","Une baisse du tonus, au repos"],"r":0,"e":"S'y ajoutent l'amélioration des schémas d'activation et des temps de réaction, de l'équilibre, de la proprioception et de la force.","s":4},{"q":"L'entraînement sensorimoteur permet notamment :","o":["De diminuer le risque de chutes et de récidives","D'augmenter la vitesse de course, sur sprint court et long","D'augmenter la capacité aérobie","De réduire la masse grasse"],"r":0,"e":"Il prévient et réduit également les blessures sportives.","s":4},{"q":"Les trois points clés du TSM sont :","o":["La posture, la respiration et le centre de gravité","La force, la vitesse et l'endurance","L'amplitude, la souplesse et la force","Les niveaux statique, dynamique et fonctionnel"],"r":0,"e":"La posture concerne les pieds, les lombaires et les cervicales, en position neutre ; le contrôle du centre de gravité s'accompagne de mouvements excentriques. La respiration est diaphragmatique.","s":4},{"q":"Le niveau statique du TSM comprend notamment :","o":["L'équilibre sur surfaces instables et l'appui unipodal","L'ajout de mouvements des membres","Des gestes fonctionnels, comme le squat, la fente et le step","Des activités en binôme, avec ballon"],"r":0,"e":"Les mouvements de la tête et la variation des bases d'appui s'y ajoutent. Les transferts de poids et les yeux fermés en font aussi partie.","s":4},{"q":"Le niveau dynamique du TSM consiste à :","o":["D'ajouter des mouvements des membres en gardant l'équilibre","De maintenir une position statique, yeux fermés","De réaliser des squats et des fentes, sur un sol stable","De travailler en binôme, avec un partenaire"],"r":0,"e":"Bandes, flexbars, ballons et poids légers y sont utilisés.","s":4},{"q":"Le niveau fonctionnel du TSM utilise :","o":["Le squat, la fente et le step, sur surface instable","Le seul maintien statique","Des mouvements des membres, en position stable","Des activités de groupe, en binôme, avec des jeux de ballon"],"r":0,"e":"Le niveau avec partenaire ajoute ensuite des activités dynamiques en binôme ou en groupe.","s":4},{"q":"Le matériel du TSM comprend :","o":["Mousses, planches d'équilibre, BOSU et trampoline","Des haltères, des barres et des machines de musculation","Des élastiques, uniquement","Un tapis de course et un TRX"],"r":0,"e":"Les surfaces en mousse sont codées par couleur — verte, bleue, noire — selon la difficulté.","s":4},{"q":"La progression complète du TSM est :","o":["Statique → dynamique → fonctionnel → avec partenaire","Fonctionnel → dynamique → statique → avec partenaire","Dynamique → statique → fonctionnel","Avec partenaire → fonctionnel → statique"],"r":0,"e":"Chaque niveau s'accompagne de surfaces instables progressives.","s":4},{"q":"La respiration recommandée pendant le TSM est :","o":["Diaphragmatique","En apnée","Thoracique haute","Forcée"],"r":0,"e":"Elle figure parmi les trois points clés, avec la posture neutre et le contrôle du centre de gravité.","s":4},{"q":"La stabilité fonctionnelle repose sur des mécanismes :","o":["Locaux et globaux","Locaux uniquement","Globaux uniquement","Purement passifs"],"r":0,"e":"Les mécanismes locaux relèvent de la stabilisation articulaire réflexe, les globaux des chaînes neuromusculaires proximales.","s":4},{"q":"Les exercices de souplesse visent à :","o":["Augmenter la force, en charge","Améliorer l'amplitude, par un effet sur la fibre","Diminuer la masse osseuse, par un effet de décharge","Augmenter la consommation d'oxygène"],"r":1,"e":"Souplesse = amplitude + effet direct sur la fibre musculaire. Ils peuvent aussi la maintenir.","s":5},{"q":"La souplesse est la capacité à :","o":["Sauter haut, sans élan, à pieds joints, plusieurs fois","Faire des mouvements amples, seul ou aidé","Tenir longtemps une position","Marcher loin, sans s'arrêter"],"r":1,"e":"Souplesse = mouvements amples (autonomes ou assistés). L'aide est une influence externe.","s":5},{"q":"Facteurs influençant la souplesse :","o":["La mobilité et la stabilité","L'âge et le sexe du sujet","L'hérédité familiale","L'entraînement et l'activité","Les suites d'un traumatisme","La couleur des vêtements"],"r":[0,1,2,3,4],"e":"5 facteurs (sauf couleur des vêtements). Les modifications liées à l'inactivité comptent aussi.","s":5},{"q":"L'étirement STATIQUE consiste à :","o":["Faire de grands mouvements, en balancier rapide et répété","Maintenir des postures qui alignent le muscle","Sauter sur place, en rythme","Faire vibrer le muscle, à haute fréquence"],"r":1,"e":"Statique = maintien d'une posture.","s":5},{"q":"L'étirement DYNAMIQUE :","o":["La capacité à faire des mouvements de grande amplitude","Le maintien fixe d'une posture","L'absence de mouvement, avec une contraction maintenue","Une vibration, appliquée au muscle"],"r":0,"e":"Dynamique = mouvements amples actifs.","s":5},{"q":"L'étirement PASSIF :","o":["Une modification autonome de la fibre","Des forces extérieures qui modifient la fibre","Une absence totale de force","Un étirement à grande vitesse, par rebonds répétés"],"r":1,"e":"Passif : forces externes (kiné, gravité, partenaire). Ces forces sont le kinésithérapeute, la gravité ou un partenaire.","s":5},{"q":"L'étirement ACTIF :","o":["Une force externe, du thérapeute","Une modification autonome, par le patient","Une absence de contraction, au repos","Un travail avec poids, attachés aux chevilles ou aux poignets"],"r":1,"e":"Actif : par le patient sans aide externe.","s":5},{"q":"Avantages des étirements :","o":["Une hausse de l'amplitude articulaire","Une meilleure activation agoniste-antagoniste","Une hausse de l'énergie élastique accumulée","Une baisse du stress articulaire","Une hausse de la vascularisation musculaire","Une baisse du risque lésionnel","Une hausse immédiate de la force maximale"],"r":[0,1,2,3,4,5],"e":"6 avantages majeurs des étirements. Un étirement statique prolongé diminue transitoirement la force et la puissance : c'est pourquoi on le place plutôt après l'effort.","s":5},{"q":"Effets sur le tissu CONTRACTILE :","o":["Aucun effet sur les fibres, seulement sur le tendon","Des fibres plus longues et mieux alignées","Une rupture des fibres, partielle","Une atrophie musculaire, rapide"],"r":1,"e":"Tissu contractile : ↑ longueur/alignement des fibres.","s":5},{"q":"Effets sur le tissu CONJONCTIF :","o":["Une faiblesse structurelle du tissu, durable","Une déformation accrue, sans faiblesse induite","Une rupture des fibres de collagène","Une calcification du tendon"],"r":1,"e":"Tissu conjonctif : ↑ déformabilité, pas de faiblesse induite.","s":5},{"q":"Position recommandée pour l'étirement :","o":["Tendu et anxieux, en contraction","Détendu, dans une posture équilibrée et confortable","En apnée, pour mieux fixer le tronc et la cage thoracique","En contraction maximale du muscle"],"r":1,"e":"Détendu + posture confortable favorisent l'étirement.","s":5},{"q":"Température recommandée :","o":["Froide, pour limiter l'inflammation","Adéquate, car le froid réduit la viscoélasticité","Très chaude, au-delà de 40 °C","Indifférente, la température n'ayant aucun effet sur le tissu"],"r":1,"e":"Le froid ↓ les propriétés viscoélastiques → moins d'efficacité. Le froid diminue les propriétés viscoélastiques.","s":5},{"q":"L'étirement provoque :","o":["Une douleur intense, nécessaire","Une gêne, mais pas une douleur","Aucune sensation, même en fin d'amplitude","Un spasme du muscle étiré"],"r":1,"e":"Gêne = OK ; douleur = signe de lésion potentielle.","s":5},{"q":"L'effet sur l'énergie élastique :","o":["↓","↑ accumulation","Aucun","Annulation"],"r":1,"e":"Étirements → ↑ stockage d'énergie élastique.","s":5},{"q":"L'étirement permet :","o":["De passer rapidement du passif à l'actif","De rester passif uniquement","D'éliminer toute contraction","Aucun changement, ni dans le muscle ni dans le tendon"],"r":0,"e":"Capacité à passer du passif à l'actif rapidement.","s":5},{"q":"Effet sur les contraintes articulaires :","o":["Une hausse du stress articulaire","Une baisse des forces de stress articulaire","Aucun effet notable, à long terme","Une compression accrue des cartilages, en charge prolongée"],"r":1,"e":"Étirements → ↓ stress articulaire.","s":5},{"q":"Effet sur la vascularisation musculaire :","o":["↓","↑","Aucun","Variable"],"r":1,"e":"Étirements → ↑ vascularisation locale.","s":5},{"q":"Le risque de lésions musculo-tendineuses avec étirements :","o":["↑","↓","Inchangé","Imprédictible"],"r":1,"e":"Étirements → ↓ risque lésionnel global.","s":5},{"q":"Pour un mouvement de grande amplitude rapide, on utilise :","o":["Étirement statique","Étirement dynamique","Aucun étirement","Massage"],"r":1,"e":"Dynamique = entraînement à l'amplitude en mouvement.","s":5},{"q":"Pour induire la relaxation, on préfère :","o":["Dynamique rapide","Statique long","PNF intense","Vibration"],"r":1,"e":"Statique long et soutenu → relaxation.","s":5},{"q":"Le moment de la séance pour les étirements dépend :","o":["Toujours en début de séance, à froid","Toujours en fin de séance","Des objectifs visés par la séance","D'aucune logique particulière"],"r":2,"e":"Selon l'objectif : échauffement (dynamique), récupération (statique), etc.","s":5},{"q":"Un étirement actif est généralement :","o":["Plus risqué que passif","Plus sûr et autonome","Identique au passif","Inutile"],"r":1,"e":"Actif = patient contrôle la tension → plus sûr.","s":5},{"q":"L'effet activation agoniste/antagoniste :","o":["↓","↑ activation du couple","Aucun changement","Inversion"],"r":1,"e":"Étirements → ↑ activation du couple agoniste/antagoniste.","s":5},{"q":"Pour un objectif de souplesse à long terme :","o":["Une seule séance occasionnelle, très longue et intense","Une pratique régulière, plusieurs fois par semaine","Un étirement violent, en force","Une vibration, appliquée au muscle"],"r":1,"e":"La régularité est clé pour les gains à long terme.","s":5},{"q":"L'étirement passif est typiquement effectué par :","o":["Le patient seul","Le kinésithérapeute","Un appareil","Aucun"],"r":1,"e":"Passif : forces externes (kinésithérapeute, gravité).","s":5},{"q":"L'étirement statique impacte surtout :","o":["La force pure, maximale","La longueur des tissus","La vitesse du geste, explosive","Le poids du corps, par la perte de masse grasse"],"r":1,"e":"Statique : modification durable de la longueur tissulaire. La modification est durable.","s":5},{"q":"Avant un sport explosif, on privilégie :","o":["Des étirements statiques longs","Des étirements dynamiques, actifs","Aucun étirement, avant l'effort","Un massage profond, prolongé"],"r":1,"e":"Dynamique avant sport (statique long peut ↓ explosivité). Les étirements statiques longs peuvent réduire la performance.","s":5},{"q":"L'âge a un impact sur la souplesse :","o":["Aucun impact, quel que soit l'âge","Une baisse avec l'âge, mais l'entraînement la limite","Une hausse avec l'âge, par le relâchement progressif des tissus","Aucune relation, chez l'adulte"],"r":1,"e":"Souplesse ↓ avec l'âge, mais entraînement compense.","s":5},{"q":"L'inactivité prolongée induit :","o":["Une souplesse maximale, au repos","Une baisse de souplesse, par modifications tissulaires","Aucun effet, ni sur la souplesse","Une hausse de la performance, par le repos prolongé des muscles"],"r":1,"e":"Inactivité → raccourcissement musculaire → ↓ souplesse.","s":5},{"q":"Les femmes sont en général :","o":["Moins souples que les hommes","Plus souples que les hommes","Aussi souples que les hommes","Plus souples uniquement à la naissance, puis comme les hommes"],"r":1,"e":"Souplesse globalement plus élevée chez la femme (laxité ligamentaire, hormones). Les différences sont hormonales et anatomiques.","s":5},{"q":"Les exercices de souplesse visent, outre l'amplitude articulaire :","o":["À améliorer la production motrice et à détendre","À augmenter la puissance, par le cycle d'étirement-détente","À augmenter la masse musculaire","À améliorer la capacité aérobie"],"r":0,"e":"Leur effet porte directement sur la fibre musculaire, contrairement à la mobilité qui agit sur la physiologie articulaire. Ils induisent une relaxation.","s":5},{"q":"La souplesse se définit comme la capacité à effectuer des mouvements amples :","o":["De façon autonome ou sous influence externe","De façon autonome, uniquement","Sous influence externe, uniquement","À vitesse constante, imposée par une machine isocinétique"],"r":0,"e":"Elle s'accompagne d'une augmentation de la longueur et de l'alignement des fibres musculaires.","s":5},{"q":"Parmi les facteurs influençant la souplesse, le cours cite :","o":["L'âge, le sexe, l'hérédité et l'entraînement","La seule hérédité, familiale","Le seul entraînement, quel que soit l'âge ou le sexe du sujet","La seule température, ambiante"],"r":0,"e":"Cette pluralité explique les grandes différences interindividuelles. La mobilité/stabilité et les modifications post-traumatiques ou d'inactivité en font aussi partie.","s":5},{"q":"L'étirement dynamique se définit comme :","o":["Le maintien de postures qui alignent le muscle","La capacité à faire des mouvements de grande amplitude","Une force extérieure qui modifie la fibre","Une modification autonome de la fibre, sans aucun mouvement"],"r":1,"e":"L'étirement statique consiste, lui, à maintenir des postures impliquant un alignement musculaire.","s":5},{"q":"L'étirement passif se définit comme :","o":["Une modification autonome de la fibre, active","Des forces extérieures qui modifient la fibre","Un maintien de posture, en alignement","Un mouvement de grande amplitude, actif"],"r":1,"e":"L'étirement actif correspond, lui, à une modification autonome de la fibre.","s":5},{"q":"Parmi les avantages de la souplesse, le cours cite :","o":["L'augmentation de l'énergie élastique accumulée","L'augmentation de la masse musculaire, par hypertrophie","L'augmentation de la force maximale","L'amélioration du débit cardiaque"],"r":0,"e":"S'y ajoutent l'augmentation de l'amplitude, de l'activation du couple agoniste/antagoniste et de la vascularisation musculaire.","s":5},{"q":"La souplesse améliore la capacité à :","o":["Passer rapidement du passif à l'actif","Maintenir une contraction isométrique longue","Produire une force maximale","Augmenter la fréquence cardiaque"],"r":0,"e":"Elle permet également d'induire la relaxation et de diminuer les forces de stress articulaire.","s":5},{"q":"L'effet de l'étirement sur le tissu contractile est :","o":["Des fibres plus longues et mieux alignées","Des fibres plus courtes, rétractées","Une rupture des fibres, partielle, réparée par la cicatrisation","Une hypertrophie des fibres"],"r":0,"e":"Sur le tissu conjonctif intramusculaire et tendineux, l'effet est une capacité de déformation accrue. Le tissu conjonctif gagne, lui, en capacité de déformation.","s":5},{"q":"L'effet de l'étirement sur le tissu conjonctif se fait :","o":["Avec un affaiblissement structurel","Sans induction de faiblesse structurelle","Par rupture des fibres de collagène","Par diminution de la déformabilité"],"r":1,"e":"Cette précision du cours répond à la crainte classique d'un tendon fragilisé par l'étirement.","s":5},{"q":"Le froid, dans le contexte de l'étirement :","o":["Augmente les propriétés viscoélastiques","Diminue les propriétés viscoélastiques","Est sans effet","Améliore l'amplitude"],"r":1,"e":"C'est pourquoi le cours recommande une température adéquate avant d'étirer.","s":5},{"q":"L'étirement doit provoquer :","o":["Une douleur franche, contrôlée","Une gêne, mais pas une douleur","Aucune sensation, même légère","Une brûlure, superficielle"],"r":1,"e":"Cette distinction constitue le repère de dosage principal de la séance d'étirement.","s":5},{"q":"La position recommandée pour l'étirement est :","o":["Patient détendu, posture équilibrée et confortable","Patient en contraction active du muscle à étirer","Patient en appui unipodal, sans aide","Patient en apnée, tronc bloqué"],"r":0,"e":"Le relâchement conditionne l'accès au tissu contractile plutôt que la lutte contre une contraction de défense.","s":5},{"q":"Le moment de la séance où placer les étirements :","o":["Est toujours le début","Est toujours la fin","Dépend des objectifs","Est indifférent"],"r":2,"e":"Le cours indique explicitement des moments différents selon les objectifs poursuivis.","s":5},{"q":"La souplesse diminue les forces :","o":["De stress articulaire","De contraction musculaire","De réaction du sol","De cisaillement tendineux uniquement"],"r":0,"e":"Elle diminue aussi le risque de lésions musculo-tendineuses et augmente la vascularisation musculaire.","s":5},{"q":"L'augmentation de l'activation du couple agoniste/antagoniste par la souplesse traduit :","o":["Un effet neuromusculaire, en plus de l'effet tissulaire","Un effet purement mécanique, lié à la viscoélasticité","Une hypertrophie des fibres, par la mise en tension","Un effet cardiovasculaire, par la hausse du débit"],"r":0,"e":"Cet effet complète l'allongement des fibres et la déformabilité du tissu conjonctif.","s":5},{"q":"Les modifications post-traumatiques influencent la souplesse au même titre que :","o":["L'inactivité","La fréquence cardiaque","La capacité aérobie","La composition corporelle"],"r":0,"e":"Les deux figurent dans le même item de la liste des facteurs influençant la souplesse.","s":5},{"q":"L'étirement statique se caractérise par :","o":["Le maintien de postures qui alignent le muscle","Des mouvements de grande amplitude, répétés","Une force externe, appliquée par le thérapeute seul","Une alternance de contraction et de relâchement"],"r":0,"e":"Il s'oppose à l'étirement dynamique dans la classification par description du mouvement.","s":5},{"q":"La classification des étirements du cours distingue :","o":["Statique, dynamique, passif et actif","Statique et balistique, seulement","Passif, actif assisté et PNF, seulement","Actif, isométrique et excentrique"],"r":0,"e":"Les deux premiers décrivent le mouvement, les deux suivants l'origine de la force appliquée.","s":5},{"q":"L'augmentation de la vascularisation musculaire figure parmi :","o":["Les avantages des étirements","Les facteurs influençant la souplesse","Les effets sur le tissu conjonctif","Les idées clés de la séance"],"r":0,"e":"Elle y côtoie la diminution du risque de lésions musculo-tendineuses.","s":5},{"q":"La souplesse se définit sur le plan tissulaire par :","o":["Des fibres musculaires plus longues et mieux alignées","Une augmentation du nombre de fibres musculaires","Une augmentation de la section du muscle entier","Une diminution du tissu conjonctif entre les fibres musculaires"],"r":0,"e":"C'est l'effet direct sur la fibre qui la distingue de la mobilité.","s":5},{"q":"L'étymologie de « goniométrie » signifie :","o":["Articulation + mesure","Angle + mesure","Mouvement + mesure","Force + mesure"],"r":1,"e":"Du grec : gonion (angle) + metron (mesure).","s":6},{"q":"La goniométrie est indiquée dans quelles situations ?","o":["En postopératoire, après une suture méniscale","En cas de douleur chronique, au coude par exemple","Après un AVC, pour suivre la récupération","Après une hospitalisation prolongée avec alitement","Chez un patient asymptomatique, sans aucune plainte"],"r":[0,1,2,3],"e":"Indications : postop, douleur chronique, AVC, alitement. Pas pour un patient asymptomatique sans plainte.","s":6},{"q":"La goniométrie se réalise :","o":["Avant tout examen, dès l'arrivée du patient","Après l'examen subjectif, l'observation et la palpation","Sans examen préalable, d'emblée en première intention","Uniquement au laboratoire, avec un matériel dédié"],"r":1,"e":"Examen subjectif → observation → palpation → goniométrie.","s":6},{"q":"Parmi les objectifs de la goniométrie :","o":["Déterminer la présence de lésions","Établir un diagnostic kinésithérapique","Évaluer les progrès","Adapter les orthèses/prothèses","Diagnostiquer un cancer"],"r":[0,1,2,3],"e":"4 objectifs principaux. Le diagnostic de cancer relève de la médecine.","s":6},{"q":"Les articulations fibreuses incluent :","o":["La synchondrose, entre deux pièces osseuses","La symphyse, comme la symphyse pubienne","Les sutures plate, squameuse, dentelée et la syndesmose","L'articulation synoviale, avec sa capsule et sa cavité"],"r":2,"e":"Fibreuses : sutures et syndesmoses. Cartilagineuses : synchondrose/symphyse.","s":6},{"q":"Les articulations synoviales contiennent :","o":["Du tissu osseux uniquement, sans cavité articulaire","Cartilage, cavité, capsule, liquide synovial et ligaments","Du tissu fibreux uniquement, comme les sutures de la voûte","De la moelle osseuse, entre les surfaces articulaires"],"r":1,"e":"Articulations synoviales : 5 éléments + parfois disques/ménisques/membranes.","s":6},{"q":"Le glissement est un déplacement :","o":["Axial autour d'un axe","Linéaire","Angulaire","De compression"],"r":1,"e":"Glissement = déplacement linéaire (translation).","s":6},{"q":"Le roulement correspond à :","o":["Un déplacement linéaire","Un déplacement axial","Un déplacement angulaire","Une rotation pure"],"r":2,"e":"Roulement = déplacement angulaire. Rotation = axiale autour d'un axe fixe.","s":6},{"q":"Que se passe-t-il pour l'amplitude lorsqu'il y a combinaison glissement + roulement ?","o":["Elle diminue","Elle reste identique","Elle augmente","Elle s'inverse"],"r":2,"e":"La combinaison glissement + roulement augmente l'amplitude articulaire.","s":6},{"q":"L'AROM correspond à :","o":["Amplitude active produite volontairement","Amplitude passive par l'évaluateur","Amplitude active assistée","Amplitude maximale"],"r":0,"e":"AROM = Active Range Of Motion, produite volontairement sans assistance.","s":6},{"q":"Normalement, on observe :","o":["PROM < AROM","PROM > AROM","PROM = AROM","Aucune relation"],"r":1,"e":"PROM > AROM car indépendante de la force musculaire et de la cognition.","s":6},{"q":"Une douleur en AROM oriente vers une atteinte :","o":["Des tissus contractiles, muscles et tendons","De la capsule articulaire, uniquement","Des ligaments, uniquement, sans le muscle","Du cartilage articulaire, uniquement"],"r":0,"e":"AROM teste les structures contractiles : muscles et tendons.","s":6},{"q":"Le PROM permet d'évaluer :","o":["Les surfaces articulaires","La capsule","Les ligaments","Les fascias et la peau","La force musculaire"],"r":[0,1,2,3],"e":"PROM évalue les tissus non contractiles. La force se teste avec AROM/résistance.","s":6},{"q":"Le plan sagittal divise le corps :","o":["En antérieur et postérieur","En droite et gauche","En supérieur et inférieur","En interne et externe"],"r":1,"e":"Plan sagittal (médian) : droite/gauche. Axe médial-latéral.","s":6},{"q":"Dans quel plan se produit la flexion ?","o":["Frontal","Transversal","Sagittal","Aucun"],"r":2,"e":"Flexion et extension = plan sagittal, axe médial-latéral.","s":6},{"q":"L'abduction et l'adduction se font dans le plan :","o":["Sagittal","Frontal","Transversal","Axial"],"r":1,"e":"Frontal (coronal), axe antéro-postérieur.","s":6},{"q":"Les rotations médiale/latérale se produisent dans le plan :","o":["Sagittal, autour de l'axe médio-latéral","Frontal, autour de l'axe sagittal","Transversal, autour de l'axe vertical","Aucun plan, la rotation étant axiale"],"r":2,"e":"Plan transversal autour de l'axe vertical.","s":6},{"q":"La position de référence pour toute mesure ROM est :","o":["Position de repos","Position fonctionnelle","Position anatomique","Position de Trendelenburg"],"r":2,"e":"Position anatomique (ou neutre pour les rotations).","s":6},{"q":"Facteurs influençant la ROM :","o":["Âge","Sexe","IMC","Heure de la journée","Couleur des vêtements","Expérience de l'évaluateur"],"r":[0,1,2,3,5],"e":"Tous sauf la couleur des vêtements.","s":6},{"q":"L'hypomobilité est :","o":["Une augmentation nette de l'amplitude","Une diminution substantielle de l'amplitude","Une absence complète de mouvement articulaire","Un mouvement instable, en fin d'amplitude"],"r":1,"e":"Hypomobilité = ↓ ROM par rapport aux valeurs de référence.","s":6},{"q":"Causes de l'hypomobilité :","o":["La douleur","Le raccourcissement musculaire","L'inflammation","L'immobilisation","Le syndrome de Marfan"],"r":[0,1,2,3],"e":"Marfan → hypermobilité par laxité. Les autres causent l'hypomobilité.","s":6},{"q":"L'hypermobilité est typiquement associée à :","o":["L'arthrose","Le syndrome de Marfan","La capsulite rétractile","L'ostéoporose"],"r":1,"e":"Marfan → laxité tissulaire → hypermobilité ligamentaire.","s":6},{"q":"Qui a décrit les types d'end-feel ?","o":["Mulligan, Maitland, McKenzie","Cyriax, Kaltenborn, Paris","Janda, Lewit, Jull","Kendall, Daniels, Worthingham"],"r":1,"e":"Cyriax, Kaltenborn, Paris sont les auteurs majeurs.","s":6},{"q":"Un end-feel souple normal correspond à :","o":["Un étirement musculaire passif","Une approximation des tissus mous","Un contact dur, os contre os","Un spasme musculaire réflexe"],"r":1,"e":"Ex : flexion du genou (mollet contre cuisse).","s":6},{"q":"Un end-feel ferme normal correspond à :","o":["Une approximation des tissus mous entre eux","Un étirement des tissus non contractiles","Un contact dur entre les deux os","Un spasme protecteur du muscle"],"r":1,"e":"Étirement capsulaire/ligamentaire (ex : flexion hanche genou tendu).","s":6},{"q":"Un end-feel dur normal correspond à :","o":["Tissus mous","Tissus non contractiles","Contact os contre os","Spasme"],"r":2,"e":"Ex : extension du coude (olécrane vs fosse olécranienne).","s":6},{"q":"L'end-feel « vide » indique :","o":["Une articulation normale, sans aucune lésion","Une pathologie grave, comme une fracture","Une raideur capsulaire, chronique","Une simple hypomobilité, réversible"],"r":1,"e":"End-feel vide = douleur intense empêche le mouvement. CI à la mobilisation. Il peut s'agir d'une inflammation aiguë, d'une bursite ou d'une fracture.","s":6},{"q":"Un end-feel « spasme » signe :","o":["Une déchirure musculaire, récente et étendue","Une réaction protectrice à la douleur","Une fracture déplacée de l'os","Une luxation de l'articulation"],"r":1,"e":"Spasme = arrêt brutal par contraction réflexe protectrice.","s":6},{"q":"Un end-feel « ressort » (mola) évoque :","o":["Une articulation normale, en fin de course","Un corps libre articulaire ou une lésion méniscale","Une raideur ligamentaire, après une longue immobilisation","Une bursite, avec un gonflement local"],"r":1,"e":"End-feel ressort = rebond. Mobilisation contre-indiquée.","s":6},{"q":"L'arthrocinématique étudie :","o":["Le mouvement osseux global, mesuré au goniomètre","Les mouvements entre les surfaces articulaires","Les forces musculaires autour de l'articulation","La conduction nerveuse, motrice et sensitive"],"r":1,"e":"Arthrocinématique = mouvements entre les surfaces articulaires (glissement/roulement/rotation).","s":6},{"q":"Parmi les situations d'indication de la goniométrie, le cours cite :","o":["Le postopératoire, la douleur chronique et l'alitement prolongé","Le seul postopératoire, à l'exclusion de toute autre situation","Le bilan sportif, avant la reprise de la compétition","Le dépistage scolaire, chez l'enfant et l'adolescent"],"r":0,"e":"La suture méniscale et la sternotomie médiane sont les exemples postopératoires donnés. L'après-AVC en fait aussi partie.","s":6},{"q":"Parmi les objectifs de la goniométrie, le cours cite :","o":["La fabrication d'orthèses et l'adaptation des équipements","La mesure de la force musculaire au dynamomètre","L'évaluation de l'endurance, sur un effort prolongé","Le dosage de l'effort, selon la fréquence cardiaque"],"r":0,"e":"S'y ajoutent le diagnostic, le pronostic, le suivi des progrès, la modification du traitement, la motivation et l'étude de l'efficacité des techniques. Les prothèses sont aussi concernées.","s":6},{"q":"Les articulations fibreuses comprennent :","o":["Les sutures plate, squameuse et dentelée, et la syndesmose","La synchondrose et la symphyse, comme au pubis","Le cartilage articulaire, la capsule et le liquide synovial","Les disques et les ménisques, entre les surfaces"],"r":0,"e":"Synchondrose et symphyse sont cartilagineuses ; les synoviales comportent cartilage, cavité, capsule, liquide synovial et ligaments.","s":6},{"q":"Les trois types de mouvements possibles d'un segment osseux sont :","o":["Glissement, rotation et roulement","Flexion, extension et rotation","Translation, compression et traction","Abduction, adduction et circumduction"],"r":0,"e":"Le glissement est un déplacement linéaire, la rotation un déplacement axial autour d'un axe fixe et le roulement un déplacement angulaire.","s":6},{"q":"Dans le corps, la combinaison glissement + roulement :","o":["Augmente l'amplitude articulaire","Diminue l'amplitude du mouvement","Bloque le mouvement en fin de course","Est sans effet sur l'amplitude finale"],"r":0,"e":"Glissements, rotations et roulements s'y combinent systématiquement.","s":6},{"q":"L'amplitude de mouvement se définit comme :","o":["L'arc, en degrés, entre le début et la fin du mouvement","La force maximale développée, en newtons, sur le mouvement","La vitesse du mouvement, en degrés par seconde","Le nombre de répétitions possibles, sans douleur"],"r":0,"e":"Elle se décline en AROM active, PROM passive et AAROM active assistée. Il est mesuré dans un plan donné.","s":6},{"q":"L'AAROM, amplitude active assistée :","o":["Est mesurée systématiquement","N'est habituellement pas mesurée","Remplace la PROM","Est toujours supérieure à la PROM"],"r":1,"e":"Elle correspond au mouvement produit par le patient avec assistance.","s":6},{"q":"L'AROM dépend notamment :","o":["De la force et de la cognition","De la seule capsule","Des seuls ligaments","De la seule capsule et des fascias"],"r":0,"e":"La PROM, indépendante de la force, est normalement supérieure à l'AROM.","s":6},{"q":"Une douleur en PROM oriente vers :","o":["Un étirement ou un pincement de tissus non contractiles","Une contraction des tissus contractiles du muscle","Une atteinte purement nerveuse, de type radiculaire","Une simulation, sans aucune lésion objective"],"r":0,"e":"La PROM évalue les surfaces articulaires, la capsule, les ligaments, les fascias et la peau.","s":6},{"q":"Le plan frontal est orienté :","o":["Verticalement, divisant antérieur et postérieur","Verticalement, divisant le droit et le gauche","Horizontalement, divisant haut et bas","Obliquement, selon la diagonale du corps"],"r":0,"e":"Son axe est antéro-postérieur ; s'y produisent abduction, adduction et déviations radiale et cubitale.","s":6},{"q":"L'axe du plan sagittal est :","o":["Médial-latéral","Antéro-postérieur","Vertical crânio-caudal","Oblique"],"r":0,"e":"Flexion et extension s'y produisent ; le plan transversal a un axe vertical crânio-caudal.","s":6},{"q":"La pronation et la supination se produisent dans le plan :","o":["Sagittal","Frontal","Transversal","Oblique"],"r":2,"e":"S'y produisent également les rotations médiale et latérale et les abduction-adduction horizontales.","s":6},{"q":"Parmi les facteurs influençant l'amplitude articulaire, le cours cite :","o":["L'heure de la journée et l'expérience de l'évaluateur","La seule pathologie, sans autre facteur","Le seul âge du patient évalué","La seule force musculaire, mesurée au dynamomètre manuel"],"r":0,"e":"S'y ajoutent l'âge, le sexe, l'IMC, le caractère actif ou passif, les activités, la position de test et le type d'instrument.","s":6},{"q":"Parmi les causes d'hypomobilité, le cours cite :","o":["La douleur, l'inflammation et les suites d'immobilisation","La laxité des tissus mous, ligaments et capsule distendus","L'hypotonie, avec une baisse du tonus musculaire","Le syndrome de Marfan, par excès de laxité"],"r":0,"e":"S'y ajoutent les maladies orthopédiques, métaboliques et neurologiques, la perte de mouvement volontaire, les déformations osseuses et l'hypertonicité. Le raccourcissement musculaire ou capsulaire en fait aussi partie.","s":6},{"q":"Parmi les causes d'hypermobilité, le cours cite :","o":["La laxité des tissus mous, le traumatisme et l'hypotonie","Le raccourcissement capsulaire, après immobilisation","L'hypertonicité, par spasticité musculaire","L'inflammation, avec un épanchement articulaire"],"r":0,"e":"Elle se définit par une augmentation de l'amplitude au-delà des valeurs de référence. Le syndrome de Marfan, l'hyperlaxité et les anomalies des surfaces articulaires en font aussi partie.","s":6},{"q":"Les auteurs cités pour la description de l'end-feel sont :","o":["Cyriax, Kaltenborn et Paris","Kendall, McCreary et Provance","Daniels et Worthingham","Lovett, Janda, Mennell et Maitland"],"r":0,"e":"L'end-feel désigne la barrière perçue par l'évaluateur, caractéristique de la structure qui limite l'amplitude.","s":6},{"q":"Un end-feel ferme anormal évoque :","o":["Un œdème ou une synovite, avec un gonflement mou et diffus","Une hausse du tonus ou un raccourcissement capsulaire","Une chondromalacie, ou une arthrose évoluée","Une inflammation aiguë, avec une douleur vive"],"r":1,"e":"Un end-feel souple anormal évoque œdème et synovite, un dur anormal chondromalacie, arthrose, fragments libres ou fracture. Le raccourcissement peut aussi être musculaire ou ligamentaire.","s":6},{"q":"Devant un end-feel « ressort » (mola), le cours précise que :","o":["La mobilisation est contre-indiquée","La mobilisation doit être intensifiée","Il s'agit d'un end-feel normal","Il traduit une simple appréhension"],"r":0,"e":"Il évoque un corps libre intra-articulaire ou une lésion méniscale ; il ne faut par ailleurs pas confondre un end-feel avec une interruption due à l'inquiétude.","s":6},{"q":"La cinématique, telle que définie dans ce cours, décrit le mouvement :","o":["Sans considérer les forces","En intégrant les forces","À partir de la seule force musculaire","À partir de l'électromyographie"],"r":0,"e":"L'arthrocinématique en constitue l'application aux surfaces articulaires : glissement, rotation et roulement.","s":6},{"q":"Le plan transversal est orienté :","o":["Verticalement, divisant droite et gauche","Horizontalement, divisant supérieur et inférieur","Obliquement, divisant l'avant et l'arrière","Selon l'axe médial-latéral, divisant le corps"],"r":1,"e":"Son axe est vertical, crânio-caudal ; le plan sagittal divise droite et gauche et le plan frontal antérieur et postérieur.","s":6},{"q":"Le goniomètre demi-cercle (0-180°) est :","o":["Moins utilisé que le cercle complet","Plus utilisé et plus facile d'emploi","Réservé aux examinateurs experts","Obsolète depuis les inclinomètres numériques"],"r":1,"e":"Le demi-cercle 0-180° est le plus utilisé en clinique.","s":7},{"q":"Types de goniomètres :","o":["En plastique","En métal","À cercle complet de 360°","En demi-cercle de 180°","À gravité, ou inclinomètre","À aimant, ou magnétique"],"r":[0,1,2,3,4],"e":"Multiples types existent. Pas de version magnétique standard.","s":7},{"q":"Un goniomètre universel comporte combien de parties ?","o":["2, un corps et un bras","3, un corps et deux bras","4, un corps, deux bras et un niveau","5, un corps, deux bras, un niveau et une vis"],"r":1,"e":"3 parties : corps (axe), bras fixe, bras mobile.","s":7},{"q":"Les incréments typiques d'un goniomètre sont :","o":["1° ou 2°","5° ou 10°","15° ou 20°","30° ou 45°"],"r":1,"e":"5° ou 10° généralement. Identifier la ligne médiane pour la lecture.","s":7},{"q":"Un goniomètre à gravité s'appelle aussi :","o":["Dynamomètre","Inclinomètre","Pédomètre","Plurimètre"],"r":1,"e":"Inclinomètre : utilise la gravité comme référence.","s":7},{"q":"La fiabilité de la goniométrie est :","o":["Faible, quelle que soit la méthode","Bonne, reproductible entre observateurs","Toujours mauvaise, même standardisée","Indépendante de la méthode employée"],"r":1,"e":"Valeurs intra- et inter-observateurs reproductibles si méthode standardisée.","s":7},{"q":"Quelle est la première étape de la procédure ?","o":["Mobiliser le segment mesuré","Aligner les bras de l'outil","Expliquer la mesure au patient","Enregistrer la valeur lue"],"r":2,"e":"Ordre : Expliquer → positionner → localiser → aligner → mobiliser → enregistrer.","s":7},{"q":"Combien d'étapes la procédure goniométrique compte-t-elle ?","o":["3","4","6","8"],"r":2,"e":"6 étapes : expliquer, positionner, localiser, aligner, mobiliser, enregistrer.","s":7},{"q":"L'articulation doit être placée à :","o":["45° de départ","90° de départ","0° de départ","Position de confort uniquement"],"r":2,"e":"Position 0° (anatomique ou neutre) comme point de départ standardisé.","s":7},{"q":"L'évaluateur doit se positionner :","o":["Le plus loin possible du patient","Près de l'articulation à évaluer","Toujours debout, face au patient","Derrière le patient, hors de sa vue"],"r":1,"e":"Proximité = bonne mécanique corporelle et précision de mesure.","s":7},{"q":"Critères du bon positionnement :","o":["Sûr, détendu et confortable","Mouvement complet, sans entrave","Articulation placée à 0°","Articulation en tension maximale","Standardisé d'une mesure à l'autre"],"r":[0,1,2,4],"e":"La tension maximale n'est pas un critère ; au contraire, on cherche stress minimal.","s":7},{"q":"Les bras du goniomètre doivent être alignés avec :","o":["Les segments distaux uniquement","Les points de référence anatomiques","La table d'examen","Les vêtements du patient"],"r":1,"e":"Alignement sur les points anatomiques identifiés par observation et palpation.","s":7},{"q":"Le corps du goniomètre doit être placé :","o":["À l'extrémité distale du segment mobile, loin de l'axe","Sur l'axe du mouvement, près du segment proximal","Au milieu du segment, à égale distance","Sur l'os controlatéral, en miroir"],"r":1,"e":"L'axe peut bouger ; rester proche du proximal facilite la mesure.","s":7},{"q":"Pour éviter l'erreur de parallaxe :","o":["Fermer un œil pour la lecture","Regarder le cadran de loin","Centrer le regard sur la lecture","Lire la mesure très rapidement"],"r":2,"e":"Regard centré = lecture sans erreur de parallaxe.","s":7},{"q":"Quel segment doit être stabilisé ?","o":["Le distal","Le proximal","Aucun","Les deux simultanément"],"r":1,"e":"Stabiliser le segment proximal (par la table ou le kiné).","s":7},{"q":"En cas de stabilisation manuelle complexe :","o":["Abandonner la mesure et noter l'échec","Faire appel à une deuxième personne","Mesurer sans aucune stabilisation","Utiliser un simple bandage"],"r":1,"e":"2e personne = solution standard si stabilisation manuelle complexe.","s":7},{"q":"Les repères anatomiques s'identifient par :","o":["Observation et palpation","Radio uniquement","Demande au patient","Hasard"],"r":0,"e":"Identification par observation + palpation systématique.","s":7},{"q":"Pour ne pas fausser la mesure, la distance bras-segment doit être :","o":["Aussi grande que possible","Faible","À 5 cm","À 10 cm"],"r":1,"e":"Distance bras-segment faible = précision.","s":7},{"q":"Lors d'une mesure passive, le mouvement est effectué :","o":["Très rapidement, en un seul geste","Lentement et minutieusement","Avec un rebond en fin de course","En vibration, par petites oscillations"],"r":1,"e":"Détermination de l'end-feel demande lenteur et précision.","s":7},{"q":"Informations obligatoires à enregistrer :","o":["Nom et âge","Date et lieu","Type de goniomètre","Amplitudes (côté, mouvement)","Couleur des yeux"],"r":[0,1,2,3],"e":"Tous sauf la couleur des yeux.","s":7},{"q":"À noter en plus :","o":["Les données subjectives, comme la douleur","Les données objectives, comme un spasme","Toute modification du positionnement","La pression artérielle, prise au repos"],"r":[0,1,2],"e":"Pas la TA en routine goniométrique.","s":7},{"q":"On marque en rouge :","o":["Les amplitudes normales","Les amplitudes anormales","Toutes les mesures, sans distinction","Aucune mesure, tout étant en noir"],"r":1,"e":"Convention : valeurs anormales = rouge ; normales = noir.","s":7},{"q":"Pour interpréter les résultats, la référence essentielle est :","o":["Le sexe du patient","Le côté controlatéral","La date","Le poids"],"r":1,"e":"Comparaison au côté sain (controlatéral) + valeurs de référence.","s":7},{"q":"Objectif idéal de rééducation :","o":["Atteindre 180° pour chaque articulation","Récupérer l'amplitude du membre non blessé","Atteindre la moitié de l'amplitude normale théorique","Ne fixer aucun objectif chiffré"],"r":1,"e":"Comparer et viser l'amplitude du membre non blessé.","s":7},{"q":"Le diagramme de mouvement utilise les symboles :","o":["A, B, C pour Amplitude, Blocage, Contracture","D, R, S pour Douleur, Résistance, Spasme","X, Y, Z pour les trois axes de l'articulation","O, N, P pour Origine, Normal, Pathologique"],"r":1,"e":"D = douleur, R = résistance, E/S = spasme. Comportement le long de l'amplitude.","s":7},{"q":"La contraction utilisée en fin d'amplitude pour le test est :","o":["Isotonique concentrique","Isotonique excentrique","Isométrique","Isocinétique"],"r":2,"e":"Isométrique en fin d'amplitude.","s":7},{"q":"Le mouvement passif lors de la mesure est :","o":["Réalisé par le patient, de façon active et seule","Réalisé par l'évaluateur, le bras mobile suivant","Réalisé par les deux en même temps","Inutile, la mesure étant statique"],"r":1,"e":"Mouvement passif = l'évaluateur mobilise ; le bras mobile du goniomètre suit.","s":7},{"q":"On standardise les mesures successives en :","o":["Mesurant à des moments aléatoires de la journée","Variant les positions à chaque séance","Gardant les mêmes positions et le même horaire","Changeant d'évaluateur à chaque nouvelle mesure prise"],"r":2,"e":"Standardisation pour la fiabilité dans le temps.","s":7},{"q":"Un patient avec hyperextension de 5° au coude se note :","o":["Extension : -5°, en déficit","Extension : +5°, en hyperextension","Flexion : -5°, en hyperextension du coude","Flexion : 5°, en position neutre"],"r":1,"e":"Hyperextension = + (au-delà de la position 0).","s":7},{"q":"Le format le plus utilisé pour la notation des amplitudes est :","o":["0-180°, méthode du zéro neutre","180-0°, méthode inversée","0-360°, cercle complet","90-270°, demi-cercle décalé"],"r":0,"e":"Méthode du zéro neutre = standard international.","s":7},{"q":"Parmi les types de goniomètres, le cours distingue notamment :","o":["Plastique ou métallique, manuel ou électronique","Uniquement plastique ou métallique, en un seul format","Uniquement manuel, à lecture directe","Uniquement électronique, à affichage numérique"],"r":0,"e":"Le goniomètre à gravité, ou inclinomètre, complète cette liste. Il peut aussi être à cercle complet ou en demi-cercle, grand ou petit.","s":7},{"q":"Parmi les méthodes alternatives à la goniométrie, le cours cite :","o":["La photographie, la radiographie et l'estimation visuelle","L'échographie, pour visualiser les surfaces articulaires","L'électromyographie, pour l'activité musculaire","La dynamométrie, pour la force maximale"],"r":0,"e":"Le goniomètre demi-cercle reste le plus utilisé et le plus facile d'emploi. Les smartphones en font aussi partie.","s":7},{"q":"Le goniomètre universel se compose :","o":["Du corps ou axe, du bras fixe et du bras mobile","De deux bras seulement, reliés par une vis centrale","D'un cadran et d'une aiguille, comme une boussole","D'un axe et d'un seul bras"],"r":0,"e":"Il faut être attentif à l'échelle et aux incréments, généralement de 5 ou 10°, pour éviter les erreurs de lecture.","s":7},{"q":"La fiabilité de la goniométrie est décrite comme :","o":["Reproductible en intra- et inter-observateurs","Faible, avec de grands écarts entre examinateurs","Limitée à un seul examinateur","Dépendante du seul instrument utilisé"],"r":0,"e":"Cette fiabilité suppose toutefois la standardisation des positions et du moment de la journée. Elle permet des évaluations universelles.","s":7},{"q":"La première étape de la procédure goniométrique est :","o":["Expliquer à l'utilisateur, en démontrant si besoin","Localiser les repères anatomiques, par palpation","Aligner les bras du goniomètre sur les segments","Mobiliser le segment, jusqu'à la fin d'amplitude"],"r":0,"e":"Suivent le positionnement et la stabilisation, la localisation des repères, l'alignement, la mobilisation et l'enregistrement.","s":7},{"q":"L'articulation doit être placée, au départ de la mesure, à :","o":["0°","45°","90°","La position de confort"],"r":0,"e":"Le positionnement doit être sûr, détendu et confortable, et permettre un mouvement complet et sans entrave.","s":7},{"q":"L'évaluateur doit se placer :","o":["Près de l'articulation, pour sa propre posture","Le plus loin possible, pour une vue d'ensemble","Face au patient, systématiquement","Derrière le patient, pour ne pas gêner le mouvement"],"r":0,"e":"La position peut être adaptée si nécessaire, mais doit alors être notée au dossier. Cela assure une bonne mécanique corporelle et prévient les douleurs.","s":7},{"q":"Le corps du goniomètre doit être aligné avec :","o":["Le segment distal","L'axe du mouvement","Le bras fixe","La ligne de gravité"],"r":1,"e":"Comme cet axe peut se déplacer, il faut garder le corps du goniomètre proche du segment proximal.","s":7},{"q":"L'erreur de parallaxe s'évite en :","o":["Centrant le regard sur la lecture","Éloignant le goniomètre","Utilisant un grand goniomètre","Mesurant deux fois"],"r":0,"e":"C'est une erreur de lecture liée à l'angle d'observation du cadran.","s":7},{"q":"La stabilisation porte sur :","o":["Le segment proximal, par la table ou par le thérapeute","Le segment distal, que l'on maintient fermement en place","Les deux segments, de façon simultanée","Le tronc uniquement, par une sangle"],"r":0,"e":"Elle évite les mouvements combinés et les compensations ; si elle est complexe, une deuxième personne est requise.","s":7},{"q":"Les repères anatomiques s'identifient :","o":["Par observation et palpation","Par radiographie","Par mesure de longueur","Par estimation visuelle seule"],"r":0,"e":"Les bras du goniomètre s'alignent ensuite sur les segments proximal et distal.","s":7},{"q":"La distance entre le bras du goniomètre et le segment doit être :","o":["Faible, pour ne pas fausser la mesure","Importante, pour bien voir le cadran","Indifférente, sans aucun effet","D'au moins 10 cm, pour la lisibilité"],"r":0,"e":"Le mouvement est passif, le bras mobile suivant le déplacement du segment.","s":7},{"q":"Parmi les informations obligatoires à consigner figurent :","o":["Le nom, l'âge, le sexe, la date et le type de goniomètre","Le seul résultat chiffré, sans aucune autre information utile","Le seul nom du patient, avec sa date de naissance","La seule date, avec l'heure de la mesure"],"r":0,"e":"S'y ajoutent les amplitudes avec le côté et le mouvement, ainsi que les informations subjectives et objectives. Le nom du kinésithérapeute et le lieu sont aussi notés.","s":7},{"q":"On marque en rouge, dans l'enregistrement :","o":["Les amplitudes modifiées","Toutes les amplitudes","Les amplitudes normales","Le nom du patient"],"r":0,"e":"La modification du positionnement doit également être consignée.","s":7},{"q":"Parmi les informations objectives à noter figurent :","o":["Les spasmes","La douleur ressentie","L'anxiété","La motivation"],"r":0,"e":"La douleur relève, elle, des informations subjectives.","s":7},{"q":"La référence essentielle pour interpréter un résultat goniométrique est :","o":["La comparaison avec le côté controlatéral","La seule valeur de référence théorique","La moyenne de la population","La mesure précédente"],"r":0,"e":"Les valeurs variant selon les individus, la comparaison controlatérale précède la comparaison aux valeurs de référence.","s":7},{"q":"L'objectif de rééducation, en goniométrie, est de travailler :","o":["Jusqu'à atteindre l'amplitude du membre non blessé","Jusqu'à la valeur théorique maximale","Jusqu'à l'apparition d'une douleur, sans jamais la dépasser","Jusqu'à 90° dans tous les cas"],"r":0,"e":"C'est la conséquence directe du principe de comparaison controlatérale.","s":7},{"q":"La standardisation des mesures successives passe par :","o":["Les mêmes positions et le même moment de la journée","Le même examinateur, d'une séance à l'autre","Le même instrument, quel que soit l'examinateur","La même température de la salle d'examen"],"r":0,"e":"C'est ce qui garantit la fiabilité intra- et inter-observateurs.","s":7},{"q":"Lors de la mesure, le mouvement du segment est :","o":["Actif, le patient réalisant seul le geste","Passif, le bras mobile suivant le mouvement","Actif assisté, avec l'aide de l'évaluateur","Résisté, contre une force manuelle"],"r":1,"e":"Cette passivité évite que la force ou la coopération du patient n'influencent la mesure.","s":7},{"q":"Les incréments d'un goniomètre exigent une attention particulière car :","o":["Ils exposent à des erreurs de lecture","Ils varient d'un patient à l'autre, selon sa taille","Ils modifient l'amplitude réelle du mouvement","Ils dépendent du plan de mesure choisi"],"r":0,"e":"Il faut également identifier la ligne médiane de l'instrument avant la lecture. Ils sont généralement de 5 ou 10°.","s":7},{"q":"L'immobilisation sélective suppose l'utilisation de :","o":["Un plâtre rigide, englobant tout le membre","Un bandage fonctionnel sur les structures lésées","Une attelle métallique, portée en permanence","Un fauteuil roulant, pour la décharge totale"],"r":1,"e":"L'immobilisation sélective = bandage fonctionnel : soutien sélectif sans immobilisation complète. Il cible les tissus mous et les articulations.","s":8},{"q":"Quels sont les effets recherchés de l'immobilisation sélective ?","o":["Soutien et protection sélective des tissus","Diminution de la douleur","Diminution de l'œdème","Augmentation de la force musculaire","Stabilité articulaire"],"r":[0,1,2,4],"e":"Soutien, ↓ douleur, ↓ œdème, stabilité. L'IS n'augmente pas directement la force musculaire.","s":8},{"q":"L'immobilisation sélective est :","o":["Un substitut au programme de rééducation","Un complément du programme de rééducation","Un traitement à elle seule","Une alternative à la chirurgie"],"r":1,"e":"C'est un COMPLÉMENT, jamais un substitut aux programmes de rééducation.","s":8},{"q":"Comment agit l'immobilisation sélective ?","o":["Compression → réduit l'œdème","Soutient ligaments, tendons et muscles","Limite les mouvements articulaires indésirables","Augmente les mouvements douloureux","Protège les structures lésées en position fonctionnelle"],"r":[0,1,2,4],"e":"L'IS limite (pas augmente) les mouvements douloureux.","s":8},{"q":"La phase aiguë de la régénération tissulaire dure :","o":["0 à 3 jours","3 jours à 6 semaines","6 semaines à 6 mois","6 mois à 1 an"],"r":0,"e":"Aiguë (inflammation) = 0-3j ; subaiguë (réparation) = 3j-6sem ; chronique (remodelage) = 6sem-6mois.","s":8},{"q":"La phase inflammatoire de la cicatrisation dure :","o":["Le premier jour seulement","Les 4 à 5 premiers jours","Les 2 premières semaines","Le premier mois complet, environ"],"r":1,"e":"Phase inflammatoire = préparation de la zone, 4 à 5 premiers jours.","s":8},{"q":"La phase fibroblastique / réparation peut durer jusqu'à :","o":["1 semaine","3 semaines","3 mois","1 an"],"r":1,"e":"Phase fibroblastique : reconstruction, formation de tissu cicatriciel — jusqu'à 3 semaines.","s":8},{"q":"Le protocole PEACE & LOVE (Dubois & Esculier, 2019) correspond à :","o":["Un protocole chirurgical de réparation ligamentaire","Une prise en charge des lésions des tissus mous","Un type de bandage fonctionnel adhésif","Un test diagnostique de l'instabilité"],"r":1,"e":"PEACE & LOVE : Protection, Elevation, Avoid antiinflammatories, Compression, Education / Load, Optimism, Vascularisation, Exercise.","s":8},{"q":"Quels facteurs influencent la cicatrisation ?","o":["L'âge du patient","L'état de santé général","Le tabac et l'alcool","L'état nutritionnel","La couleur des cheveux","Le diabète et la BPCO"],"r":[0,1,2,3,5],"e":"Tous sauf la couleur des cheveux. Type de tissu, âge, santé, psychologique, hygiène de vie, nutrition, comorbidités.","s":8},{"q":"Les effets des bandages fonctionnels sont :","o":["Mécanique, limitant les mouvements excessifs","Proprioceptif, via les récepteurs cutanés","Psychologique, avec une sensation de sécurité","Anti-inflammatoire, par un effet pharmacologique","Hormonal, par une libération d'endorphines"],"r":[0,1,2],"e":"3 effets : mécanique, proprioceptif, psychologique.","s":8},{"q":"Avant l'application d'un bandage fonctionnel, il faut :","o":["Hydrater abondamment la peau, avec une crème grasse riche","Laver, sécher et épiler la peau, sans crème","Appliquer une pommade anti-inflammatoire, en couche","Bander immédiatement, sans aucune préparation"],"r":1,"e":"Préparer la peau : laver, sécher, épiler (sens descendant), retirer huiles/crèmes pour adhérence. Les huiles et crèmes doivent être retirées pour l'adhérence.","s":8},{"q":"Lors de l'application, l'articulation doit être placée :","o":["En position d'étirement maximal de la structure lésée","En position fonctionnelle, avec un stress minimal","En contraction maximale, contre résistance","Sans aucune position particulière"],"r":1,"e":"Position fonctionnelle, ligaments en raccourcissement, stress minimal.","s":8},{"q":"Lors de l'application des bandes, on les superpose :","o":["Au tiers, pour gagner du temps et de la bande","À moitié, pour éviter lacunes et glissement","Aux trois quarts, pour renforcer le maintien","Sans superposition, bord à bord"],"r":1,"e":"Superposition à moitié : évite lacunes et glissement.","s":8},{"q":"Quels signes d'alerte doivent être expliqués au patient ?","o":["Fatigue, frissons, démangeaisons","Rougeur, chaleur et démangeaisons","Vertiges, nausées et céphalées","Aucun signe, ni local ni général"],"r":1,"e":"Rougeur, chaleur et sensation de peau irritée (démangeaisons) = signes à surveiller.","s":8},{"q":"Que faut-il ÉVITER lors d'un bandage fonctionnel ?","o":["Une traction excessive de la peau","Des lacunes et des plis","Des bandages circonférentiels continus","Toujours le même point d'ancrage","Une préparation correcte de la peau"],"r":[0,1,2,3],"e":"À éviter : traction excessive, plis (ampoules), circonférentiel continu, même ancrage répété (irritation).","s":8},{"q":"Pour retirer un bandage fonctionnel, on utilise :","o":["Un couteau à lame fine, glissé sous la bande adhésive","Du Tape Remover et des ciseaux à bouts ronds","Une lame de rasoir, en coupe rapide","Une simple traction, d'un coup sec"],"r":1,"e":"Tape Remover + ciseaux à bouts ronds, en soutenant la peau.","s":8},{"q":"Combien de temps faut-il habituellement laisser un bandage fonctionnel ?","o":["1 heure","6 heures","24 heures","1 semaine"],"r":2,"e":"Retrait après 24h dans la plupart des cas. Réévaluer fréquemment l'état de la peau.","s":8},{"q":"Après retrait, on évite l'exposition solaire pendant :","o":["12h","48h à 72h","1 semaine","1 mois"],"r":1,"e":"Éviter exposition solaire 48-72h car peau fragilisée.","s":8},{"q":"Quelles sont les contre-indications absolues à l'immobilisation sélective ?","o":["Les fractures","Les troubles circulatoires graves","Les syndromes des loges","Les lésions cutanées ou les plaies","L'intolérance à l'adhésif","Une légère fatigue passagère"],"r":[0,1,2,3,4],"e":"5 CI : fractures, troubles circulatoires graves, syndromes compartimentaux, lésions cutanées, intolérance adhésive.","s":8},{"q":"Quels matériaux font partie des bandages utilisés ?","o":["Tape (rigide)","Bandage élastique","Bandage conventionnel","Pré-tape","Coussins compressifs","Acide hyaluronique"],"r":[0,1,2,3,4],"e":"Tous sauf l'acide hyaluronique (qui est un produit injectable).","s":8},{"q":"Parmi les accessoires nécessaires :","o":["Spray adhésif","Tape remover","Coupe-ongles / appareil à raser","Ciseaux à bouts ronds","Crème hydratante","Stéthoscope"],"r":[0,1,2,3,4],"e":"Le stéthoscope n'est pas nécessaire pour l'immobilisation sélective.","s":8},{"q":"Le Kinesio Tape (bande neuromusculaire) a une élasticité de :","o":["50-70%","100%","140-150%","200%"],"r":2,"e":"Élasticité de 140 à 150% — caractéristique distincte du tape rigide.","s":8},{"q":"Le Kinesio Tape agit sur :","o":["La peau et ses récepteurs","Le fascia superficiel","Le système circulatoire","Le système lymphatique","Le muscle sous-jacent","La biomécanique articulaire","La consolidation osseuse"],"r":[0,1,2,3,4,5],"e":"6 niveaux d'action (Wu et al., 2015) : peau, fascia, circulation, lymphatique, muscle, articulation. Le Kinesio Tape agit sur les tissus mous et la perception ; il n'immobilise rien et n'influence pas la consolidation osseuse.","s":8},{"q":"Une découpe en « I Strip » se caractérise par :","o":["Une tension dispersée sur les deux côtés de la bande","Une tension focalisée, directement sur le tissu cible","Une tension nulle, la bande étant posée à plat","Une tension répartie en éventail, sur une zone"],"r":1,"e":"I Strip : tension focalisée sur la zone cible.","s":8},{"q":"La découpe en « Fan Cut » est utilisée principalement pour :","o":["Force musculaire","Drainage lymphatique","Stabilité ligamentaire","Compression intense"],"r":1,"e":"Fan Cut : tension dispersée par les bandes, idéale pour le drainage lymphatique.","s":8},{"q":"Pour une INHIBITION musculaire (surmenage, lésion aiguë, spasme), on applique le Kinesio Tape :","o":["Origine → Insertion, tension 25-50%","Insertion → Origine, tension 15-25%","Sans tension","Perpendiculairement"],"r":1,"e":"Inhibition = direction Insertion→Origine, tension faible 15-25%.","s":8},{"q":"Pour une FACILITATION (lésion chronique, rééducation), on applique le Kinesio Tape :","o":["Origine → Insertion, tension 25-50%","Insertion → Origine, tension 5-10%","Sans tension","En boucle fermée"],"r":0,"e":"Facilitation = direction Origine→Insertion, tension élevée 25-50%.","s":8},{"q":"La durée maximale recommandée pour porter un Kinesio Tape est de :","o":["12 heures","24 heures","3 à 5 jours","2 semaines"],"r":2,"e":"Kinesio Tape : 3 à 5 jours maximum.","s":8},{"q":"Précautions à prendre avec le Kinesio Tape :","o":["Diabète","Pathologies rénales","Pathologie cardiaque","Peau fragile","Cheveux longs"],"r":[0,1,2,3],"e":"4 précautions : diabète, pathologies rénales, cardiaques et peau fragile.","s":8},{"q":"Quels mythes faut-il déconstruire à propos du Kinesio Tape ?","o":["Les couleurs ont un effet thérapeutique","Les bandes contiennent un anti-inflammatoire","Son efficacité est largement prouvée","Son action est purement sensitive","Une attitude critique est nécessaire"],"r":[0,1,2],"e":"3 MYTHES : chromothérapie, anti-inflammatoires, efficacité largement prouvée. L'action est sensitive ; attitude critique requise.","s":8},{"q":"Parmi les objectifs d'utilisation de l'immobilisation sélective, le cours cite :","o":["La prévention, le traitement et une meilleure fonction","La seule prévention, chez le sportif en bonne santé","Le seul traitement, après une lésion constituée","La seule antalgie, sans autre objectif visé"],"r":0,"e":"Elle complète notamment la marche, l'entraînement fonctionnel, la reprogrammation sensori-motrice et le massage. La complémentarité avec d'autres stratégies en fait aussi partie.","s":8},{"q":"Parmi les mécanismes d'action de l'immobilisation sélective figure :","o":["La protection des tissus lésés en position fonctionnelle","L'augmentation de la force des muscles stabilisateurs","L'augmentation de l'amplitude articulaire disponible","La stimulation de l'inflammation, pour cicatriser"],"r":0,"e":"S'y ajoutent la compression réduisant l'œdème, le soutien des ligaments, tendons et muscles, et la limitation des mouvements indésirables.","s":8},{"q":"Les décisions cliniques en immobilisation sélective se fondent sur :","o":["La physiologie de la régénération et les objectifs visés","Le seul confort du patient, selon ses préférences du jour","La seule douleur ressentie, quelle qu'en soit la cause","Le protocole du service, appliqué de façon identique"],"r":0,"e":"Il s'agit de contrôler l'inflammation, stabiliser, créer les conditions de réparation, diminuer douleur et œdème et maintenir mobilité et force des segments non affectés.","s":8},{"q":"La phase chronique de la régénération tissulaire s'étend de :","o":["0 à 3 jours","3 jours à 6 semaines","6 semaines à 6 mois","6 mois à 1 an"],"r":2,"e":"Elle correspond au remodelage ; la phase aiguë couvre 0 à 3 jours et la subaiguë 3 jours à 6 semaines.","s":8},{"q":"La phase de remodelage de la cicatrisation se caractérise par :","o":["Une réorganisation progressive des cellules et de la matrice","La préparation de la zone affectée, par la réaction vasculaire","La formation initiale du tissu cicatriciel, encore fragile","La réaction vasculaire, avec un afflux de cellules"],"r":0,"e":"Les fibroblastes n'ont pas toujours la capacité de reproduire exactement l'architecture du tissu original. La fibrose est remodelée et progressivement remplacée.","s":8},{"q":"Dans PEACE, la lettre A signifie :","o":["Activité, avec une reprise précoce","Éviter les anti-inflammatoires","Application de glace, sur la zone lésée","Analgésie, par les antalgiques"],"r":1,"e":"PEACE réunit Protection, Élévation, Avoid anti-inflammatories, Compression et Éducation ; LOVE ajoute Load, Optimism, Vascularisation et Exercise. En anglais : Avoid anti-inflammatories.","s":8},{"q":"Dans LOVE, la lettre O signifie :","o":["Œdème","Optimisme","Observation","Orthèse"],"r":1,"e":"Le protocole est dû à Dubois & Esculier (2019).","s":8},{"q":"Parmi les facteurs influençant la cicatrisation, le cours cite :","o":["Le type de tissu, l'âge, la nutrition et l'état général","Le seul âge, quel que soit l'état de santé du patient","La seule nutrition, en protéines et en vitamines","Le seul type de tissu, sans autre facteur associé"],"r":0,"e":"Tabac, alcool et caféine figurent parmi les habitudes de vie ; diabète, BPCO et néoplasies parmi les pathologies. L'état psychologique, les habitudes de vie et les pathologies associées en font aussi partie.","s":8},{"q":"L'effet proprioceptif des bandages fonctionnels repose sur :","o":["La stimulation des récepteurs cutanés et articulaires","La limitation mécanique des mouvements excessifs","Le sentiment de sécurité et de confort du patient","La compression, qui réduit l'œdème autour de l'articulation"],"r":0,"e":"L'effet mécanique limite les mouvements excessifs et l'effet psychologique procure sécurité et confort.","s":8},{"q":"Parmi les précautions avant application figure :","o":["Vérifier une éventuelle intolérance à l'adhésif","Mouiller la peau, pour faciliter l'adhérence","Appliquer une crème hydratante, pour protéger la peau","Chauffer la zone avec une poche chaude"],"r":0,"e":"La peau doit être lavée, séchée et épilée si nécessaire, et débarrassée des huiles et crèmes. L'intolérance au spray est aussi recherchée.","s":8},{"q":"Lors de l'application, les ligaments doivent être placés :","o":["En position d'étirement","En position de raccourcissement","En position neutre indifférente","En tension maximale"],"r":1,"e":"L'articulation est placée en position fonctionnelle, avec un stress minimal.","s":8},{"q":"Les bandes doivent être superposées :","o":["À moitié, pour éviter lacunes et glissement","Au quart, pour économiser la longueur de bande","Bord à bord, sans aucun chevauchement","Sans recouvrement, en spirale lâche"],"r":0,"e":"Chaque bande doit être appliquée avec un objectif précis, de façon douce mais ferme.","s":8},{"q":"Les signes d'alerte à expliquer au patient sont :","o":["Rougeur, chaleur et démangeaisons","Douleur, crampes et somnolence","Fièvre, frissons et courbatures","Pâleur, œdème et hématome local"],"r":0,"e":"Ils imposent le retrait du bandage et la réévaluation de l'état cutané.","s":8},{"q":"Parmi les erreurs à éviter, le cours cite :","o":["La traction excessive, les plis et le même ancrage répété","Le recouvrement des bandes, à la moitié de leur largeur totale","L'utilisation de pré-tape, sous la bande adhésive","L'application à température ambiante, sur peau sèche"],"r":0,"e":"La traction excessive provoque des lésions cutanées et les plis des ampoules. Les lacunes et les bandages circonférentiels continus sont aussi à éviter.","s":8},{"q":"L'exposition solaire doit être évitée après retrait pendant :","o":["24 heures","48 à 72 heures","1 semaine","1 mois"],"r":1,"e":"Le bandage lui-même se retire après 24 heures dans la plupart des cas.","s":8},{"q":"Parmi les contre-indications à l'immobilisation sélective figurent :","o":["Les fractures et les syndromes des loges","L'œdème, quel qu'en soit le stade","Une douleur modérée au repos","L'instabilité articulaire, chronique ou aiguë"],"r":0,"e":"Le syndrome des loges est aggravé par toute compression supplémentaire. Les troubles circulatoires graves, les lésions cutanées et l'intolérance à l'adhésif en font aussi partie.","s":8},{"q":"L'élasticité du Kinesio Tape est de :","o":["100 à 110 %","120 à 130 %","140 à 150 %","180 à 200 %"],"r":2,"e":"Elle permet une totale liberté de mouvement tout en soutenant les tissus mous.","s":8},{"q":"Selon Wu et al. (2015), le Kinesio Tape agit notamment sur :","o":["La peau, le fascia, la circulation et le muscle","Le seul muscle, par une contraction renforcée","La seule peau, sans effet plus profond sur les tissus","Le seul système lymphatique, par drainage"],"r":0,"e":"Il prolonge ainsi l'effet de la thérapie manuelle. Le système lymphatique et la biomécanique articulaire en font aussi partie.","s":8},{"q":"Pour une facilitation musculaire, le Kinesio Tape s'applique :","o":["De l'insertion vers l'origine, à tension faible","De l'origine vers l'insertion, à tension plus élevée","Sans aucune tension, la bande posée à plat","En circonférentiel, autour du membre entier"],"r":1,"e":"L'inhibition s'applique de l'insertion vers l'origine avec une tension faible de 15 à 25 %, en cas de surmenage, lésion aiguë ou spasme. La tension est de 25 à 50 %.","s":8},{"q":"Parmi les mythes à déconstruire à propos du Kinesio Tape, le cours cite :","o":["L'effet des couleurs et la présence d'anti-inflammatoires","Son élasticité, proche de celle de la peau humaine saine","Sa durée de port, de plusieurs jours sans retrait","Ses précautions d'emploi sur peau préparée"],"r":0,"e":"Son action est purement sensitive, et son efficacité reste questionnable faute de preuves scientifiques solides — d'où l'attitude critique recommandée. L'effet des couleurs relève de la chromothérapie.","s":8},{"q":"Une mobilisation passive est basée sur :","o":["Les mouvements accessoires, de glissement et de traction","Les mouvements physiologiques, à faible vitesse","La force musculaire, contre résistance","Le réflexe ostéo-tendineux, au marteau"],"r":1,"e":"Mobilisation passive = basée sur les mouvements physiologiques angulaires.","s":9},{"q":"Un mouvement accessoire est :","o":["Volontaire et mesurable, au goniomètre","Petit, intra-articulaire et non volontaire","Une amplitude active maximale, en charge","Un test musculaire, contre une résistance manuelle"],"r":1,"e":"Mouvements accessoires : glissements, tractions, intra-articulaires.","s":9},{"q":"Si ↓ mouvements accessoires :","o":["↑ mouvements physiologiques → hypermobilité","↓ mouvements physiologiques → douleur","Aucun effet → mobilité conservée","↑ stabilité articulaire → protection"],"r":1,"e":"↓ accessoires → ↓ physiologiques → douleur.","s":9},{"q":"Directions des mouvements accessoires :","o":["Longitudinale","Transversale","Antéro-postérieure","Rotation","Tangentielle"],"r":[0,1,2,3],"e":"4 directions : longitudinale, transversale, AP, rotation.","s":9},{"q":"L'ostéocinématique étudie :","o":["Les mouvements intra-articulaires, entre les surfaces","Les mouvements globaux des os, mesurables au goniomètre","Le métabolisme osseux, par le remodelage","Les forces musculaires, autour de l'articulation"],"r":1,"e":"Ostéocinétique = mouvements physiologiques angulaires.","s":9},{"q":"Types de mouvements arthrocinématiques :","o":["Roulement","Glissement","Rotation","Compression","Traction","Pronation"],"r":[0,1,2,3,4],"e":"5 types : roulement, glissement, rotation, compression, traction. Pronation = ostéocinétique.","s":9},{"q":"Lors d'un roulement :","o":["Un seul point sur une série de points","Une série de points sur une série de points","Une compression pure des deux surfaces","Une translation parallèle, comme un glissement"],"r":1,"e":"Roulement = série de points en contact avec série de points (balle qui roule). C'est l'image de la balle qui roule.","s":9},{"q":"Plus les surfaces sont congruentes, plus il y a :","o":["Roulement","Glissement","Compression","Traction"],"r":1,"e":"Surfaces congruentes → glissement prédominant.","s":9},{"q":"La compression articulaire avec contraction musculaire :","o":["Crée toujours une lésion du cartilage","Apporte stabilité et nutrition cartilagineuse","Augmente le mouvement, en écartant les surfaces","Provoque une luxation de l'articulation"],"r":1,"e":"Compression + contraction = stabilité, prévention de lésions, nutrition cartilage.","s":9},{"q":"La traction articulaire :","o":["Rapproche les surfaces, et comprime le cartilage","Écarte les surfaces, allonge la capsule et soulage","Bloque le mouvement, en verrouillant l'articulation","Crée une luxation, par écartement excessif"],"r":1,"e":"Traction = écartement, allongement capsulaire, antalgique.","s":9},{"q":"Selon Kaltenborn, surface mobile CONVEXE :","o":["Glissement dans le même sens que le mouvement","Glissement dans le sens opposé au mouvement","Aucun glissement, roulement pur","Roulement uniquement, sans glissement"],"r":1,"e":"Convexe sur concave → glissement opposé.","s":9},{"q":"Selon Kaltenborn, surface mobile CONCAVE :","o":["Glissement dans le sens opposé au mouvement","Glissement dans le même sens que le mouvement","Pas de glissement, rotation pure","Roulement libre, sans glissement"],"r":1,"e":"Concave sur convexe → glissement même sens.","s":9},{"q":"En flexion de hanche en DD, la tête fémorale (convexe) :","o":["Glisse en AP, à l'opposé de la flexion","Glisse en PA, dans le sens de la flexion","Ne glisse pas, roulement pur","Tourne sur elle-même, sans aucun glissement"],"r":0,"e":"Convexe sur concave → glissement antéro-postérieur (opposé).","s":9},{"q":"En extension du genou (assis), le tibia (concave) :","o":["Glisse en AP, à l'opposé de l'extension","Glisse en PA, dans le sens de l'extension","Glisse latéralement, en dehors de l'axe du genou","Reste fixe, le fémur seul se déplaçant"],"r":1,"e":"Concave sur convexe → glissement postéro-antérieur (même sens).","s":9},{"q":"Indications de la mobilisation accessoire :","o":["Douleur et spasmes musculaires","Hypomobilité réversible","Adhérences et rétractions capsulaires","Subluxation ou mauvais alignement","Œdème articulaire","Fracture aiguë non consolidée"],"r":[0,1,2,3,4],"e":"Fracture aiguë = CI. Les autres = indications.","s":9},{"q":"Buts de la mobilisation accessoire :","o":["Modulation de la douleur","↑ amplitude de mouvement","Traitement des dysfonctionnements biomécaniques","Renforcement musculaire direct"],"r":[0,1,2],"e":"Pas un objectif de renforcement musculaire.","s":9},{"q":"Effet neurophysiologique de la mobilisation accessoire :","o":["Mécanorécepteurs stimulés → nociception inhibée","Augmentation de la force → stabilité","Réparation tissulaire directe → cicatrisation rapide","Compression neuronale → anesthésie locale"],"r":0,"e":"Oscillations → stimulent mécanorécepteurs → inhibition de la nociception (porte de Melzack).","s":9},{"q":"Effet nutritionnel de la mobilisation accessoire :","o":["Hausse de l'appétit → meilleure nutrition","Liquide synovial mobilisé → nutrition du cartilage","Apport de calcium → minéralisation des surfaces osseuses","Renforcement osseux → densité accrue"],"r":1,"e":"Mouvements doux → mobilisation du liquide synovial → nutrition des zones avasculaires.","s":9},{"q":"Effet mécanique :","o":["Rupture des adhérences, en un seul geste","Maintien de l'extensibilité des ligaments et de la capsule","Éclatement du cartilage, par une compression répétée trop forte","Augmentation de la fibrose, autour de l'articulation"],"r":1,"e":"Maintien de l'extensibilité, force tensile ; évite la prolifération fibro-adipeuse.","s":9},{"q":"Contre-indications RELATIVES :","o":["Hypermobilité","Grossesse (relaxine ↑)","Ostéoporose","Modifications vasculaires","Lésions ligamentaires aiguës","Fractures non consolidées"],"r":[0,1,2,3,4],"e":"Fracture non consolidée = CI absolue.","s":9},{"q":"Contre-indications ABSOLUES :","o":["Fractures non consolidées","Arthroplastie totale","Spondylolisthésis","Compression médullaire","Néoplasie ou métastases","Ostéomyélite","Grossesse en cours"],"r":[0,1,2,3,4,5],"e":"La grossesse est relative. Les 6 autres = absolues.","s":9},{"q":"En cas d'hypomobilité D4-D5 + hypermobilité douloureuse D9-D10 :","o":["Mobiliser uniquement D9-D10, site de la douleur","Mobiliser D4-D5, pour réduire le stress en D9-D10","Immobiliser le rachis thoracique entier, en corset rigide","Manipuler D9-D10, en haute vélocité"],"r":1,"e":"Traiter l'hypomobilité (cause), pas le site douloureux (conséquence).","s":9},{"q":"Grade I de Maitland :","o":["Une petite oscillation en début d'amplitude","Une grande oscillation en fin d'amplitude","Un mouvement maximal, jusqu'à la limite de résistance","Une manipulation rapide, en haute vélocité"],"r":0,"e":"Grade I : oscillation en début, but analgésique.","s":9},{"q":"Grade II de Maitland :","o":["Une petite amplitude en fin de course","Une grande amplitude sans atteindre la limite","Une manipulation rapide, de petite amplitude","Un maintien statique, sans amplitude"],"r":1,"e":"Grade II : amplitude plus grande, sans atteindre la limite. Analgésique.","s":9},{"q":"Grade III de Maitland :","o":["Une petite amplitude au début, loin de la résistance","Une grande amplitude jusqu'à la limite, en forçant","Une très petite amplitude, en fin de course","Une manipulation rapide, en haute vélocité"],"r":1,"e":"Grade III : grande amplitude forçant la résistance. Augmente la ROM. Elle force la résistance.","s":9},{"q":"Grade IV de Maitland :","o":["Une petite amplitude en fin de mouvement, à la limite","Une grande amplitude en début de course, sans forcer","Un mouvement balistique, avec élan","Une pression maintenue, sans aucun mouvement"],"r":0,"e":"Grade IV : petite amplitude en fin, à la limite, forçant la résistance.","s":9},{"q":"Grade V de Maitland :","o":["Une manipulation rapide, de petite amplitude","Une mobilisation lente, de grande amplitude","Une pression statique, sans amplitude","Un grade pédiatrique, réservé aux très jeunes enfants"],"r":0,"e":"Grade V = thrust manipulatif. Cours avancé, technique experte. Elle échappe au contrôle du patient.","s":9},{"q":"Indication des grades I-II :","o":["Augmenter l'amplitude articulaire","Obtenir une analgésie de la douleur","Manipuler l'articulation bloquée","Stabiliser l'articulation lâche"],"r":1,"e":"I-II = analgésie. III-IV = augmentation ROM.","s":9},{"q":"Indication des grades III-IV :","o":["Obtenir une analgésie, en phase aiguë","Augmenter l'amplitude, en phase chronique","Réduire un spasme, de façon réflexe","Manipuler l'articulation, en haute vélocité"],"r":1,"e":"III-IV : forçage de la résistance pour ↑ ROM. La phase peut aussi être subaiguë.","s":9},{"q":"La mobilisation accessoire vise principalement :","o":["Le renforcement des muscles stabilisateurs","La douleur, l'amplitude et la biomécanique","Le drainage lymphatique, de l'œdème","La rééducation cardiaque, après un infarctus"],"r":1,"e":"3 buts : modulation douleur, ↑ ROM, traitement biomécanique.","s":9},{"q":"La mobilisation articulaire passive s'applique :","o":["Aux articulations et aux tissus mous, à faible vitesse","Aux seules articulations, sans les tissus mous","À vitesse rapide, avec une impulsion brève en fin de course","En amplitude maximale uniquement, en forçant"],"r":0,"e":"Elle repose sur les mouvements physiologiques et le patient peut l'interrompre. Elle se fait dans différentes amplitudes.","s":9},{"q":"Les mouvements accessoires se caractérisent par le fait :","o":["De ne pas pouvoir être réalisés seuls volontairement","D'être volontairement contrôlés par le patient","D'être mesurables à la goniométrie, en degrés","De se produire autour d'un axe défini, dans un seul plan"],"r":0,"e":"Ce sont de petits mouvements intra-articulaires nécessaires pour réaliser l'amplitude normale : glissements et tractions.","s":9},{"q":"Les sens des mouvements accessoires sont :","o":["Caudal ou céphalique, latéral ou médial, antéro-postérieur","Flexion ou extension seulement, autour d'un axe frontal unique","Interne ou externe, en rotation pure","Proximal ou distal uniquement, en traction"],"r":0,"e":"Leurs directions sont longitudinale, transversale, antéro-postérieure et en rotation. Le sens postéro-antérieur en fait aussi partie.","s":9},{"q":"Les mouvements ostéocinétiques se caractérisent par le fait :","o":["D'être volontaires et mesurables par goniométrie","D'être intra-articulaires et non volontaires du patient","D'être de faible amplitude, entre les surfaces","D'être non mesurables, même au goniomètre"],"r":0,"e":"Ils se produisent dans un plan, autour d'un axe ; les arthrocinématiques sont non volontaires et non mesurables.","s":9},{"q":"Le roulement se définit comme :","o":["Une série de points contre une série de points","Un seul point contre une série de points","Une rotation autour d'un axe longitudinal","Un écartement des surfaces, perpendiculaire au plan"],"r":0,"e":"La surface qui bouge n'influence pas sa direction, contrairement au glissement soumis à la règle convexe-concave.","s":9},{"q":"Le glissement se définit comme :","o":["Une série de points contre une série de points de l'autre","Un point précis contre une série de points de l'autre","Une rotation axiale, autour de l'axe longitudinal","Une compression, qui rapproche les surfaces"],"r":1,"e":"Plus les surfaces sont congruentes, plus il y a de glissement.","s":9},{"q":"La compression articulaire associée à une contraction musculaire apporte :","o":["Stabilité, prévention des lésions et nutrition","Uniquement un soulagement de la douleur","Un allongement capsulaire, par tension","Un écartement des surfaces, avec une décoaptation"],"r":0,"e":"Son excès entraîne au contraire une lésion cartilagineuse ; la traction allonge la capsule et soulage la douleur. La nutrition concerne le cartilage.","s":9},{"q":"Selon la règle de Kaltenborn, une surface mobile convexe glisse :","o":["Dans le même sens que le mouvement physiologique","Dans le sens opposé au mouvement physiologique","Sans aucun glissement, par un roulement pur et isolé","En rotation pure, autour de l'axe longitudinal"],"r":1,"e":"Une surface mobile concave glisse, elle, dans le même sens que le mouvement physiologique.","s":9},{"q":"Lors de l'extension du genou en position assise, le tibia concave glisse :","o":["De postérieur vers antérieur, comme l'extension","D'antérieur vers postérieur, contre l'extension","Latéralement, vers le compartiment externe","En rotation, sans glissement associé"],"r":0,"e":"À la hanche, la tête fémorale convexe glisse au contraire d'antérieur vers postérieur lors de la flexion.","s":9},{"q":"Parmi les indications de la mobilisation accessoire, le cours cite :","o":["La douleur, les spasmes, les adhérences et l'œdème","La fracture non consolidée, en phase aiguë","L'hypermobilité, avec une instabilité articulaire nette","Les signes neurologiques, comme une compression"],"r":0,"e":"Sur œdème articulaire, les mobilisations douces favorisent le drainage et la nutrition du cartilage. L'hypomobilité réversible et le mauvais alignement en font aussi partie.","s":9},{"q":"Les trois buts de la mobilisation accessoire sont :","o":["Agir sur la douleur, l'amplitude et la biomécanique","Renforcer, étirer et stabiliser les muscles","Drainer, réchauffer et relâcher les tissus mous","Mobiliser, manipuler et étirer l'articulation"],"r":0,"e":"Ses effets se répartissent en neurophysiologiques, nutritionnels et mécaniques.","s":9},{"q":"L'effet neurophysiologique de la mobilisation accessoire repose sur :","o":["Des oscillations de faible amplitude inhibant la nociception","La circulation du liquide synovial, vers le cartilage","Le maintien de l'extensibilité ligamentaire et capsulaire","La compression articulaire, qui stabilise l'articulation"],"r":0,"e":"Cette inhibition s'exerce au niveau de la moelle et du tronc cérébral, et s'accompagne d'une augmentation de la proprioception. Elles stimulent les mécanorécepteurs et les nocicepteurs.","s":9},{"q":"L'effet nutritionnel de la mobilisation accessoire s'explique par :","o":["Des tractions et glissements faisant circuler la synovie","Une vasodilatation des vaisseaux de la capsule","Une augmentation du débit artériel vers l'os","Un drainage lymphatique des tissus périarticulaires"],"r":0,"e":"Ils nourrissent ainsi les zones non vascularisées du cartilage. Ces mouvements sont de faible amplitude.","s":9},{"q":"L'effet mécanique de la mobilisation accessoire consiste à :","o":["Maintenir l'extensibilité et la force tensile des ligaments","Augmenter la force musculaire, par une mise en tension active","Diminuer la douleur, par une stimulation des récepteurs","Nourrir le cartilage grâce au liquide synovial"],"r":0,"e":"C'est ce qui justifie la mobilisation précoce après immobilisation. Elle évite aussi la prolifération fibro-adipeuse.","s":9},{"q":"Parmi les contre-indications RELATIVES de la mobilisation accessoire figurent :","o":["L'hypermobilité, la grossesse et l'ostéoporose","Les fractures non consolidées, même anciennes","Les arthroplasties totales, de hanche ou de genou","Les maladies néoplasiques, et les métastases"],"r":0,"e":"La grossesse y figure du fait de l'augmentation de la relaxine et donc de la laxité. Les modifications vasculaires et les lésions ligamentaires aiguës en font aussi partie.","s":9},{"q":"Parmi les contre-indications ABSOLUES figurent :","o":["Les fractures non consolidées et l'arthroplastie totale","L'ostéoporose même modérée","La grossesse, quel qu'en soit le terme","L'hypermobilité, avec une laxité ligamentaire très marquée"],"r":0,"e":"Les signes neurologiques visés sont la compression médullaire, le syndrome de la queue de cheval et les sténoses. Le spondylolisthésis, les signes neurologiques, les néoplasies et les infections osseuses en font aussi partie.","s":9},{"q":"La modification vasculaire citée comme contre-indication relative concerne :","o":["L'artère vertébrale, du fait du risque de vertiges","L'artère fémorale, en raison du risque de thrombose","Les veines superficielles, en raison du risque de phlébite","Le réseau lymphatique, par risque d'œdème"],"r":0,"e":"Elle impose une prudence particulière lors des mobilisations cervicales.","s":9},{"q":"Devant une hypomobilité en D4-D5 associée à une hypermobilité douloureuse en D9-D10, on traite :","o":["Le segment hypomobile","Le segment hypermobile, siège de la douleur","Les deux simultanément","Ni l'un ni l'autre"],"r":0,"e":"La règle est de traiter l'hypomobilité et non l'hypermobilité, même si cette dernière est le siège des symptômes.","s":9},{"q":"Une diminution des mouvements accessoires entraîne :","o":["Une baisse des mouvements physiologiques et une douleur","Une augmentation de l'amplitude, par une compensation","Aucune conséquence sur l'amplitude globale","Une hypermobilité des segments sus-jacents"],"r":0,"e":"C'est précisément ce qui fonde l'intérêt de la mobilisation accessoire dans la récupération d'amplitude.","s":9},{"q":"La traction articulaire a pour effets :","o":["L'allongement de la capsule et un effet antalgique","La stabilité et la nutrition du cartilage articulaire","La prévention des lésions du cartilage, par appui","La diminution de l'espace entre les deux surfaces"],"r":0,"e":"La compression, à l'inverse, diminue l'espace articulaire.","s":9},{"q":"Carl Kaltenborn a apporté :","o":["Le concept de manipulation à haute vélocité, ou thrust","La règle concave-convexe et ses bases biomécaniques","La rééducation fonctionnelle, en chaînes","La théorie du portillon, contre la douleur"],"r":1,"e":"Kaltenborn (1950-80) : règle concave-convexe, mobilisation accessoire biomécanique.","s":10},{"q":"George Maitland était :","o":["Physiothérapeute américain","Physiothérapeute australien","Orthopédiste anglais","Médecin radiologue néo-zélandais"],"r":1,"e":"Maitland australien, premier à systématiser cliniquement la MA. Il a vécu de 1924 à 2010.","s":10},{"q":"McKenzie est connu pour :","o":["Les mouvements actifs répétés et la centralisation","La mobilisation accessoire selon la règle convexe","La manipulation à haute vélocité, ou thrust","Le drainage lymphatique manuel des membres"],"r":0,"e":"McKenzie : positions, exercices actifs répétés, centralisation. La centralisation concerne les symptômes.","s":10},{"q":"Mulligan est associé à :","o":["La MWM, ou mobilisation avec mouvement","La PNF, ou facilitation neuromusculaire","Le concept de Maitland, par grades","Le testing musculaire, de 0 à 5"],"r":0,"e":"Mulligan = MWM : combinaison mobilisation accessoire + mouvement actif.","s":10},{"q":"Cyriax est associé à :","o":["Les mobilisations passives et les massages transverses","Les tests fonctionnels en charge","Le drainage lymphatique, par pressions douces et lentes","La reprogrammation sensori-motrice, par l'équilibre"],"r":0,"e":"Cyriax (1940-80) : approche orthopédique, MTP. Les manipulations en font aussi partie ; les massages transverses profonds sont les MTP.","s":10},{"q":"Le concept Maitland repose principalement sur :","o":["Le diagnostic médical strict","La réponse du patient au mouvement","Les protocoles rigides","La radiographie"],"r":1,"e":"Évaluation analytique basée sur les symptômes/signes du patient.","s":10},{"q":"Le « Permeable Brick Wall » de Maitland sépare :","o":["La théorie et la pratique clinique","Le sain et le malade, chez un même patient","L'actif et le passif de l'examen","Le cervical et le lombaire, par niveaux"],"r":0,"e":"2 compartiments perméables : théorie (anatomie, physio) et clinique (présentation, signes).","s":10},{"q":"L'examen subjectif inclut :","o":["Les données personnelles","Le diagnostic médical","Les antécédents","Les symptômes et leurs zones","Le comportement des symptômes","Les tests musculaires"],"r":[0,1,2,3,4],"e":"Subjectif = verbal/anamnestique. Tests musculaires = objectif.","s":10},{"q":"L'examen objectif inclut :","o":["L'évaluation des structures","La reproduction des symptômes","L'amplitude et les mouvements accessoires","Les antécédents médicaux et chirurgicaux","La comparaison controlatérale"],"r":[0,1,2,4],"e":"Les antécédents font partie du subjectif. L'évaluation des structures recherche œdème et atrophie.","s":10},{"q":"Sur un body chart, on note la chronologie :","o":["D1 apparaît avant D2","D2 avant D1","Aucune chronologie","Dates de l'année"],"r":0,"e":"D1 = premier symptôme, D2 = second. La chronologie aide au raisonnement clinique.","s":10},{"q":"Une douleur constante :","o":["Disparaissant au repos, dès l'arrêt","Toujours présente, même au repos","Apparaissant à l'effort, seulement","Variant de façon cyclique"],"r":1,"e":"Douleur constante = présente en permanence, y compris au repos.","s":10},{"q":"Une douleur mécanique :","o":["Liée à l'inflammation, pire le matin","Liée au mouvement, et soulagée par le repos","Constante, présente même au repos le plus complet","Spontanée, sans facteur déclenchant"],"r":1,"e":"Mécanique : déclenchée par le mouvement, soulagée par le repos. La position peut aussi la déclencher.","s":10},{"q":"Une douleur inflammatoire :","o":["Soulagée par le repos, et aggravée par le mouvement","Aggravée par le mouvement, en fin de journée","Pire le matin, avec raideur et réveil nocturne","Indépendante de l'horaire de la journée"],"r":2,"e":"Profil inflammatoire : pire le matin, raideur, nocturne. S'améliore avec le mouvement.","s":10},{"q":"Une douleur latente :","o":["Présente au repos, de façon continue","Absente au repos, apparaissant à la stimulation","Toujours intense, quel que soit le contexte","Toujours chronique, au-delà de trois mois d'évolution"],"r":1,"e":"Latente : silencieuse au repos, déclenchée par mouvement/palpation.","s":10},{"q":"Une douleur nociceptive est :","o":["D'origine nerveuse, par lésion du système nerveux","Liée à une lésion non neurale, et bien localisée","Centrale, par une sensibilisation du système nerveux","Sans lésion, avec un traitement central altéré"],"r":1,"e":"Nociceptive (mécanique) = tissu lésé, localisée, répond à la mob. Elle répond bien à la mobilisation.","s":10},{"q":"Une douleur neuropathique :","o":["Mécanique pure, soulagée par le repos et la position","Liée au nerf, avec chocs, brûlures et picotements","Sans relation avec le système nerveux","Toujours bénigne, et sans précaution"],"r":1,"e":"Neuropathique = lésion nerveuse, exige prudence. Elle traduit une lésion du système nerveux.","s":10},{"q":"La douleur nociplastique correspond à :","o":["Une lésion tissulaire claire, bien localisée","Une altération du traitement central, sans lésion","Une lésion ligamentaire, avec une instabilité","Une rupture musculaire, partielle ou totale"],"r":1,"e":"Nociplastique = sensibilisation centrale ; mobilisation seule insuffisante.","s":10},{"q":"Le S de SIN signifie :","o":["Symptôme","Sévérité","Stabilité","Stade"],"r":1,"e":"S = Sévérité (intensité, retentissement).","s":10},{"q":"Le I de SIN signifie :","o":["Intensité, mesurée sur une échelle visuelle","Irritabilité, persistant après le stimulus","Inflammation, aiguë ou chronique","Insertion, du tendon sur l'os"],"r":1,"e":"I = Irritabilité : symptômes persistent après l'arrêt du stimulus.","s":10},{"q":"Le N de SIN signifie :","o":["Niveau, de la lésion vertébrale","Nature, du processus pathologique","Nocturne, pour une douleur qui réveille la nuit","Numérique, pour l'échelle de douleur"],"r":1,"e":"N = Nature : processus pathologique, facteurs contributifs. Elle inclut la stabilité et les facteurs contributifs.","s":10},{"q":"Une irritabilité élevée oriente vers :","o":["Mobilisations grade III-IV","Mobilisations grade I-II","Manipulation thrust","Pas de traitement"],"r":1,"e":"Irritabilité élevée = grades I-II (analgésiques).","s":10},{"q":"En phase AIGUË, la séquence douleur/résistance est :","o":["Résistance puis douleur","Douleur puis résistance","Simultanées","Aucune"],"r":1,"e":"Aigu : douleur AVANT résistance → I-II.","s":10},{"q":"En phase SUBAIGUË :","o":["Une douleur seule, sans aucune résistance","Une résistance seule, sans douleur","Une douleur et une résistance, simultanées","Aucune douleur ni résistance"],"r":2,"e":"Subaigu : mixte, douleur + résistance simultanées → II-III.","s":10},{"q":"En phase CHRONIQUE :","o":["Douleur seule","Résistance PUIS douleur","Douleur PUIS résistance","Pas de douleur"],"r":1,"e":"Chronique : raideur capsulo-ligamentaire, résistance précède la douleur → III-IV.","s":10},{"q":"Pour soulager la douleur, on choisit un rythme :","o":["Rapide et saccadé","Lent et régulier","Soutenu","Aléatoire"],"r":1,"e":"Lent et régulier → analgésie.","s":10},{"q":"Pour traiter une raideur articulaire :","o":["Lent","Rapide et saccadé","Soutenu","En vibration"],"r":1,"e":"Rapide-saccadé → raideur.","s":10},{"q":"Pour réduire les spasmes musculaires :","o":["Rapide","Soutenu","Lent","Très rapide"],"r":1,"e":"Mobilisation soutenue → spasmes.","s":10},{"q":"L'end-feel « capsulaire/élastique » correspond à :","o":["Un contact os contre os","Une approximation des tissus mous","Un étirement des tissus non contractiles","Un spasme musculaire, de protection réflexe"],"r":2,"e":"Élastique = étirement capsulaire/ligamentaire (épaule, hanche).","s":10},{"q":"Dans un diagramme de mouvement, D1 indique :","o":["Le début de la douleur","La fin du mouvement","Le pic de douleur","La résistance maximale"],"r":0,"e":"D1 = apparition initiale de la douleur dans l'amplitude.","s":10},{"q":"L = limite pathologique. Sur le diagramme, D2, R2, S2 représentent :","o":["Le début de l'amplitude","La fin, en limitant le mouvement","Le milieu de l'amplitude, sans limiter le geste","Rien de particulier, sans signification"],"r":1,"e":"D2/R2/S2 = facteur limitant en fin d'amplitude. D'/R'/S' = fin sans limiter.","s":10},{"q":"Kaltenborn a exercé son influence sur la période :","o":["1940-1980","1950-1980","1924-2010","1980-1990"],"r":1,"e":"Il a apporté les fondements biomécaniques de la mobilisation accessoire et la règle concave-convexe.","s":10},{"q":"Maitland a vécu de :","o":["1924 à 2010","1950 à 2000","1900 à 1980","1930 à 1995"],"r":0,"e":"Il a été le premier à systématiser cliniquement la mobilisation accessoire, en se fondant sur la réponse du patient, à la colonne vertébrale.","s":10},{"q":"Mulligan est associé, sur la période 1980-1990, à :","o":["La mobilisation avec mouvement, ou MWM","La centralisation des symptômes","Le massage transverse profond, ou le MTP","La règle concave-convexe"],"r":0,"e":"McKenzie est associé aux mouvements actifs répétés et à la centralisation, Cyriax aux mobilisations passives, manipulations et MTP.","s":10},{"q":"Le concept de Maitland est décrit comme :","o":["Le plus facilitateur et structurant","Le plus ancien des concepts manuels","Le plus rigide, fondé sur des protocoles","Le plus biomécanique de tous"],"r":0,"e":"Il met l'accent sur l'évaluation analytique continue et le classement par gravité, irritabilité, nature et stade.","s":10},{"q":"La base physiologique du concept de Maitland comporte trois points, dont :","o":["L'engagement personnel à comprendre l'utilisateur","La standardisation des protocoles de soin","La priorité absolue donnée au diagnostic médical initial","L'application de techniques fixes et identiques"],"r":0,"e":"S'y ajoutent la réflexion théorique et l'évaluation permanente avec réévaluation des données.","s":10},{"q":"Dans le concept de Maitland :","o":["Le raisonnement clinique prime sur les protocoles","Les protocoles rigides priment sur le raisonnement clinique","Seule la biomécanique compte pour la décision","Seule la douleur guide le choix des techniques"],"r":0,"e":"Chaque « brique » du mur constitue un élément d'évaluation.","s":10},{"q":"Le concept de Maitland englobe l'évaluation et le traitement :","o":["Du seul système articulaire et capsulaire","Des systèmes articulaire, neural et musculaire","Du seul système musculaire, contractile et tendineux","Du seul système neural, central et périphérique"],"r":1,"e":"Son objectif est de restaurer la fonction selon la réponse de la douleur au mouvement.","s":10},{"q":"Parmi les éléments de l'examen objectif, le cours cite :","o":["La reproduction des symptômes, ou signe comparable","Les antécédents médicaux, chirurgicaux et traitements","Le comportement des symptômes au repos","Les données personnelles et la profession"],"r":0,"e":"S'y ajoutent l'évaluation des structures, les tests fonctionnels et posturaux, la détection des dysfonctionnements et la comparaison controlatérale.","s":10},{"q":"Sur un body chart, la chronologie se note :","o":["D1 pour la première douleur, D2 pour la suivante","Par ordre d'intensité, de D1 à D3","Par ordre anatomique, de la tête aux pieds, de D1 à D5","Par ordre de traitement prévu"],"r":0,"e":"On y note aussi la zone, la profondeur, le type et le comportement des symptômes.","s":10},{"q":"Une douleur intermittente se définit comme :","o":["Toujours présente, même au repos","Présente dans certaines situations, absente au repos","Absente au repos et apparaissant à la stimulation","Plus intense le matin, avec une raideur matinale prolongée"],"r":1,"e":"La douleur latente est, elle, absente au repos et apparaît à la stimulation par le mouvement ou la palpation.","s":10},{"q":"Une douleur inflammatoire se caractérise par :","o":["Une amélioration par le repos complet","Une raideur matinale, améliorée par le mouvement","Une apparition à la seule palpation de la zone","Une absence au repos, avec une apparition à la stimulation"],"r":1,"e":"La douleur mécanique s'améliore au contraire avec le repos et dépend du mouvement ou de la position. Elle est aussi plus intense le matin et réveille la nuit.","s":10},{"q":"Une douleur neuropathique se manifeste par :","o":["Des chocs électriques, des brûlures et des picotements","Une douleur localisée, qui répond à la mobilisation","Un traitement central altéré, sans aucune lésion","Une douleur exclusivement nocturne, au repos"],"r":0,"e":"La douleur mixte, comme la lombosciatique, associe composantes nociceptive et neuropathique. Elle impose la prudence.","s":10},{"q":"Dans l'acronyme SIN, la lettre N désigne :","o":["La sévérité, selon la limitation du mouvement","L'irritabilité, selon la persistance des symptômes","La nature, du processus pathologique en cause","La nociception, par les récepteurs de la douleur"],"r":2,"e":"La sévérité évalue si la douleur limite le mouvement, l'irritabilité si les symptômes persistent après l'arrêt du stimulus. Elle inclut la stabilité du problème, les facteurs contributifs et l'évitement.","s":10},{"q":"Une irritabilité élevée oriente vers des mobilisations de degré :","o":["I-II","II-III","III-IV","V"],"r":0,"e":"La douleur y est facile à provoquer et persistante ; les grades I-II visent l'analgésie.","s":10},{"q":"En phase subaiguë, la séquence douleur/résistance est :","o":["La douleur, puis la résistance","Douleur et résistance simultanées","La résistance, puis la douleur","La résistance seule et indolore"],"r":1,"e":"Elle traduit une inflammation en régression avec raideur, et oriente vers des degrés II-III.","s":10},{"q":"En phase chronique, la séquence est :","o":["Douleur puis résistance","Simultanée","Résistance puis douleur","Aucune des deux"],"r":2,"e":"Elle traduit une raideur capsulo-ligamentaire avec faible inflammation, donc une limitation structurelle, et oriente vers des degrés III-IV.","s":10},{"q":"La phase aiguë, où la douleur précède la résistance, traduit :","o":["Un tissu enflammé, avec une limitation douloureuse","Une raideur capsulaire, avec une limitation ancienne","Une limitation structurelle, par fibrose","Une inflammation en régression, avec raideur"],"r":0,"e":"Elle oriente vers des mobilisations de degré I-II. La sensibilité nociceptive est élevée et la limitation non structurelle.","s":10},{"q":"Les grades III-IV de Maitland sont indiqués pour :","o":["L'analgésie, en phase aiguë","L'augmentation de l'amplitude","La manipulation, à thrust","La seule évaluation initiale"],"r":1,"e":"Les grades I-II visent l'analgésie et le grade V correspond à la manipulation.","s":10},{"q":"L'examen subjectif, selon Maitland, recueille notamment :","o":["Les données personnelles, les antécédents et les symptômes","Les seuls symptômes, sans les antécédents","La seule amplitude articulaire, au goniomètre","Les seuls tests fonctionnels, réalisés en charge et en décharge"],"r":0,"e":"Les antécédents comprennent les médicaments et les chirurgies ; le comportement porte sur le repos et les facteurs aggravants. Le diagnostic médical, le comportement des symptômes et le stade en font aussi partie.","s":10},{"q":"Parmi les objectifs du concept de Maitland, le cours cite :","o":["Diminuer la douleur et les spasmes, et gagner en amplitude","Augmenter la force maximale, en charge lourde","Améliorer la capacité aérobie, à l'effort","Corriger la posture uniquement, en statique et en dynamique"],"r":0,"e":"Le tout selon la réponse de la douleur et des symptômes au mouvement.","s":10},{"q":"Fonctions de la colonne vertébrale :","o":["Transmettre le poids du corps","Protéger la moelle épinière","Déterminer l'amplitude du tronc","Produire du calcium sanguin","Assurer les échanges gazeux"],"r":[0,1,2],"e":"3 fonctions : transmission, protection moelle, amplitude tronc.","s":11},{"q":"La courbure cervicale est une :","o":["Une cyphose, convexe en arrière","Une lordose, concave en arrière","Une scoliose, de profil","Absente, la colonne étant rectiligne"],"r":1,"e":"Cervicale : lordose physiologique.","s":11},{"q":"La courbure dorsale est une :","o":["Une lordose, concave en arrière","Une cyphose, convexe en arrière","Une inversion de la courbure lombaire","Absente, le dos étant plat"],"r":1,"e":"Dorsale : cyphose ; protège les organes thoraciques.","s":11},{"q":"Les courbures vertébrales physiologiques :","o":["Diminuent la résistance aux compressions axiales","Augmentent la résistance aux compressions","N'ont aucun effet sur la résistance","Augmentent les contraintes sur les disques"],"r":1,"e":"Courbures = ↑ résistance aux compressions (Kapandji). Ce sont les compressions axiales, selon Kapandji.","s":11},{"q":"Le disque intervertébral existe à partir de :","o":["C1","C2","C7","L1"],"r":1,"e":"Pas de disque C0-C1 ni C1-C2 (articulations à pivot). Premier disque = C2-C3.","s":11},{"q":"Le noyau pulpeux à la naissance contient :","o":["50% d'eau","65%","88%","100%"],"r":2,"e":"88% d'eau à la naissance, baisse à ~65% à 77 ans.","s":11},{"q":"L'anneau fibreux est composé de :","o":["Du tissu osseux, organisé en travées spongieuses","Du tissu cartilagineux, organisé en lamelles","Du liquide synovial, dans une capsule","Du muscle, en fibres striées"],"r":1,"e":"Anneau fibreux : tissu cartilagineux organisé en lamelles. Ses fibres sont verticales en périphérie et plus obliques au centre.","s":11},{"q":"Une hernie discale signifie :","o":["Un disque déformé, l'anneau restant intact","Une rupture de l'anneau, avec sortie du noyau","Un glissement d'une vertèbre sur l'autre","Un ostéophyte, ou bec osseux sur le corps vertébral"],"r":1,"e":"Hernie : rupture de l'anneau, expulsion du noyau.","s":11},{"q":"Une protrusion discale :","o":["Un anneau fibreux rompu, noyau sorti","Un disque déformé, l'anneau restant intact","Un disque qui s'épaissit, par absorption d'eau","Une disparition complète du disque"],"r":1,"e":"Protrusion : déformation sans rupture de l'anneau.","s":11},{"q":"Pression intradiscale en décubitus dorsal (unités relatives) :","o":["25","50","100","140"],"r":0,"e":"DD = 25 (basse). Debout = 100. Assis = 140.","s":11},{"q":"Pression intradiscale en position debout :","o":["25","50","100","200"],"r":2,"e":"Debout = 100 (référence).","s":11},{"q":"Pression intradiscale en position assise :","o":["50","100","140","200"],"r":2,"e":"Assis = 140. L'inclinaison antérieure majore davantage.","s":11},{"q":"Sous pression axiale :","o":["100 % à l'anneau, rien au noyau","100 % au noyau, rien à l'anneau","75 % au noyau, 25 % à l'anneau","50 % au noyau, 50 % à l'anneau"],"r":2,"e":"75% supportés par le noyau, 25% par l'anneau. Noyau disperse horizontalement.","s":11},{"q":"En flexion du tronc, le noyau :","o":["Reste central, sans bouger","Se déplace vers l'arrière du disque","Se déplace vers l'avant du disque","Disparaît, par perte d'eau"],"r":1,"e":"Flexion : noyau postérieur, ligaments postérieurs en tension. Les ligaments postérieurs sont mis en tension.","s":11},{"q":"En extension, le noyau :","o":["Se déplace en avant","Se déplace en arrière","Reste central","Vers le haut"],"r":0,"e":"Extension : noyau antérieur, ligaments antérieurs en tension.","s":11},{"q":"En flexion latérale, le noyau se déplace :","o":["Vers la concavité","Vers la convexité","Vers le bas","Aucun déplacement"],"r":1,"e":"Flexion latérale : noyau vers la convexité (côté étiré).","s":11},{"q":"Combinaison à risque maximal de hernie :","o":["Flexion seule, sans charge","Extension seule, avec charge lourde","Rotation, flexion et charge","Position debout, au repos"],"r":2,"e":"Rotation + flexion + charge = risque discal accru.","s":11},{"q":"Le comportement viscoélastique du disque sous charge constante :","o":["Une stabilité de l'épaisseur","Une baisse progressive d'épaisseur, ou creep","Une hausse d'épaisseur, par absorption d'eau du noyau","Une calcification, avec rigidité"],"r":1,"e":"Creep : ↓ taille pendant la journée par perte d'eau du noyau. Elle s'accompagne d'une perte d'eau.","s":11},{"q":"ROM cervicale en flexion :","o":["20°","40°","60°","90°"],"r":1,"e":"Cervicale : flexion ~40°, extension ~75°.","s":11},{"q":"ROM lombaire en flexion :","o":["35°","60°","90°","120°"],"r":1,"e":"Lombaire : flexion ~60°, extension ~35°.","s":11},{"q":"Contenu du foramen de conjugaison :","o":["Artère spinale","Nerf spinal","Tissu adipeux","Moelle épinière","Disque intervertébral"],"r":[0,1,2],"e":"3 éléments : artère spinale, nerf spinal, tissu adipeux.","s":11},{"q":"L'extension diminue :","o":["La dimension verticale du foramen","Augmente le foramen","Aucun effet","Augmente la lordose lombaire"],"r":0,"e":"Extension → ↓ dimension verticale du foramen → risque de compression nerveuse.","s":11},{"q":"La flexion augmente :","o":["La lordose lombaire","Le foramen de conjugaison","La pression sur le nerf","Le contact des facettes"],"r":1,"e":"Flexion → ↑ foramen (utilisée pour soulager la sciatique).","s":11},{"q":"L'artère vertébrale entre dans le foramen transverse à :","o":["C1","C3","C6","T1"],"r":2,"e":"Entrée à C6, traverse les foramen transverses jusqu'à C1.","s":11},{"q":"Quels mouvements ↑ la compression de l'artère vertébrale ?","o":["Flexion + rotation","Extension + rotation cervicale","Inclinaison latérale isolée","Décompression axiale"],"r":1,"e":"Extension + rotation cervicales = ↑ compression artère vertébrale.","s":11},{"q":"Les 5D (Harper et al., 2020) incluent :","o":["Dizziness (vertiges)","Diplopie","Dysarthrie","Dysphagie","Drop attacks","Douleur lombaire"],"r":[0,1,2,3,4],"e":"Les 5D : vertiges, diplopie, dysarthrie, dysphagie, drop attacks (pas de douleur lombaire).","s":11},{"q":"Les 3N (Harper et al., 2020) :","o":["Nausées","Numbness (engourdissements)","Nystagmus","Niveau de conscience","Néoplasie"],"r":[0,1,2],"e":"3N : nausées, numbness, nystagmus.","s":11},{"q":"Le test de Klein/artère vertébrale est :","o":["Recommandé avant toute manipulation","À éviter, un test négatif n'excluant pas le risque","Toujours fiable, avec une très bonne sensibilité","Sans danger, quel que soit le patient"],"r":1,"e":"Test à éviter ; précautions cliniques globales recommandées. Thomas et Treleaven (2020) le déconseillent en raison des risques.","s":11},{"q":"L'articulation sacro-iliaque est :","o":["Cartilagineuse, de type symphyse","Une arthrodie synoviale, qui absorbe la torsion","Fibreuse, de type syndesmose, sans aucune cavité articulaire","Sphéroïde, mobile dans les trois plans"],"r":1,"e":"SI = synoviale stable, sujette à blocages, ankylose après 50 ans.","s":11},{"q":"La nutation correspond à :","o":["Le promontoire vers l'arrière et le haut","Le promontoire vers l'avant et le bas","Une rotation pure du sacrum","Une translation latérale du sacrum entre les iliaques"],"r":1,"e":"Nutation : promontoire vers avant/bas. Contre-nutation = inverse. Le sommet du sacrum part vers l'arrière et le haut.","s":11},{"q":"La musculature statique du rachis assure :","o":["L'équilibre dynamique des gestes volontaires","Un contrôle réflexe des déséquilibres segmentaires","La protection de la moelle épinière","La transmission du poids du corps jusqu'au bassin osseux"],"r":1,"e":"La musculature dynamique assure, elle, l'équilibre dynamique des gestes volontaires conscients.","s":11},{"q":"Selon Kapandji, les courbures vertébrales :","o":["Augmentent la résistance aux compressions axiales","Diminuent la mobilité du rachis entier","Réduisent la protection de la moelle épinière","N'ont aucun rôle mécanique, et seulement un rôle esthétique"],"r":0,"e":"La lordose est une concavité postérieure, la cyphose une convexité postérieure.","s":11},{"q":"Le noyau pulpeux contient, à 77 ans, environ :","o":["88 % d'eau","77 % d'eau","65 % d'eau","50 % d'eau"],"r":2,"e":"Il en contient 88 % à la naissance ; cette déshydratation progressive réduit sa capacité d'amortissement.","s":11},{"q":"Dans l'anneau fibreux, les fibres sont :","o":["Verticales en périphérie et plus obliques au centre","Obliques en périphérie et verticales au centre","Toutes verticales, du bord jusqu'au centre","Toutes horizontales, en couches parallèles"],"r":0,"e":"Il limite les mouvements et absorbe les forces.","s":11},{"q":"La protrusion discale se distingue de la hernie en ce que :","o":["L'anneau reste intact, le disque se déformant","Le noyau sort vers l'extérieur du disque","L'anneau est rompu, le noyau restant en place","Le disque disparaît, par usure"],"r":0,"e":"La hernie correspond à une rupture de l'anneau fibreux avec sortie du noyau.","s":11},{"q":"Selon Andersson & Nachemson (1974), la pression intradiscale en position couchée est de :","o":["25","100","140","75"],"r":0,"e":"Elle vaut 100 debout et 140 assis, et augmente fortement en inclinaison antérieure.","s":11},{"q":"Sous pression axiale, la répartition de la charge est :","o":["50 % noyau et 50 % anneau","75 % noyau et 25 % anneau","25 % noyau et 75 % anneau","100 % anneau"],"r":1,"e":"Le noyau disperse les forces horizontalement.","s":11},{"q":"En flexion latérale, le noyau pulpeux se déplace :","o":["Vers la concavité","Vers la convexité","En avant","En arrière"],"r":1,"e":"En flexion il recule et augmente la tension des ligaments postérieurs, en extension il avance.","s":11},{"q":"La combinaison la plus à risque discal est :","o":["Rotation + flexion + charge","Extension seule","Flexion latérale seule","Rotation seule sans charge"],"r":0,"e":"Les mouvements excessifs ou répétés, surtout en charge, favorisent la formation de hernies.","s":11},{"q":"Le comportement viscoélastique du disque sous charge constante se traduit par :","o":["Une baisse progressive d'épaisseur, ou creep","Un gonflement, par absorption d'eau","Une rigidification, par calcification des lamelles","Aucun changement, ni de forme ni de hauteur"],"r":0,"e":"La décharge en position couchée permet ensuite la réabsorption d'eau, ou recovery. Le noyau perd de l'eau.","s":11},{"q":"L'amplitude de flexion de la colonne cervicale est, selon ce cours, de :","o":["40°","60°","75°","105°"],"r":0,"e":"Son extension atteint 75° ; la région lombaire fléchit à 60° et s'étend à 35°.","s":11},{"q":"Le foramen de conjugaison est limité en arrière par :","o":["Le disque et les corps vertébraux","Les articulations interapophysaires","Les pédicules","Les lames"],"r":1,"e":"Il est limité en avant par le disque et les corps vertébraux, en bas par les pédicules.","s":11},{"q":"Le foramen de conjugaison contient :","o":["L'artère spinale, le nerf spinal et du tissu adipeux","La moelle épinière, avec ses méninges","L'artère vertébrale, avec son plexus veineux et sympathique","Le ligament jaune, en arrière du canal"],"r":0,"e":"Le nerf peut y être comprimé par une protrusion ou hernie, une hypertrophie articulaire, ou la combinaison des deux.","s":11},{"q":"La flexion agit sur le foramen de conjugaison en :","o":["Diminuant sa dimension verticale","Augmentant sa dimension verticale","Le fermant complètement","N'ayant aucun effet"],"r":1,"e":"L'extension le diminue, et la flexion latérale l'augmente du côté opposé tout en le diminuant du même côté.","s":11},{"q":"L'artère vertébrale entre dans le foramen transverse au niveau de :","o":["C1","C4","C6","C7"],"r":2,"e":"Elle passe ensuite derrière les apophyses transverses ; extension et rotation cervicale augmentent sa compression.","s":11},{"q":"Parmi les endroits à risque pour l'artère vertébrale, le cours cite :","o":["Les trous transversaux de C2 à C6 et la jonction C1-C2","Le seul niveau C7, à la jonction cervico-dorsale","La jonction cervico-dorsale en regard de T1","Le foramen magnum uniquement, au niveau C0"],"r":0,"e":"La rotation en C1/C2 rétrécit particulièrement l'espace. L'articulation C0-C1 et le trajet initial sous-clavier en font aussi partie.","s":11},{"q":"Selon Thomas & Treleaven (2020), le test de l'artère vertébrale :","o":["Doit être évité, un test négatif n'excluant pas le risque","Est obligatoire avant toute manipulation, même du rachis lombaire","Est très spécifique, et donc fiable","Remplace l'imagerie, en première intention"],"r":0,"e":"C'est un test de provocation, dont le rapport bénéfice/risque est défavorable.","s":11},{"q":"Parmi les 5D de Harper et al. (2020) figurent :","o":["Vertiges, diplopie, dysarthrie et dysphagie","Douleur, dyspnée, dysurie et diarrhée","Dyskinésie, dystonie, dyspraxie et dysgraphie","Déficit moteur, douleur, dysesthésie et dysménorrhée"],"r":0,"e":"Les drop attacks sont des chutes sans perte de conscience ; les 3N sont nausées, engourdissements et nystagmus. Les drop attacks complètent les 5D.","s":11},{"q":"Les 3N de Harper et al. (2020) désignent :","o":["Nausées, engourdissements et nystagmus","Névralgie, neuropathie et nécrose","Nausées, nystagmus et névrite du nerf optique","Nausées, nervosité et nystagmus"],"r":0,"e":"Ils complètent les 5D dans le dépistage d'une atteinte vertébro-basilaire. En anglais, engourdissement se dit numbness.","s":11},{"q":"Parmi les mouvements accessoires de la colonne dorsale, le cours cite :","o":["Les postéro-antérieurs unilatéraux costo-vertébraux","Les transverses au niveau de l'atlas","Les longitudinaux céphaliques","Les rotations pures du corps vertébral, sans glissement"],"r":0,"e":"S'y ajoutent les postéro-antérieurs sur les épineuses, les unilatéraux sur les transverses, les transverses et le longitudinal caudal.","s":11},{"q":"Posture vient du latin :","o":["Postura, la position ou l'attitude","Pondus, le poids ou la charge du corps","Posto, la place ou l'endroit","Postulatum, la demande"],"r":0,"e":"Posture = positura (position/attitude dans l'espace).","s":12},{"q":"La posture est :","o":["Toujours fixe, chez un même sujet","Variable, selon les positions et le temps","Inchangeable après 25 ans, une fois fixée","Dépendante uniquement du sexe, à tout âge de la vie"],"r":1,"e":"Posture dynamique ; évolue avec l'âge, l'activité, le temps.","s":12},{"q":"La posture statique est caractérisée par :","o":["Des mouvements rapides, avec élan","La gravité, le tonus et un contrôle automatique","Une position toujours debout, jamais assise","Aucun engagement musculaire, le corps étant au repos"],"r":1,"e":"Statique : maintien (debout, assis) sous l'action de la gravité.","s":12},{"q":"La posture dynamique implique :","o":["Un repos absolu, sans mouvement","Des ajustements anticipatifs et réactifs","Le sommeil en position allongée","Une apnée, pour bloquer le tronc pendant l'effort"],"r":1,"e":"Dynamique : mouvement, ajustements posturaux constants. Elle comprend des accélérations et des décélérations.","s":12},{"q":"Critères d'une bonne posture :","o":["Le centre de gravité dans la base d'appui","Des mouvements efficaces","Une charge symétrique sur les articulations","Une moindre dépense énergétique","Une forme harmonieuse du visage","Le bon fonctionnement des organes thoraciques"],"r":[0,1,2,3,5],"e":"5 critères : CG dans BA, mouvements efficaces, charge symétrique, dépense énergétique minimale, organes thoraciques OK.","s":12},{"q":"Alignement idéal de Kendall (plan latéral) :","o":["Sommet suture coronale","Méat auditif externe","Articulation de l'épaule","Légèrement en arrière du grand trochanter","Légèrement en avant du genou","Au milieu de la jambe"],"r":[0,1,2,3,4],"e":"Tous sauf 'milieu de la jambe' (ce serait imprécis ; on parle de malléole).","s":12},{"q":"Le fil à plomb passe légèrement :","o":["Au-dessus du grand trochanter","En arrière du grand trochanter","En avant du grand trochanter","Au centre"],"r":1,"e":"Légèrement en arrière du grand trochanter (axe coxo-fémoral).","s":12},{"q":"Au niveau du genou, le fil à plomb passe :","o":["En arrière de l'articulation","Légèrement en avant de l'articulation","Au milieu exact de l'articulation, sur l'axe","Au-dessus de la rotule"],"r":1,"e":"Légèrement en avant du genou (pour maintenir l'extension passive).","s":12},{"q":"Au niveau de la cheville, le fil à plomb passe :","o":["En arrière de la malléole interne, près du talon","Légèrement en avant de la malléole externe","Au milieu du pied, sur l'arche interne","Sur le talon, au point d'appui"],"r":1,"e":"Légèrement en avant de la malléole externe.","s":12},{"q":"Causes des modifications posturales :","o":["Traumatismes","Faiblesse neuromusculaire","Problèmes psycho-émotionnels","Malnutrition / obésité","Couleur des cheveux","Dysmétrie des MI"],"r":[0,1,2,3,5],"e":"5 causes parmi les 6 listées. La couleur des cheveux n'a pas d'incidence.","s":12},{"q":"Combien de plans pour l'évaluation posturale ?","o":["1, de face uniquement, en vue antérieure","2, de face et de dos","4, de face, de dos et des deux profils","6, avec les vues obliques"],"r":2,"e":"4 plans : antérieur, postérieur, latéral gauche, latéral droit.","s":12},{"q":"Ordre habituel de l'évaluation :","o":["Aléatoire, selon l'examinateur","Céphalo-caudal ou caudal-céphalique","Toujours le profil latéral d'abord","Toujours le dos en premier"],"r":1,"e":"Évaluation systématique de haut en bas (ou inverse).","s":12},{"q":"Au plan antérieur, on évalue :","o":["Symétrie du visage et yeux","Niveau des clavicules","Mamelons et sternum","EIAS et crêtes iliaques","Position des MI (varus/valgus)","Position de la moelle épinière"],"r":[0,1,2,3,4],"e":"Tous sauf la moelle (interne).","s":12},{"q":"L'angle Q normal est :","o":["Inférieur à 5°, chez l'homme comme chez la femme","Inférieur à 15° environ, un peu plus chez la femme","Supérieur à 30°, quel que soit le sexe","Toujours égal à 0°, en alignement parfait"],"r":1,"e":"Angle Q : EIAS – centre rotule – tubérosité tibiale. < 15° normal. Il est de 10 à 14° chez l'homme et de 15 à 17° chez la femme.","s":12},{"q":"Une scoliose POSTURALE :","o":["Courbure > 10° avec rotation","Attitude scoliotique réductible","Toujours évolutive","Avec hémivertèbre"],"r":1,"e":"Posturale : la colonne reste souple, retrouve sa forme. Pas de rotation vraie.","s":12},{"q":"Une scoliose STRUCTURELLE est définie par :","o":["Une courbure latérale de moins de 10°","Une courbure de plus de 10° avec rotation vertébrale","Une courbure aisément réductible, en se penchant","Une position temporaire, liée à une douleur"],"r":1,"e":"Structurelle : > 10° + rotation vertébrale. Tendance évolutive. Elle a tendance à évoluer.","s":12},{"q":"L'angle crânio-vertébral C7-Tragus normal :","o":["20-30°","50-55°","70-80°","90-100°"],"r":1,"e":"50-55° normal. < 50° = antériorisation.","s":12},{"q":"Antériorisation de la tête : lobe oreille par rapport à acromion :","o":["En arrière","En avant","Au même niveau","Au-dessus"],"r":1,"e":"Lobe en avant de l'acromion = antériorisation.","s":12},{"q":"Pour 2-3 cm d'avancée de la tête, tension supplémentaire :","o":["1-2 kg","3-5 kg","7-14 kg","30 kg"],"r":2,"e":"7-14 kg de tension musculaire supplémentaire pour 2-3 cm.","s":12},{"q":"Posture cyphotique-lordotique : caractéristiques principales :","o":["↓ cyphose, ↓ lordose et bassin en rétroversion","↑ cyphose, ↑ lordose et bassin en antéversion","Une lordose rectifiée, avec un dos plat","Un bassin en rétroversion, avec des genoux en hyperextension"],"r":1,"e":"Cyphose-lordose : ↑ cyphose + ↑ lordose + bascule antérieure du bassin.","s":12},{"q":"Muscles faibles dans la cyphotique-lordotique :","o":["Pectoraux, fléchisseurs de hanche et érecteurs lombaires","Abdominaux, fessiers, rhomboïdes et trapèze moyen","Quadriceps et ischio-jambiers, en chaîne","Triceps et deltoïdes, aux membres supérieurs"],"r":1,"e":"Faibles : abdos, fessiers, rhomboïdes, trapèze moyen (chaînes postérieures et stabilisateurs).","s":12},{"q":"Posture flat back :","o":["↑ lordose lombaire, avec bassin en antéversion","↓ cyphose, lordose rectifiée et bassin en rétroversion","Hyperlordose lombaire, avec une cyphose dorsale accentuée","Bassin en antéversion, avec genoux fléchis"],"r":1,"e":"Flat back : courbures rectifiées, bascule postérieure du bassin.","s":12},{"q":"Muscles faibles dans la flat back :","o":["Les fléchisseurs de hanche et les extenseurs lombaires","Les abdominaux et les extenseurs de hanche","Les quadriceps et les triceps suraux","Aucun muscle, la posture étant purement passive et osseuse"],"r":0,"e":"Fléchisseurs hanche + extenseurs lombaires = faibles.","s":12},{"q":"Posture sway-back :","o":["Tête centrée, bassin en arrière et genoux fléchis en appui","Tête en avant, bassin avancé et genoux en hyperextension","Lordose lombaire augmentée, tête alignée","Genoux fléchis, tête et bassin alignés"],"r":1,"e":"Sway-back : tête avant, bassin déplacé antérieurement, hyperextension genoux. Le bassin est aussi en inclinaison postérieure.","s":12},{"q":"Muscles faibles dans la sway-back :","o":["Quadriceps et ischio-jambiers, en chaîne","Fessiers et extenseurs dorsaux","Les abdominaux uniquement","Trapèze supérieur et deltoïde"],"r":1,"e":"Faibles : fessiers et extenseurs dorsaux.","s":12},{"q":"Équilibre du bassin (latéral) — vers l'avant :","o":["Les abdominaux, vers le haut","Les fléchisseurs de hanche, vers le bas","Les extenseurs du rachis, vers le haut","Les fessiers, vers le bas"],"r":[0,1],"e":"Avant : abdos haut + fléchisseurs hanche bas.","s":12},{"q":"Équilibre du bassin — vers l'arrière :","o":["Les extenseurs du rachis, vers le haut","Les extenseurs de hanche, vers le bas","Les fléchisseurs de hanche, vers le bas","Les abdominaux, vers le haut"],"r":[0,1],"e":"Arrière : extenseurs rachis haut + extenseurs hanche bas.","s":12},{"q":"Le test d'Adam (flexion avant) recherche :","o":["Une hernie discale, par la douleur provoquée","Une scoliose structurelle, par la gibbosité","La force des muscles lombaires","La souplesse des ischio-jambiers"],"r":1,"e":"Adam : flexion avant → asymétrie costale (gibbosité) = scoliose structurelle.","s":12},{"q":"Outils d'évaluation posturale :","o":["Test d'Adam","Photogrammétrie posturale","Miroir avec lignes","Scanner cérébral","Goniomètre"],"r":[0,1,2],"e":"3 outils principaux : Adam, photogrammétrie, miroir avec lignes.","s":12},{"q":"L'ergonomie étudie :","o":["L'anatomie du corps humain, au poste de travail","Les interactions entre l'humain et un système","Les médicaments, et leurs effets au travail","La biomécanique pure, sans l'environnement"],"r":1,"e":"Ergonomie : interactions humain-système pour optimiser bien-être et performance. Elle vise à optimiser le bien-être et la performance.","s":12},{"q":"Le mot posture vient du latin :","o":["Positura, signifiant position ou attitude","Postura, signifiant équilibre du corps","Ponere, signifiant poser ou placer","Statura, signifiant stature ou taille"],"r":0,"e":"Elle désigne la position que le corps adopte dans l'espace, et la disposition des segments par rapport au centre de gravité.","s":12},{"q":"La posture recherche un alignement des segments :","o":["Avec le moindre coût énergétique et biomécanique","Avec la force maximale, quel que soit le coût énergétique","Sans rapport avec la dépense énergétique du corps","Fixe dans le temps, quelle que soit l'activité"],"r":0,"e":"Elle n'est pas fixe : elle change avec les positions, les mouvements et le temps.","s":12},{"q":"La posture statique se caractérise par :","o":["La gravité, un alignement maintenu et le tonus","Des accélérations et des décélérations, en mouvement","Des ajustements anticipatifs, avant le geste","Le mouvement, avec des ajustements réactifs"],"r":0,"e":"La posture dynamique implique mouvement, accélération/décélération et ajustements anticipatifs et réactifs. Le contrôle est automatique.","s":12},{"q":"Parmi les critères d'une bonne posture, le cours cite :","o":["Une charge symétrique et une moindre dépense énergétique","La seule symétrie visuelle, vue de face et de dos","La seule verticalité au fil à plomb","La seule absence de douleur, au repos et à l'effort"],"r":0,"e":"Ce dernier critère rappelle que la posture a aussi des conséquences viscérales. Le centre de gravité dans la base d'appui, des mouvements efficaces et le bon fonctionnement des organes thoraciques et abdominaux en font aussi partie.","s":12},{"q":"Dans l'alignement idéal de Kendall, la ligne passe au niveau du crâne :","o":["Au sommet exact de la suture coronale","Légèrement en arrière de la suture coronale","Légèrement en avant du sommet de la suture coronale","Au vertex, au point le plus haut du crâne"],"r":1,"e":"Elle passe ensuite par le méat auditif externe, les corps vertébraux cervicaux et lombaires et l'articulation de l'épaule. Elle passe en arrière de son sommet.","s":12},{"q":"Au niveau de la hanche, la ligne d'aplomb de Kendall passe :","o":["Légèrement en arrière du grand trochanter","Légèrement en avant du grand trochanter","Sur le grand trochanter","Au centre du bassin"],"r":0,"e":"Elle passe ensuite légèrement en avant du genou et légèrement en avant de la malléole externe.","s":12},{"q":"Parmi les causes de modifications posturales, le cours cite :","o":["Les traumatismes, la faiblesse neuromusculaire et l'obésité","La seule faiblesse musculaire, quelle qu'en soit la cause","Le seul âge, avec le vieillissement des disques et des muscles","La seule génétique, transmise par les parents"],"r":0,"e":"S'y ajoutent le repos inadéquat, la fatigue chronique, la diminution de souplesse, la dysmétrie des membres inférieurs et les cicatrices. Les problèmes psycho-émotionnels, la malnutrition et les facteurs environnementaux en font aussi partie.","s":12},{"q":"L'évaluation posturale se conduit selon :","o":["Quatre plans, de face, de dos et des deux profils","Deux plans, de face et de dos","Trois plans, de face, de dos et d'un profil","Un seul plan, de profil, au fil à plomb et sur une grille"],"r":0,"e":"L'ordre peut être céphalo-caudal ou caudal-céphalique.","s":12},{"q":"Au plan antérieur, on recherche notamment :","o":["Un pectus carinatum ou excavatum, ou un thorax en tonneau","Les épines iliaques postéro-supérieures, de part et d'autre","L'alignement des apophyses épineuses, de haut en bas","Le tendon d'Achille, et l'axe du calcanéum"],"r":0,"e":"On y évalue aussi la symétrie du visage, le niveau des yeux, des clavicules et des mamelons, les EIAS et la position des membres inférieurs.","s":12},{"q":"Une scoliose structurelle se définit par :","o":["Une courbure de plus de 10°, avec rotation vertébrale","Une simple attitude, corrigeable en position couchée","Une courbure latérale de moins de 10°, sans rotation","Une cyphose dorsale majorée, avec une gibbosité en flexion"],"r":0,"e":"Elle a tendance à évoluer, à la différence de la scoliose posturale où la colonne reste souple et retrouve sa forme.","s":12},{"q":"L'angle crânio-vertébral C7-tragus est considéré comme normal entre :","o":["40 et 45°","50 et 55°","60 et 65°","30 et 40°"],"r":1,"e":"En dessous de 50°, on parle d'antériorisation de la tête.","s":12},{"q":"L'antériorisation de la tête se repère par :","o":["Le lobe de l'oreille en avant de l'acromion","Le lobe de l'oreille en arrière de l'acromion","L'alignement parfait","La position du menton"],"r":0,"e":"Pour 2 à 3 cm d'avancée, la tension supplémentaire est de 7 à 14 kg.","s":12},{"q":"La posture cyphotique-lordotique associe :","o":["Une cyphose dorsale et une lordose lombaire augmentées","Une rectification de la lordose lombaire","Une bascule postérieure du bassin, en rétroversion","Une diminution de la cyphose, avec un bassin en rétroversion"],"r":0,"e":"Les muscles faibles y sont les abdominaux, les fessiers, les rhomboïdes et le trapèze moyen. S'y ajoutent tête en avant, hyperextension cervicale, abduction des omoplates, bascule antérieure du bassin et hyperextension des genoux.","s":12},{"q":"Dans la posture flat back, les muscles faibles sont :","o":["Les abdominaux, les fessiers et les rhomboïdes","Les fléchisseurs de hanche et les extenseurs lombaires","Les fessiers et les extenseurs dorsaux, en chaîne postérieure","Les rhomboïdes et le trapèze moyen"],"r":1,"e":"Elle associe tête en avant, extension cervicale, cyphose diminuée, rectification de la lordose, bascule postérieure du bassin et extension des genoux.","s":12},{"q":"Dans la posture sway-back, les muscles faibles sont :","o":["Les fessiers et les extenseurs dorsaux","Les abdominaux et les rhomboïdes","Les fléchisseurs de hanche","Les extenseurs lombaires"],"r":0,"e":"Elle associe tête en avant, hyperextension cervicale, cyphose augmentée, légère extension lombaire, déviation antérieure du bassin et hyperextension des genoux.","s":12},{"q":"Dans l'équilibre du bassin, les muscles qui le tirent vers l'avant sont :","o":["Les abdominaux et les fléchisseurs de hanche","Les extenseurs du rachis et les extenseurs de la hanche","Les fessiers seuls, par leur tension","Les abdominaux seuls, vers le haut"],"r":0,"e":"Vers l'arrière, les extenseurs du rachis tirent vers le haut et les extenseurs de hanche vers le bas. Les abdominaux tirent vers le haut et les fléchisseurs de hanche vers le bas.","s":12},{"q":"Le test de flexion avant d'Adam recherche :","o":["Une scoliose structurelle","Une cyphose","Une antériorisation de la tête","Une dysmétrie"],"r":0,"e":"Photogrammétrie posturale et miroir avec lignes complètent les outils d'évaluation.","s":12},{"q":"L'ergonomie se définit comme l'étude :","o":["Des interactions entre l'humain et les éléments d'un système","De la posture statique seule, au poste de travail","Du mobilier de bureau, et de son réglage en hauteur au poste","Des troubles musculo-squelettiques liés au travail"],"r":0,"e":"Le mobilier, les chaussures et les conditions de travail figurent parmi les facteurs environnementaux de modification posturale. Elle vise à optimiser le bien-être et la performance.","s":12},{"q":"L'angle Q est considéré comme normal, en évaluation posturale, en dessous de :","o":["10°","15°","20°","25°"],"r":1,"e":"Il s'évalue au plan antérieur, avec la position des membres inférieurs en varus ou valgus.","s":12},{"q":"La posture est décrite comme favorisant :","o":["Le confort et un soutien économique et harmonieux","La force maximale, en toute situation","La souplesse maximale des articulations","L'immobilité, pour économiser l'énergie et les articulations"],"r":0,"e":"Cela découle de la recherche du moindre coût énergétique et biomécanique.","s":12},{"q":"Que signifie la « force » musculaire selon le cours ?","o":["La taille du muscle au repos, en section transversale","La capacité d'un muscle à générer une tension","La résistance du muscle à l'étirement passif","La quantité d'ATP stockée dans les fibres"],"r":1,"e":"La force est une qualité physique de caractéristique neuromusculaire. Elle s'exerce dans un temps et à une vitesse donnés.","s":13},{"q":"Plus le nombre d'unités motrices activées est élevé...","o":["...plus la fatigue diminue","...plus la force développée est importante","...plus la vitesse de contraction diminue","...plus la taille du muscle augmente immédiatement"],"r":1,"e":"Le nombre d'unités motrices recrutées détermine la force produite.","s":13},{"q":"Le test musculaire manuel est né dans le contexte de l'étude de quelle pathologie ?","o":["La sclérose en plaques","La myopathie de Duchenne","La poliomyélite","Les AVC"],"r":2,"e":"Études du début du XXe siècle aux États-Unis. Robert W. Lovett a introduit la méthode utilisant la résistance à la gravité.","s":13},{"q":"Qui a introduit la méthode de test utilisant la résistance à la gravité ?","o":["Henry Kendall","Robert W. Lovett","Daniels & Worthingham","George Maitland"],"r":1,"e":"Lovett a posé les bases du testing manuel utilisant la gravité comme résistance.","s":13},{"q":"La méthode de Daniels & Worthingham teste principalement :","o":["L'activité groupée des muscles d'un mouvement","L'action d'un muscle spécifique, isolé de ses synergistes","L'endurance musculaire uniquement, sur répétitions","La proprioception articulaire des membres"],"r":0,"e":"Daniels & Worthingham : groupes musculaires. Kendall & McCreary : muscles spécifiques.","s":13},{"q":"Selon la méthode Kendall & McCreary, combien de tests sont nécessaires pour évaluer les abducteurs de la hanche ?","o":["1 test, pour tous les abducteurs ensemble","2 tests, un par fessier","3 tests, un par muscle abducteur","4 tests, avec le piriforme"],"r":2,"e":"Chaque muscle abducteur est isolé : moyen fessier, TFL, petit fessier.","s":13},{"q":"Quel est l'avantage principal de la méthode Daniels & Worthingham ?","o":["Plus précise pour identifier les substitutions","Plus pratique et rapide pour un dépistage","Permet de tester chaque muscle séparément","Évite les compensations"],"r":1,"e":"Daniels & Worthingham est plus rapide, surtout en dépistage.","s":13},{"q":"Les auteurs phares dont provient la plupart des tests musculaires manuels modernes sont :","o":["Cyriax, Maitland et Paris","Henry O. et Florence P. Kendall","Janda, Lewit et Kolář","Mulligan, McKenzie et Cyriax"],"r":1,"e":"Auteurs de Muscles: Testing and Function.","s":13},{"q":"Pour garantir la fiabilité du test musculaire manuel, il faut :","o":["Effectuer chaque test au moins 5 fois, puis faire la moyenne","Utiliser systématiquement un dynamomètre électronique","Les réaliser de la même manière, au même point d'amplitude","Toujours tester le côté affecté en premier"],"r":2,"e":"La standardisation est la condition de la reproductibilité.","s":13},{"q":"Lequel de ces facteurs n'influence PAS la reproductibilité d'un test musculaire ?","o":["La méthode utilisée","Le ton de la voix du thérapeute","La fatigue du patient","La couleur des vêtements du patient"],"r":3,"e":"Tous les autres sont listés comme facteurs influençants.","s":13},{"q":"L'amplitude de test correspond à :","o":["L'amplitude maximale du segment, dans toutes les directions","L'amplitude spécifique au muscle testé","L'amplitude minimale utile en clinique","L'amplitude active uniquement, sans aide"],"r":1,"e":"L'amplitude de test est spécifique à chaque muscle. Elle ne coïncide pas forcément avec l'amplitude de mouvement.","s":13},{"q":"Comment doit-on positionner les muscles biarticulaires lors du test ?","o":["À leur position d'allongement maximal","À leur position de raccourcissement maximal, en fin de course","À la position intermédiaire de leur amplitude totale","En appui contre la gravité, segment pendant"],"r":2,"e":"Les biarticulaires sont évalués à la position intermédiaire pour éviter une perte de tension active.","s":13},{"q":"Lors du test, le segment proximal doit être :","o":["Mobilisé activement par le patient","Stabilisé","Étiré au maximum","Maintenu en flexion"],"r":1,"e":"La stabilisation du segment proximal isole le mouvement testé.","s":13},{"q":"Quel type de contraction est requis lors du test musculaire manuel à la fin de l'amplitude ?","o":["Isotonique concentrique","Isotonique excentrique","Isométrique","Isocinétique"],"r":2,"e":"Test isométrique en fin d'amplitude pour mesurer la force statique maximale.","s":13},{"q":"La résistance doit être appliquée :","o":["Avec une seule main, l'autre stabilisant","Avec les deux mains, pour mieux contrôler","Toujours sur l'articulation, pour plus de bras de levier","Très rapidement, et de façon brusque"],"r":0,"e":"Une main pour la résistance, une main pour la stabilisation. Jamais sur l'articulation.","s":13},{"q":"Que signifie un degré 0 ?","o":["Aucune contraction perceptible","Contraction ressentie sans mouvement","Mouvement complet sans gravité","Mouvement complet avec résistance maximale"],"r":0,"e":"Degré 0 = absence totale de contraction.","s":13},{"q":"Que signifie un degré 1 ?","o":["Aucune contraction","Contraction ressentie mais sans mouvement","Mouvement complet contre gravité","Mouvement complet contre résistance modérée"],"r":1,"e":"Degré 1 = contraction perceptible (palpation), pas de mouvement.","s":13},{"q":"Que signifie un degré 3 ?","o":["Un mouvement contre une résistance maximale","Un mouvement avec la gravité éliminée","Une amplitude complète contre la seule gravité","Aucune contraction visible ni palpable du muscle testé"],"r":2,"e":"3 = ROM complète contre gravité, sans résistance externe ajoutée.","s":13},{"q":"Que signifie un degré 5 ?","o":["Position complète sans résistance","Position complète avec résistance modérée","Test complet et résistance maximale","Test impossible à effectuer"],"r":2,"e":"Degré 5 correspond à la force normale, résistance maximale.","s":13},{"q":"Comment doivent être notés les degrés inférieurs à 3 ?","o":["En noir","En rouge","En bleu","En vert"],"r":1,"e":"Convention : < 3 en rouge, ≥ 3 en noir.","s":13},{"q":"Pour tester un muscle faible qui ne peut pas vaincre la gravité, on utilise :","o":["Une position contre la gravité, avec résistance","Une position dans le plan horizontal, sans gravité","Une position pendante, segment relâché","Une posture en suspension, dans des sangles élastiques"],"r":1,"e":"Plan horizontal pour éliminer l'effet gravitaire chez le muscle faible (degrés 0-2).","s":13},{"q":"Lequel de ces facteurs PEUT diminuer la force musculaire ?","o":["L'augmentation de la masse maigre","L'entraînement régulier et progressif","La douleur ressentie pendant le test","Une bonne hydratation de base"],"r":2,"e":"Atrophie, atteinte SN, douleur, fatigue, lésion musculaire diminuent la force.","s":13},{"q":"Chez la personne âgée, on observe une perte de fibres préférentiellement :","o":["De type I (lentes)","De type II (rapides)","De type III","Toutes au même rythme"],"r":1,"e":"Atteinte préférentielle des fibres de type II → ralentissement, perte d'explosivité.","s":13},{"q":"Les conséquences neuromusculaires du vieillissement incluent :","o":["Une augmentation du nombre de motoneurones","Une baisse du nombre et de la taille des unités motrices","Une augmentation de la vitesse de conduction nerveuse motrice","Une hypertrophie des axones, de diamètre accru"],"r":1,"e":"Réduction des UM et de leur taille, diamètre axonal réduit, conduction plus lente.","s":13},{"q":"Quel objectif n'est PAS un objectif typique du test musculaire ?","o":["Aide au diagnostic différentiel","Pronostic","Suivi du traitement","Mesure de la consommation d'oxygène"],"r":3,"e":"Le test musculaire ne mesure pas la VO2.","s":13},{"q":"Quel est l'inconvénient principal de la méthode Kendall & McCreary ?","o":["Elle est moins fiable que les autres méthodes","Elle est plus longue et exige une anatomie précise","Elle ne permet pas de détecter les substitutions","Elle ne peut pas être utilisée en clinique"],"r":1,"e":"Kendall = précis mais long, requérant des connaissances anatomiques pointues.","s":13},{"q":"Avant le test, on doit :","o":["Faire courir le patient pour échauffer le muscle","Expliquer la procédure et la démontrer au patient","Donner un antalgique avant de commencer","Tester d'abord le membre douloureux, sans prévenir le patient"],"r":1,"e":"Communication et préparation = base de la coopération.","s":13},{"q":"Lors du test, l'utilisation de leviers longs :","o":["Est recommandée autant que possible","Est interdite","Est utilisée uniquement chez l'enfant","N'a pas d'incidence"],"r":0,"e":"Levier long = meilleure mécanique, sauf si la fixation proximale est impossible.","s":13},{"q":"Quelle compétence n'est PAS essentielle chez l'observateur ?","o":["Connaissances anatomiques","Compétences techniques","Expérience clinique","Capacité à courir un marathon"],"r":3,"e":"L'observateur a besoin de compétences cognitives et techniques.","s":13},{"q":"Lequel de ces effets fait partie des adaptations positives à l'exercice chez la personne âgée ?","o":["Une diminution du volume musculaire, par atrophie","Une réduction du nombre d'unités motrices","Des adaptations neuronales et un remodelage","Une atrophie sélective des fibres de type I"],"r":2,"e":"L'exercice induit augmentation du volume musculaire, remodelage et adaptations neuronales. Le remodelage est musculaire.","s":13},{"q":"La force se définit dans le cours comme la capacité à générer une tension :","o":["Dans un temps donné et à une vitesse donnée","Sans aucune limite de temps, quelle que soit la vitesse","Indépendamment de la vitesse du mouvement","À vitesse maximale uniquement, sans durée"],"r":0,"e":"C'est une qualité physique de caractéristique neuromusculaire.","s":13},{"q":"Le test musculaire évalue trois capacités :","o":["Activer les muscles, produire un mouvement et stabiliser","La force, l'endurance et la puissance du muscle","L'amplitude, la force et la souplesse articulaire","La coordination, l'équilibre et la vitesse du geste"],"r":0,"e":"Le muscle joue en effet, outre le mouvement, un rôle de soutien des structures squelettiques. Stabiliser revient aussi à soutenir les structures.","s":13},{"q":"Le cours énonce qu'un muscle doit être :","o":["Le plus long possible, pour la mobilité","Assez long pour la mobilité, assez court pour la stabilité","Le plus court possible, pour la stabilité articulaire maximale","De longueur indifférente, seule la force comptant"],"r":1,"e":"C'est ce double impératif qui fonde l'évaluation de la longueur autant que de la force.","s":13},{"q":"Les trois utilisations cliniques du test musculaire sont :","o":["Diagnostic, pronostic et traitement","Dépistage, prévention et suivi","Recherche, enseignement et clinique","Force, endurance et puissance"],"r":0,"e":"Le diagnostic vise le différentiel des troubles neuromusculaires et musculo-squelettiques.","s":13},{"q":"Le test musculaire manuel est né :","o":["Aux États-Unis, au début des années 1900","En Europe, dans les années 1950","Au Japon, dans les années 1970","En Australie, au cours des années 1980"],"r":0,"e":"Robert W. Lovett y a introduit la méthode utilisant la résistance à la gravité. C'était lors d'une étude sur la poliomyélite.","s":13},{"q":"La méthode Daniels & Worthingham teste :","o":["L'action d'un muscle spécifique, isolé de ses synergistes","L'activité musculaire groupée d'un mouvement","La seule endurance, sur répétitions","La seule amplitude articulaire"],"r":1,"e":"Kendall & McCreary testent, eux, l'action d'un muscle spécifique — d'où trois tests séparés pour les abducteurs de hanche.","s":13},{"q":"L'inconvénient principal de la méthode Kendall & McCreary est :","o":["Son manque de spécificité, faute de tester chaque muscle","Sa durée, et l'exigence d'une anatomie précise","Son imprécision, liée à la cotation","Son coût, lié au matériel nécessaire"],"r":1,"e":"Daniels & Worthingham est au contraire plus pratique et rapide pour un dépistage, mais moins spécifique. Il faut connaître l'orientation précise de chaque muscle.","s":13},{"q":"Les auteurs de Muscles: Testing and Function sont :","o":["Henry et Florence Kendall","Daniels et Worthingham","Lovett et Cyriax","Janda et Kaltenborn"],"r":0,"e":"La plupart des tests musculaires modernes en proviennent.","s":13},{"q":"La fiabilité inter- et intra-examinateurs n'est garantie que si les tests sont réalisés :","o":["De la même manière, au même point de l'amplitude","Par le même examinateur, à chaque séance","Avec le même instrument, étalonné avant chaque mesure","Au même moment de la journée, le matin"],"r":0,"e":"Le problème central reste la variable « cadre de référence » utilisée pour l'évaluation.","s":13},{"q":"Parmi les facteurs de variabilité liés à la technique, le cours cite :","o":["Le point d'application de la résistance, sa vitesse, sa durée","La seule méthode employée, Kendall ou Daniels","La seule fatigue du patient, en fin de séance","La seule expérience de l'observateur, débutant ou expert"],"r":0,"e":"S'y ajoutent des facteurs liés au patient et à l'observateur. La ligne d'application, l'amplitude, les instructions et le ton de la voix en font aussi partie.","s":13},{"q":"Parmi les facteurs liés au patient figurent :","o":["La coopération, la fatigue, la douleur et l'anxiété","Les connaissances anatomiques, sur l'orientation des fibres","La compétence technique, dans la prise et la résistance","L'expérience clinique, acquise au fil des années"],"r":0,"e":"Les trois derniers items relèvent des facteurs liés à l'observateur. L'interaction thérapeute-patient en fait aussi partie.","s":13},{"q":"L'amplitude de test se distingue de l'amplitude de mouvement en ce qu'elle :","o":["Est propre au muscle testé et diffère souvent d'elle","Est toujours plus grande, quel que soit le muscle","Est toujours plus petite de moitié","Est identique, la mesure étant la même dans les deux cas"],"r":0,"e":"L'amplitude de mouvement est l'espace parcouru de la position neutre à la position extrême.","s":13},{"q":"Les muscles biarticulaires sont testés :","o":["En amplitude complète, d'une extrémité à l'autre","À la position intermédiaire de l'amplitude totale","En position raccourcie maximale","En position allongée maximale"],"r":1,"e":"Les muscles mono-articulaires doivent, eux, compléter l'amplitude articulaire.","s":13},{"q":"Le positionnement du patient pour le test peut être :","o":["En décubitus dorsal, ventral ou latéral, selon la fixation","Exclusivement assis, pieds au sol","Exclusivement debout, en appui bipodal, face au thérapeute assis","Indifférent, au choix du patient"],"r":0,"e":"La stabilisation porte sur le segment proximal à la zone testée.","s":13},{"q":"Lorsque les muscles sont faibles, la zone testée est placée :","o":["Contre la gravité, avec une résistance","En plan horizontal, gravité éliminée","En position déclive, la tête plus basse que le segment","En charge, sur le membre testé"],"r":1,"e":"La position contre gravité s'emploie pour la plupart des muscles du tronc et certains muscles des extrémités.","s":13},{"q":"La contraction demandée lors du test est :","o":["Isotonique concentrique, sur toute l'amplitude","Isométrique, en fin d'amplitude testée","Excentrique, freinant la résistance","Isocinétique, à vitesse constante imposée par une machine"],"r":1,"e":"Elle permet une comparaison reproductible en un point précis de l'amplitude.","s":13},{"q":"Concernant les leviers, le cours recommande de les prendre :","o":["Longs si possible, et courts si la fixation est limitée","Toujours courts, pour protéger l'articulation et le muscle","Toujours longs, quelle que soit la fixation","Indifféremment, selon l'habitude du thérapeute"],"r":0,"e":"Le levier long augmente le moment résistant et affine la discrimination des grades élevés.","s":13},{"q":"Avant le test, la checklist prévoit notamment :","o":["De déterminer passivement l'amplitude du segment","De mesurer la force au dynamomètre, sur chaque muscle","De faire un échauffement complet, à vélo","De réaliser un bilan goniométrique complet"],"r":0,"e":"S'y ajoutent l'explication, l'exposition de la zone, le placement en position initiale, la stabilisation, la palpation et la surveillance des substitutions.","s":13},{"q":"La résistance doit être, selon le cours :","o":["Douce, ferme et graduée","Maximale, dès le début","Brève et brutale","Maintenue longuement"],"r":0,"e":"Il ne faut ni la maintenir trop longtemps ni la répéter, afin d'éviter la fatigue.","s":13},{"q":"Le degré 2 de Lovett correspond à :","o":["Aucune contraction","Une contraction palpable sans mouvement","Une amplitude complète sans gravité","Une amplitude complète contre gravité"],"r":2,"e":"Le degré 3 correspond à l'amplitude complète contre gravité sans résistance, le 4 avec résistance modérée et le 5 avec résistance maximale.","s":13}]};
